interface DashboardProps {
  user: User;
  onNavigate: (page: string) => void;
}

export const Dashboard: React.FC<DashboardProps> = ({ user, onNavigate }) => {
  const evaluations = useMemo(() => DB.evaluations.all(), []);

  const ranking = useMemo(() => {
    const scores = evaluations.reduce((acc, curr) => {
      if (!acc[curr.userId]) {
        acc[curr.userId] = { 
          name: curr.userName, 
          avg: 0, 
          count: 0, 
          best: 0,
          uf: curr.uf,
          city: curr.city
        };
      }
      acc[curr.userId].count++;
      acc[curr.userId].best = Math.max(acc[curr.userId].best, curr.score);
      return acc;
    }, {} as Record<string, { name: string, avg: number, count: number, best: number, uf: string, city: string }>);

    return Object.values(scores)
      .sort((a, b) => b.best - a.best)
      .slice(0, 5);
  }, [evaluations]);

  return (
    <div className="space-y-8 animate-fadeIn">
      {/* Cards de Menu */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
