import React, { useRef, useState, useEffect, useCallback } from 'react';

interface RecorderProps {
  onComplete: (videoBlob: Blob, audioBlob: Blob) => void;
  onCancel: () => void;
}

export const Recorder: React.FC<RecorderProps> = ({ onComplete, onCancel }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const [isRecording, setIsRecording] = useState(false);
  const [recordedBlob, setRecordedBlob] = useState<Blob | null>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const chunks = useRef<Blob[]>([]);

  const startCamera = async () => {
    try {
      const s = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'user' }, 
        audio: true 
      });
      setStream(s);
      if (videoRef.current) {
        videoRef.current.srcObject = s;
      }
    } catch (err) {
      alert("Não foi possível acessar a câmera ou microfone.");
      onCancel();
    }
  };

  useEffect(() => {
    startCamera();
    return () => {
      stream?.getTracks().forEach(track => track.stop());
    };
  }, []);

  const handleStartRecording = () => {
    if (!stream) return;
    chunks.current = [];
    const recorder = new MediaRecorder(stream);
    recorder.ondataavailable = (e) => {
      if (e.data.size > 0) chunks.current.push(e.data);
    };
    recorder.onstop = () => {
      const blob = new Blob(chunks.current, { type: 'video/mp4' });
      setRecordedBlob(blob);
    };
    recorder.start();
    mediaRecorderRef.current = recorder;
    setIsRecording(true);
  };

  const handleStopRecording = () => {
    mediaRecorderRef.current?.stop();
    setIsRecording(false);
  };

  const handleRepeat = () => {
    setRecordedBlob(null);
    startCamera();
  };

  const handleSend = () => {
    if (recordedBlob) {
      onComplete(recordedBlob, recordedBlob); // Simplified: sending same blob for demo
    }
  };

  return (
    <div className="flex flex-col items-center space-y-6 animate-fadeIn">
      <div className="relative w-full aspect-video bg-black rounded-3xl overflow-hidden shadow-2xl">
        {!recordedBlob ? (
          <video 
            ref={videoRef} 
            autoPlay 
            muted 
            playsInline 
            className="w-full h-full object-cover mirror"
          />
        ) : (
          <video 
            src={URL.createObjectURL(recordedBlob)} 
            controls 
            className="w-full h-full object-cover"
          />
        )}

        {isRecording && (
          <div className="absolute top-4 right-4 flex items-center gap-2 bg-red-600 px-3 py-1 rounded-full text-white text-sm font-bold animate-pulse">
            <div className="w-2 h-2 bg-white rounded-full"></div>
            GRAVANDO
          </div>
        )}
      </div>

      <div className="w-full flex justify-center gap-4">
        {!recordedBlob ? (
          !isRecording ? (
            <button 
              onClick={handleStartRecording}
              className="w-20 h-20 rounded-full border-4 border-gray-200 p-1 flex items-center justify-center transition-all hover:border-red-500"
            >
              <div className="w-full h-full bg-[#ee0000] rounded-full flex items-center justify-center">
                <div className="w-6 h-6 bg-white rounded-sm"></div>
              </div>
            </button>
          ) : (
            <button 
              onClick={handleStopRecording}
              className="w-20 h-20 rounded-full border-4 border-gray-200 p-1 flex items-center justify-center"
            >
              <div className="w-full h-full bg-white rounded-full flex items-center justify-center border-4 border-[#ee0000]">
                <div className="w-6 h-6 bg-[#ee0000] rounded-sm"></div>
              </div>
            </button>
          )
        ) : (
          <div className="flex flex-col w-full gap-4 max-w-sm">
            <button 
              onClick={handleSend}
              className="w-full claro-red text-white font-bold py-4 rounded-full shadow-lg"
            >
              ENVIAR PARA AVALIAÇÃO
            </button>
            <button 
              onClick={handleRepeat}
              className="w-full bg-gray-200 text-gray-700 font-bold py-4 rounded-full"
            >
              REPETIR GRAVAÇÃO
            </button>
          </div>
        )}
      </div>

      {!recordedBlob && !isRecording && (
        <p className="text-gray-400 text-sm">Toque no botão central para começar a gravar</p>
      )}
    </div>
  );
};

