}

// Added interface to define the structure of ranking data for type safety
interface RankingEntry {
  name: string;
  avg: number;
  count: number;
  best: number;
  uf: string;
  city: string;
}

export const Dashboard: React.FC<DashboardProps> = ({ user, onNavigate }) => {
  const evaluations = useMemo(() => DB.evaluations.all(), []);

  const ranking = useMemo(() => {
    // Explicitly typed the accumulator to avoid 'unknown' element types when calling Object.values
    const scores = evaluations.reduce((acc: Record<string, RankingEntry>, curr) => {
      if (!acc[curr.userId]) {
        acc[curr.userId] = { 
          name: curr.userName, 
          avg: 0, 
          count: 0, 
          best: 0,
          uf: curr.uf,
          city: curr.city
        };
      }
      acc[curr.userId].count++;
      acc[curr.userId].best = Math.max(acc[curr.userId].best, curr.score);
      return acc;
    }, {} as Record<string, RankingEntry>);

    return Object.values(scores)
      .sort((a, b) => b.best - a.best)
      .slice(0, 5);
  }, [evaluations]);

  return (
    <div className="space-y-8 animate-fadeIn">
      {/* Cards de Menu */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <button 
          onClick={() => onNavigate('consultivo')}
          className="group p-6 bg-white border-2 border-transparent hover:claro-border-red rounded-2xl shadow-sm transition-all text-left flex items-center justify-between"
        >
          <div>
            <h3 className="text-xl font-bold claro-text-red mb-1">Consultivo +</h3>
            <p className="text-gray-500 text-sm">Pratique sua abordagem e receba feedback em tempo real.</p>
            <span className="inline-block mt-3 px-2 py-0.5 bg-green-100 text-green-700 text-[10px] font-bold rounded uppercase">Ativo</span>
          </div>
          <div className="w-12 h-12 rounded-full bg-red-50 flex items-center justify-center text-[#ee0000] group-hover:bg-[#ee0000] group-hover:text-white transition-colors">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14.752 11.168l-3.197-2.132A1 1 0 0010 9.87v4.263a1 1 0 001.555.832l3.197-2.132a1 1 0 000-1.664z" />
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
          </div>
        </button>

        {user.role === 'admin' && (
          <button 
            onClick={() => onNavigate('admin')}
            className="group p-6 bg-white border-2 border-transparent hover:claro-border-red rounded-2xl shadow-sm transition-all text-left flex items-center justify-between"
          >
            <div>
              <h3 className="text-xl font-bold claro-text-red mb-1">Gestão Admin</h3>
