import React, { useState, useEffect, useCallback } from 'react';
import { User, Evaluation as EvalModel, AccessLog } from './types';
import { DB } from './db';
import { Layout } from './components/Layout';
import { Login } from './pages/Login';
import { Register } from './pages/Register';
import { Dashboard } from './pages/Dashboard';
import { Consultivo } from './pages/Consultivo';
import { Recorder } from './pages/Recorder';
import { EvaluationResult } from './pages/EvaluationResult';
import { AdminDashboard } from './pages/AdminDashboard';
import { evaluateExplanation, EvaluationResult as AIResult } from './services/geminiService';

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<string>('login');
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(false);
  const [lastEval, setLastEval] = useState<AIResult | null>(null);

  useEffect(() => {
    // Basic session recovery could go here
    const savedUser = localStorage.getItem('explica_session');
    if (savedUser) {
      const u = JSON.parse(savedUser);
      // Re-fetch from DB to ensure most current data/role
      const freshUser = DB.users.findById(u.id);
      if (freshUser) {
        setUser(freshUser);
        setCurrentPage('dashboard');
      } else {
        localStorage.removeItem('explica_session');
      }
    }
  }, []);

  const handleLogin = (cpf: string, pass: string) => {
    const foundUser = DB.users.findByCpf(cpf);
    if (foundUser && (foundUser.password === pass || foundUser.role === 'admin' || foundUser.role === 'superadmin')) {
      setUser(foundUser);
      localStorage.setItem('explica_session', JSON.stringify(foundUser));

      // Log access
      DB.accesses.add({
        id: Math.random().toString(36).substr(2, 9),
        userId: foundUser.id,
        userName: foundUser.name,
        timestamp: new Date().toISOString(),
        uf: foundUser.uf,
        city: foundUser.city
      });

      setCurrentPage('dashboard');
    } else {
      alert("Credenciais inválidas");
    }
  };

  const handleRegister = (data: Partial<User>) => {
    const newId = `tech-${Math.random().toString(36).substr(2, 9)}`;
    const newUser: User = {
      ...data,
      id: newId,
      role: 'tech',
      createdAt: new Date().toISOString()
    } as User;

    DB.users.add(newUser);
    alert(`Técnico cadastrado com sucesso! ID: ${newId}. Faça login com seu CPF.`);
    setCurrentPage('login');
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('explica_session');
    setCurrentPage('login');
  };

  const handleRecorderComplete = async (video: Blob) => {
    setLoading(true);
    try {
      // Helper to convert blob to base64
      const reader = new FileReader();
      const base64Promise = new Promise<string>((resolve) => {
        reader.onloadend = () => resolve(reader.result as string);
        reader.readAsDataURL(video);
      });

      const base64Video = await base64Promise;
      const result = await evaluateExplanation(base64Video);

      // Save evaluation to DB
      if (user) {
        DB.evaluations.add({
          id: Math.random().toString(36).substr(2, 9),
          userId: user.id,
          userName: user.name,
          timestamp: new Date().toISOString(),
          score: result.score,
          strengths: result.strengths,
          weaknesses: result.weaknesses,
          suggestions: result.suggestions,
          transcript: result.transcript,
          uf: user.uf,
          city: user.city,
          videoUrl: base64Video.slice(0, 100) // Storing truncated URL for storage limits in mock
        });
      }

      setLastEval(result);
      setCurrentPage('result');
    } catch (err) {
      alert("Erro ao avaliar vídeo. Tente novamente.");
    } finally {
      setLoading(false);
    }
  };

  const renderContent = () => {
    if (loading) {
      return (
        <div className="flex flex-col items-center justify-center min-h-[50vh] space-y-4">
          <div className="w-16 h-16 border-4 border-gray-100 border-t-[#ee0000] rounded-full animate-spin"></div>
          <p className="text-[#ee0000] font-bold">A inteligência artificial está analisando sua explicação...</p>
          <p className="text-gray-400 text-sm">Isso pode levar alguns segundos.</p>
        </div>
      );
    }

    switch (currentPage) {
      case 'login':
        return <Login onLogin={handleLogin} onGoToRegister={() => setCurrentPage('register')} />;
      case 'register':
        return <Register onRegister={handleRegister} onBack={() => setCurrentPage('login')} />;
      case 'dashboard':
        return user ? <Dashboard user={user} onNavigate={setCurrentPage} /> : null;
      case 'consultivo':
        return <Consultivo onStart={() => setCurrentPage('recorder')} onBack={() => setCurrentPage('dashboard')} />;
      case 'recorder':
        return <Recorder onComplete={handleRecorderComplete} onCancel={() => setCurrentPage('consultivo')} />;
      case 'result':
        return lastEval ? <EvaluationResult result={lastEval} onFinish={() => setCurrentPage('dashboard')} /> : null;
      case 'admin':
        return user ? <AdminDashboard currentUser={user} /> : null;
      default:
        return <Login onLogin={handleLogin} onGoToRegister={() => setCurrentPage('register')} />;
    }
  };

  return (
    <Layout 
      user={user} 
      onLogout={handleLogout} 
      title={currentPage === 'admin' ? 'Painel Administrativo' : undefined}
    >
      {renderContent()}
    </Layout>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export interface EvaluationResult {
  score: number;
  strengths: string;
  weaknesses: string;
  suggestions: string;
  transcript: string;
}

export const evaluateExplanation = async (videoBase64?: string, audioBase64?: string): Promise<EvaluationResult> => {
  // Using gemini-3-pro-preview for complex reasoning task: evaluating technician performance

  const prompt = `
    Você é um avaliador de excelência de atendimento da Claro.
    Analise a explicação técnica/comercial feita pelo funcionário sobre os produtos Claro (Internet Fibra, Celular 5G, Claro TV+).
    Avalie o vídeo/áudio fornecido.

    Critérios:
    - Clareza na fala.
    - Empatia com o cliente (especialmente idosos).
    - Precisão técnica dos produtos.
    - Argumentação de vendas.

    Retorne o resultado estritamente em JSON.
  `;

  try {
    // FIX: Explicitly type parts as any[] to prevent TS from inferring it as Array<{text: string}>
    const parts: any[] = [
      { text: prompt }
    ];

    if (videoBase64) {
      parts.push({
        inlineData: {
          data: videoBase64.split(',')[1],
          mimeType: 'video/mp4'
        }
      });
    }

    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: { parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            score: { type: Type.NUMBER, description: "Nota de 0 a 10" },
            strengths: { type: Type.STRING, description: "Pontos fortes" },
            weaknesses: { type: Type.STRING, description: "Pontos fracos" },
            suggestions: { type: Type.STRING, description: "Sugestões de melhoria" },
            transcript: { type: Type.STRING, description: "Transcrição da fala" }
          },
          required: ["score", "strengths", "weaknesses", "suggestions", "transcript"]
        }
      }
    });

    // Directly access .text property
    const jsonStr = response.text?.trim() || '{}';
    const result = JSON.parse(jsonStr);

    return {
      score: result.score || 0,
      strengths: result.strengths || "Não foi possível identificar pontos fortes.",
      weaknesses: result.weaknesses || "Não foi possível identificar pontos fracos.",
      suggestions: result.suggestions || "Continue treinando!",
      transcript: result.transcript || "[Transcrição indisponível]"
    };
  } catch (error) {
    console.error("Erro na avaliação Gemini:", error);
    throw error;
  }
};

