          <p className="text-[#ee0000] font-bold">A inteligência artificial está analisando sua explicação...</p>
          <p className="text-gray-400 text-sm">Isso pode levar alguns segundos.</p>
        </div>
      );
    }

    switch (currentPage) {
      case 'login':
        return <Login onLogin={handleLogin} onGoToRegister={() => setCurrentPage('register')} />;
      case 'register':
        return <Register onRegister={handleRegister} onBack={() => setCurrentPage('login')} />;
      case 'dashboard':
        return user ? <Dashboard user={user} onNavigate={setCurrentPage} /> : null;
      case 'consultivo':
        return <Consultivo onStart={() => setCurrentPage('recorder')} onBack={() => setCurrentPage('dashboard')} />;
      case 'recorder':
        return <Recorder onComplete={handleRecorderComplete} onCancel={() => setCurrentPage('consultivo')} />;
      case 'result':
        return lastEval ? <EvaluationResult result={lastEval} onFinish={() => setCurrentPage('dashboard')} /> : null;
      case 'admin':
        return user ? <AdminDashboard currentUser={user} /> : null;
      default:
        return <Login onLogin={handleLogin} onGoToRegister={() => setCurrentPage('register')} />;
    }
  };

  return (
    <Layout 
      user={user} 
      onLogout={handleLogout}
      onHome={handleHome}
      title={currentPage === 'admin' ? 'Painel Administrativo' : undefined}
    >
      {renderContent()}
    </Layout>
  );
};

export default App;

const DB_NAME = 'ExplicaPlusStorage';
const STORE_NAME = 'media_files';
const DB_VERSION = 1;

export const MediaStorage = {
  init: (): Promise<void> => {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(DB_NAME, DB_VERSION);
      request.onupgradeneeded = () => {
        const db = request.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME);
        }
      };
      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  },

  save: async (id: string, blob: Blob): Promise<string> => {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(DB_NAME, DB_VERSION);
      request.onsuccess = () => {
        const db = request.result;
        const transaction = db.transaction(STORE_NAME, 'readwrite');
        const store = transaction.objectStore(STORE_NAME);
        const putRequest = store.put(blob, id);
        putRequest.onsuccess = () => resolve(id);
        putRequest.onerror = () => reject(putRequest.error);
      };
      request.onerror = () => reject(request.error);
    });
  },

  get: async (id: string): Promise<Blob | null> => {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(DB_NAME, DB_VERSION);
      request.onsuccess = () => {
        const db = request.result;
        const transaction = db.transaction(STORE_NAME, 'readonly');
        const store = transaction.objectStore(STORE_NAME);
        const getRequest = store.get(id);
        getRequest.onsuccess = () => resolve(getRequest.result || null);
        getRequest.onerror = () => reject(getRequest.error);
      };
      request.onerror = () => reject(request.error);
    });
  },

  delete: async (id: string): Promise<void> => {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(DB_NAME, DB_VERSION);
      request.onsuccess = () => {
        const db = request.result;
        const transaction = db.transaction(STORE_NAME, 'readwrite');
        const store = transaction.objectStore(STORE_NAME);
        const delRequest = store.delete(id);
        delRequest.onsuccess = () => resolve();
        delRequest.onerror = () => reject(delRequest.error);
      };
      request.onerror = () => reject(request.error);
    });
  }
};

import React, { useState, useMemo, useEffect } from 'react';
