  const ranking = useMemo(() => {
    const scores = evaluations.reduce((acc: Record<string, RankingEntry>, curr) => {
      if (!acc[curr.userId]) {
        acc[curr.userId] = { 
          name: curr.userName, 
          avg: 0, 
          count: 0, 
          best: 0,
          uf: curr.uf,
          city: curr.city
        };
      }
      acc[curr.userId].count++;
      acc[curr.userId].best = Math.max(acc[curr.userId].best, curr.score);
      return acc;
    }, {} as Record<string, RankingEntry>);

    return Object.values(scores)
      .sort((a, b) => b.best - a.best)
      .slice(0, 5);
