const ExpandableSection: React.FC<{ title: string; content: string; colorClass: string; textColor: string }> = ({ title, content, colorClass, textColor }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const isLong = content.length > 150;

  return (
    <div className={`border-l-4 ${colorClass} pl-4 relative group`}>
      <h4 className={`text-xs font-black ${textColor} uppercase flex items-center justify-between`}>
        {title}
        {isLong && (
          <button 
            onClick={() => setIsExpanded(!isExpanded)}
            className="p-1 hover:bg-gray-100 rounded-full transition-colors text-gray-400"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className={`h-4 w-4 transition-transform ${isExpanded ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
            </svg>
          </button>
        )}
      </h4>
      <p className={`text-sm text-gray-600 leading-relaxed ${!isExpanded && isLong ? 'line-clamp-3' : ''}`}>
        {content}
      </p>
      {!isExpanded && isLong && (
        <button 
          onClick={() => setIsExpanded(true)}
          className="text-[10px] font-bold text-blue-500 hover:underline mt-1"
        >
          Ver mais...
        </button>
      )}
    </div>
  );
};

export const AdminDashboard: React.FC<AdminDashboardProps> = ({ currentUser }) => {
  const [activeTab, setActiveTab] = useState<'accesses' | 'evaluations' | 'users'>('evaluations');
  const [filterUf, setFilterUf] = useState('');
  const [filterCity, setFilterCity] = useState('');
  const [refresh, setRefresh] = useState(0);
  const [selectedEval, setSelectedEval] = useState<Evaluation | null>(null);
  const [videoUrl, setVideoUrl] = useState<string | null>(null);

  const [newAdmin, setNewAdmin] = useState({ name: '', login: '', cpf: '', email: '', uf: '', city: '', password: '' });
  const [showAddAdmin, setShowAddAdmin] = useState(false);

  const accesses = useMemo(() => DB.accesses.all().sort((a,b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()), []);
  const evaluations = useMemo(() => DB.evaluations.all().sort((a,b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()), [refresh]);
  const users = useMemo(() => DB.users.all(), [refresh]);

  const isSuperAdmin = currentUser.role === 'superadmin';
  const isAdminOrSuper = currentUser.role === 'admin' || currentUser.role === 'superadmin';

  const filteredEvaluations = useMemo(() => {
    return evaluations.filter(e => 
      (!filterUf || e.uf === filterUf) && 
      (!filterCity || e.city.toLowerCase().includes(filterCity.toLowerCase()))
    );
  }, [evaluations, filterUf, filterCity]);

  useEffect(() => {
    if (selectedEval) {
      MediaStorage.get(selectedEval.id).then(blob => {
        if (blob) {
          setVideoUrl(URL.createObjectURL(blob));
