import React, { useState, useEffect } from 'react';
import { validateCPF, formatCPF } from '../utils/validators';

interface RegisterProps {
  onRegister: (data: any) => void;
  onBack: () => void;
}

interface IBGECity {
  id: number;
  nome: string;
}

const BRAZIL_STATES = [
  { uf: 'AC', nome: 'Acre' }, { uf: 'AL', nome: 'Alagoas' }, { uf: 'AP', nome: 'Amapá' },
  { uf: 'AM', nome: 'Amazonas' }, { uf: 'BA', nome: 'Bahia' }, { uf: 'CE', nome: 'Ceará' },
  { uf: 'DF', nome: 'Distrito Federal' }, { uf: 'ES', nome: 'Espírito Santo' }, { uf: 'GO', nome: 'Goiás' },
  { uf: 'MA', nome: 'Maranhão' }, { uf: 'MT', nome: 'Mato Grosso' }, { uf: 'MS', nome: 'Mato Grosso do Sul' },
  { uf: 'MG', nome: 'Minas Gerais' }, { uf: 'PA', nome: 'Pará' }, { uf: 'PB', nome: 'Paraíba' },
  { uf: 'PR', nome: 'Paraná' }, { uf: 'PE', nome: 'Pernambuco' }, { uf: 'PI', nome: 'Piauí' },
  { uf: 'RJ', nome: 'Rio de Janeiro' }, { uf: 'RN', nome: 'Rio Grande do Norte' }, { uf: 'RS', nome: 'Rio Grande do Sul' },
  { uf: 'RO', nome: 'Rondônia' }, { uf: 'RR', nome: 'Roraima' }, { uf: 'SC', nome: 'Santa Catarina' },
  { uf: 'SP', nome: 'São Paulo' }, { uf: 'SE', nome: 'Sergipe' }, { uf: 'TO', nome: 'Tocantins' }
];

export const Register: React.FC<RegisterProps> = ({ onRegister, onBack }) => {
  const [formData, setFormData] = useState({
    name: '',
    login: '',
    cpf: '',
    email: '',
    uf: '',
    city: '',
    password: ''
  });

  const [cpfStatus, setCpfStatus] = useState<'idle' | 'valid' | 'invalid'>('idle');
  const [cities, setCities] = useState<IBGECity[]>([]);
  const [loadingCities, setLoadingCities] = useState(false);

  useEffect(() => {
    if (formData.uf) {
      setLoadingCities(true);
      fetch(`https://servicodados.ibge.gov.br/api/v1/localidades/estados/${formData.uf}/municipios?orderBy=nome`)
        .then(res => res.json())
        .then((data: IBGECity[]) => {
          setCities(data);
          setLoadingCities(false);
          setFormData(prev => ({ ...prev, city: '' }));
        })
        .catch(err => {
          console.error("Erro ao buscar cidades:", err);
          setLoadingCities(false);
        });
    } else {
      setCities([]);
    }
  }, [formData.uf]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (cpfStatus === 'invalid' || !validateCPF(formData.cpf)) {
      setCpfStatus('invalid');
      alert("O CPF informado é inválido. Por favor, confira os números.");
      return;
    }

    if (!formData.uf || !formData.city) {
      alert("Por favor, selecione seu Estado e Cidade.");
      return;
    }

    onRegister(formData);
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;

    if (name === 'cpf') {
      const formatted = formatCPF(value);
      const digits = formatted.replace(/\D/g, '');
      setFormData(prev => ({ ...prev, [name]: formatted }));

      if (digits.length === 11) {
        const isValid = validateCPF(digits);
        setCpfStatus(isValid ? 'valid' : 'invalid');
      } else {
        setCpfStatus('idle');
      }
    } else {
      setFormData(prev => ({ ...prev, [name]: value }));
    }
  };

  const getCpfClasses = () => {
    if (cpfStatus === 'valid') return 'border-green-500 bg-green-50 text-green-700';
    if (cpfStatus === 'invalid') return 'border-[#ee0000] bg-red-50 text-[#ee0000]';
    return 'border-gray-100 focus:claro-border-red focus:bg-white';
  };

  return (
    <div className="flex flex-col items-center justify-center py-6 animate-fadeIn">
      <div className="w-full max-w-xl bg-white p-8 rounded-3xl shadow-xl border border-gray-100">
        <div className="mb-6 flex items-center justify-between">
          <h2 className="text-2xl font-black claro-text-red">NOVO CADASTRO</h2>
          <button onClick={onBack} className="text-gray-400 hover:text-gray-600 text-sm font-bold">Voltar</button>
        </div>

        <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="md:col-span-2">
            <label className="block text-xs font-bold text-gray-500 uppercase mb-1 ml-1">Nome Completo</label>
            <input 
              name="name" 
              type="text" 
              placeholder="Ex: Willian Barbosa"
              className="w-full p-3 bg-gray-50 border border-gray-100 rounded-xl focus:claro-border-red focus:bg-white outline-none transition-all"
              onChange={handleChange}
              value={formData.name}
              required
            />
          </div>
          <div>
            <label className="block text-xs font-bold text-gray-500 uppercase mb-1 ml-1">Login (Usuário)</label>
            <input 
              name="login" 
              type="text" 
              placeholder="Ex: F1234567"
              className="w-full p-3 bg-gray-50 border border-gray-100 rounded-xl focus:claro-border-red focus:bg-white outline-none transition-all"
              onChange={handleChange}
              value={formData.login}
              required
            />
          </div>
          <div>
            <label className={`block text-xs font-bold uppercase mb-1 ml-1 ${cpfStatus === 'invalid' ? 'text-[#ee0000]' : cpfStatus === 'valid' ? 'text-green-600' : 'text-gray-500'}`}>
              CPF
            </label>
            <input 
              name="cpf" 
              type="text" 
              placeholder="000.000.000-00"
              className={`w-full p-3 bg-gray-50 border rounded-xl outline-none transition-all ${getCpfClasses()}`}
              onChange={handleChange}
              value={formData.cpf}
              maxLength={14}
              required
            />
            {cpfStatus === 'invalid' && <p className="text-[10px] text-[#ee0000] font-bold mt-1 ml-1 animate-fadeIn">CPF INVÁLIDO</p>}
            {cpfStatus === 'valid' && <p className="text-[10px] text-green-600 font-bold mt-1 ml-1 animate-fadeIn">CPF VÁLIDO</p>}
          </div>
          <div className="md:col-span-2">
            <label className="block text-xs font-bold text-gray-500 uppercase mb-1 ml-1">Email</label>
            <input 
              name="email" 
              type="email" 
              placeholder="willian@claro.com.br"
              className="w-full p-3 bg-gray-50 border border-gray-100 rounded-xl focus:claro-border-red focus:bg-white outline-none transition-all"
              onChange={handleChange}
              value={formData.email}
              required
            />
          </div>
          <div className="grid grid-cols-3 gap-2 md:col-span-2">
            <div className="col-span-1">
              <label className="block text-xs font-bold text-gray-500 uppercase mb-1 ml-1">UF</label>
              <select 
                name="uf" 
                className="w-full p-3 bg-gray-50 border border-gray-100 rounded-xl focus:claro-border-red focus:bg-white outline-none transition-all appearance-none"
                onChange={handleChange}
                value={formData.uf}
                required
              >
                <option value="">UF</option>
                {BRAZIL_STATES.map(state => (
                  <option key={state.uf} value={state.uf}>{state.uf}</option>
                ))}
              </select>
            </div>
            <div className="col-span-2">
              <label className="block text-xs font-bold text-gray-500 uppercase mb-1 ml-1">Cidade</label>
              <select 
                name="city" 
                className="w-full p-3 bg-gray-50 border border-gray-100 rounded-xl focus:claro-border-red focus:bg-white outline-none transition-all appearance-none disabled:opacity-50"
                onChange={handleChange}
                value={formData.city}
                disabled={!formData.uf || loadingCities}
                required
              >
                <option value="">{loadingCities ? 'Carregando...' : 'Selecione a cidade'}</option>
                {cities.map(city => (
                  <option key={city.id} value={city.nome}>{city.nome}</option>
                ))}
              </select>
            </div>
          </div>
          <div className="md:col-span-2">
            <label className="block text-xs font-bold text-gray-500 uppercase mb-1 ml-1">Crie sua Senha</label>
            <input 
              name="password" 
              type="password" 
              placeholder="••••••••"
              className="w-full p-3 bg-gray-50 border border-gray-100 rounded-xl focus:claro-border-red focus:bg-white outline-none transition-all"
              onChange={handleChange}
              value={formData.password}
              required
            />
          </div>

          <div className="md:col-span-2 pt-4">
            <button 
              type="submit"
              disabled={cpfStatus === 'invalid'}
              className={`w-full text-white font-bold py-4 rounded-full shadow-lg transition-all ${cpfStatus === 'invalid' ? 'bg-gray-300 cursor-not-allowed' : 'claro-red hover:bg-red-700'}`}
            >
              FINALIZAR CADASTRO
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { DB } from '../db';
import { User, AccessLog, Evaluation } from '../types';
import { MediaStorage } from '../services/storageService';
import { validateCPF, formatCPF } from '../utils/validators';

interface AdminDashboardProps {
  currentUser: User;
}

const ExpandableSection: React.FC<{ title: string; content: string; colorClass: string; textColor: string }> = ({ title, content, colorClass, textColor }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const isLong = content.length > 150;

  return (
    <div className={`border-l-4 ${colorClass} pl-4 relative group`}>
      <h4 className={`text-xs font-black ${textColor} uppercase flex items-center justify-between`}>
        {title}
        {isLong && (
          <button 
            onClick={() => setIsExpanded(!isExpanded)}
            className="p-1 hover:bg-gray-100 rounded-full transition-colors text-gray-400"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className={`h-4 w-4 transition-transform ${isExpanded ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
            </svg>
          </button>
        )}
      </h4>
      <p className={`text-sm text-gray-600 leading-relaxed ${!isExpanded && isLong ? 'line-clamp-3' : ''}`}>
        {content}
      </p>
      {!isExpanded && isLong && (
        <button 
          onClick={() => setIsExpanded(true)}
          className="text-[10px] font-bold text-blue-500 hover:underline mt-1"
        >
          Ver mais...
        </button>
      )}
    </div>
  );
};

export const AdminDashboard: React.FC<AdminDashboardProps> = ({ currentUser }) => {
  const [activeTab, setActiveTab] = useState<'accesses' | 'evaluations' | 'users'>('evaluations');
  const [filterUf, setFilterUf] = useState('');
  const [filterCity, setFilterCity] = useState('');
  const [refresh, setRefresh] = useState(0);
  const [selectedEval, setSelectedEval] = useState<Evaluation | null>(null);
  const [videoUrl, setVideoUrl] = useState<string | null>(null);

  const [newAdmin, setNewAdmin] = useState({ name: '', login: '', cpf: '', email: '', uf: '', city: '', password: '' });
  const [cpfStatus, setCpfStatus] = useState<'idle' | 'valid' | 'invalid'>('idle');
  const [showAddAdmin, setShowAddAdmin] = useState(false);

  const accesses = useMemo(() => DB.accesses.all().sort((a,b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()), []);
  const evaluations = useMemo(() => DB.evaluations.all().sort((a,b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()), [refresh]);
  const users = useMemo(() => DB.users.all(), [refresh]);

  const isSuperAdmin = currentUser.role === 'superadmin';
  const isAdminOrSuper = currentUser.role === 'admin' || currentUser.role === 'superadmin';

  const filteredEvaluations = useMemo(() => {
    return evaluations.filter(e => 
      (!filterUf || e.uf === filterUf) && 
      (!filterCity || e.city.toLowerCase().includes(filterCity.toLowerCase()))
    );
  }, [evaluations, filterUf, filterCity]);

  useEffect(() => {
    if (selectedEval) {
      MediaStorage.get(selectedEval.id).then(blob => {
        if (blob) {
          setVideoUrl(URL.createObjectURL(blob));
        }
      });
    } else {
      setVideoUrl(null);
    }
  }, [selectedEval]);

  const handleDeleteUser = (userToDelete: User) => {
    if (!isAdminOrSuper) return;
    if (userToDelete.id === currentUser.id) {
      alert("Você não pode excluir seu próprio perfil.");
      return;
    }

    if (currentUser.role === 'admin' && userToDelete.role === 'superadmin') {
      alert("Acesso negado: Administradores não podem excluir Super Administradores.");
      return;
    }

    if (window.confirm(`Deseja realmente excluir o usuário ${userToDelete.name}?`)) {
      DB.users.delete(userToDelete.id);
      setRefresh(prev => prev + 1);
    }
  };

  const handleCreateAdmin = (e: React.FormEvent) => {
    e.preventDefault();
    if (!isSuperAdmin) {
      alert("Apenas Super Administradores podem criar novos administradores.");
      return;
    }

    if (cpfStatus === 'invalid' || !validateCPF(newAdmin.cpf)) {
      alert("CPF inválido. Verifique os números digitados.");
      return;
    }

    const existing = DB.users.findByCpf(newAdmin.cpf);
    if (existing) { alert("Este CPF já está cadastrado no sistema."); return; }

    DB.users.add({
      ...newAdmin,
      id: `admin-${Math.random().toString(36).substr(2, 9)}`,
      role: 'admin',
      createdAt: new Date().toISOString()
    });

    setNewAdmin({ name: '', login: '', cpf: '', email: '', uf: '', city: '', password: '' });
    setCpfStatus('idle');
    setShowAddAdmin(false);
    setRefresh(prev => prev + 1);
  };

  const handleNewAdminCpfChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const formatted = formatCPF(e.target.value);
    const digits = formatted.replace(/\D/g, '');
    setNewAdmin({...newAdmin, cpf: formatted});

    if (digits.length === 11) {
      const isValid = validateCPF(digits);
      setCpfStatus(isValid ? 'valid' : 'invalid');
    } else {
      setCpfStatus('idle');
    }
  };

  const getCpfClasses = () => {
    if (cpfStatus === 'valid') return 'border-green-500 bg-green-50 text-green-700';
    if (cpfStatus === 'invalid') return 'border-[#ee0000] bg-red-50 text-[#ee0000]';
    return 'border-gray-200 focus:border-[#ee0000]';
  };

  const handleSendEmail = () => {
    if (!selectedEval) return;

    const subject = encodeURIComponent(`[Explica+] Relatório de Avaliação - ${selectedEval.userName}`);
    const body = encodeURIComponent(
      `Relatório de Avaliação - Explica+\n\n` +
      `Técnico: ${selectedEval.userName}\n` +
      `Local: ${selectedEval.city}/${selectedEval.uf}\n` +
      `Data: ${new Date(selectedEval.timestamp).toLocaleDateString()}\n` +
      `Nota Final: ${selectedEval.score.toFixed(1)}\n\n` +
      `PONTOS FORTES:\n${selectedEval.strengths}\n\n` +
      `OPORTUNIDADES:\n${selectedEval.weaknesses}\n\n` +
      `SUGESTÃO DO AVALIADOR:\n${selectedEval.suggestions}\n\n` +
      `TRANSCRIÇÃO:\n"${selectedEval.transcript}"\n`
    );

    window.location.href = `mailto:?subject=${subject}&body=${body}`;
  };

  return (
    <div className="space-y-6 animate-fadeIn pb-20">
      {/* Resumo de Cards */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <div className="bg-white p-4 rounded-2xl shadow-sm border border-gray-100">
          <p className="text-[10px] font-bold text-gray-400 uppercase">Total Avaliações</p>
          <p className="text-2xl font-black claro-text-red">{evaluations.length}</p>
        </div>
        <div className="bg-white p-4 rounded-2xl shadow-sm border border-gray-100">
          <p className="text-[10px] font-bold text-gray-400 uppercase">Média Geral</p>
          <p className="text-2xl font-black text-gray-800">
            {(evaluations.reduce((acc, curr) => acc + curr.score, 0) / (evaluations.length || 1)).toFixed(1)}
          </p>
        </div>
        <div className="bg-white p-4 rounded-2xl shadow-sm border border-gray-100">
          <p className="text-[10px] font-bold text-gray-400 uppercase">Acessos Hoje</p>
          <p className="text-2xl font-black text-blue-600">
            {accesses.filter(a => new Date(a.timestamp).toDateString() === new Date().toDateString()).length}
          </p>
        </div>
        <div className="bg-white p-4 rounded-2xl shadow-sm border border-gray-100">
          <p className="text-[10px] font-bold text-gray-400 uppercase">Técnicos Ativos</p>
          <p className="text-2xl font-black text-green-600">{users.filter(u => u.role === 'tech').length}</p>
        </div>
      </div>

      <div className="flex bg-white p-1 rounded-xl shadow-sm border border-gray-200">
        <button onClick={() => setActiveTab('evaluations')} className={`flex-1 py-2 px-4 rounded-lg font-bold text-sm transition-all ${activeTab === 'evaluations' ? 'claro-red text-white' : 'text-gray-500'}`}>Avaliações</button>
        <button onClick={() => setActiveTab('accesses')} className={`flex-1 py-2 px-4 rounded-lg font-bold text-sm transition-all ${activeTab === 'accesses' ? 'claro-red text-white' : 'text-gray-500'}`}>Acessos</button>
        <button onClick={() => setActiveTab('users')} className={`flex-1 py-2 px-4 rounded-lg font-bold text-sm transition-all ${activeTab === 'users' ? 'claro-red text-white' : 'text-gray-500'}`}>Usuários</button>
      </div>

      {(activeTab === 'evaluations' || activeTab === 'accesses') && (
        <div className="bg-white p-4 rounded-2xl shadow-sm border border-gray-100 flex flex-wrap gap-4 items-end">
          <div className="w-24">
            <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1">Estado (UF)</label>
            <input type="text" placeholder="UF" className="w-full p-2 border border-gray-200 rounded-lg text-sm" value={filterUf} onChange={(e) => setFilterUf(e.target.value.toUpperCase())} maxLength={2} />
          </div>
          <div className="flex-1">
            <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1">Cidade</label>
            <input type="text" placeholder="Filtrar cidade..." className="w-full p-2 border border-gray-200 rounded-lg text-sm" value={filterCity} onChange={(e) => setFilterCity(e.target.value)} />
          </div>
          <button onClick={() => {setFilterCity(''); setFilterUf('')}} className="p-2 text-xs font-bold text-gray-400 hover:text-[#ee0000]">Limpar Filtros</button>
        </div>
      )}

      <div className="bg-white rounded-2xl shadow-sm overflow-hidden border border-gray-100">
        {activeTab === 'evaluations' && (
          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-gray-50 border-b border-gray-100">
                  <th className="p-4 text-xs font-bold text-gray-400 uppercase">Técnico</th>
                  <th className="p-4 text-xs font-bold text-gray-400 uppercase">Local</th>
                  <th className="p-4 text-xs font-bold text-gray-400 uppercase text-center">Nota</th>
                  <th className="p-4 text-xs font-bold text-gray-400 uppercase">Data</th>
                  <th className="p-4 text-xs font-bold text-gray-400 uppercase text-right">Ação</th>
                </tr>
              </thead>
              <tbody className="divide-y">
                {filteredEvaluations.map((ev) => (
                  <tr key={ev.id} className="hover:bg-red-50/30 transition-colors">
                    <td className="p-4 font-bold text-sm text-gray-700">{ev.userName}</td>
                    <td className="p-4 text-xs text-gray-500">{ev.city}/{ev.uf}</td>
                    <td className="p-4 text-center">
                      <span className={`inline-block px-3 py-1 rounded-full font-black text-sm ${ev.score >= 8 ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                        {ev.score.toFixed(1)}
                      </span>
                    </td>
                    <td className="p-4 text-xs text-gray-400">{new Date(ev.timestamp).toLocaleDateString()}</td>
                    <td className="p-4 text-right">
                      <button onClick={() => setSelectedEval(ev)} className="claro-text-red text-xs font-bold hover:underline">Ver Detalhes</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {activeTab === 'accesses' && (
          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-gray-50 border-b border-gray-100">
                  <th className="p-4 text-xs font-bold text-gray-400 uppercase">Técnico</th>
                  <th className="p-4 text-xs font-bold text-gray-400 uppercase">Local</th>
                  <th className="p-4 text-xs font-bold text-gray-400 uppercase">Data/Hora</th>
                </tr>
              </thead>
              <tbody className="divide-y">
                {accesses.map((acc) => (
                  <tr key={acc.id} className="hover:bg-gray-50">
                    <td className="p-4 text-sm font-medium">{acc.userName}</td>
                    <td className="p-4 text-xs text-gray-500">{acc.city}, {acc.uf}</td>
                    <td className="p-4 text-xs text-gray-400 font-mono">{new Date(acc.timestamp).toLocaleString()}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {activeTab === 'users' && (
          <div className="p-4 space-y-4">
            {isSuperAdmin && (
              <div className="mb-6 border-b border-gray-100 pb-6">
                <button onClick={() => setShowAddAdmin(!showAddAdmin)} className="claro-red text-white px-4 py-2 rounded-lg font-bold text-sm">
                  {showAddAdmin ? 'Cancelar Cadastro' : '+ Novo Administrador'}
                </button>
                {showAddAdmin && (
                  <form onSubmit={handleCreateAdmin} className="mt-4 grid grid-cols-1 md:grid-cols-3 gap-3 p-4 bg-gray-50 rounded-xl">
                    <input type="text" placeholder="Nome" className="p-2 border rounded text-sm" value={newAdmin.name} onChange={e => setNewAdmin({...newAdmin, name: e.target.value})} required />
                    <input type="text" placeholder="Login" className="p-2 border rounded text-sm" value={newAdmin.login} onChange={e => setNewAdmin({...newAdmin, login: e.target.value})} required />
                    <div className="relative">
                      <input 
                        type="text" 
                        placeholder="CPF" 
                        className={`w-full p-2 border rounded text-sm transition-all ${getCpfClasses()}`} 
                        value={newAdmin.cpf} 
                        onChange={handleNewAdminCpfChange} 
                        maxLength={14}
                        required 
                      />
                      {cpfStatus === 'invalid' && <span className="absolute -bottom-4 left-0 text-[9px] font-bold text-[#ee0000]">INVÁLIDO</span>}
                      {cpfStatus === 'valid' && <span className="absolute -bottom-4 left-0 text-[9px] font-bold text-green-600">VÁLIDO</span>}
                    </div>
                    <input type="email" placeholder="Email" className="p-2 border rounded text-sm" value={newAdmin.email} onChange={e => setNewAdmin({...newAdmin, email: e.target.value})} required />
                    <input type="text" placeholder="UF" className="p-2 border rounded text-sm" value={newAdmin.uf} onChange={e => setNewAdmin({...newAdmin, uf: e.target.value.toUpperCase()})} maxLength={2} required />
                    <input type="text" placeholder="Cidade" className="p-2 border rounded text-sm" value={newAdmin.city} onChange={e => setNewAdmin({...newAdmin, city: e.target.value})} required />
                    <input type="password" placeholder="Senha" className="p-2 border rounded text-sm" value={newAdmin.password} onChange={e => setNewAdmin({...newAdmin, password: e.target.value})} required />
                    <button 
                      type="submit" 
                      disabled={cpfStatus === 'invalid'}
                      className={`md:col-span-3 text-white py-2 rounded font-bold transition-all ${cpfStatus === 'invalid' ? 'bg-gray-300 cursor-not-allowed' : 'bg-green-600 hover:bg-green-700'}`}
                    >
                      Salvar Admin
                    </button>
                  </form>
                )}
              </div>
            )}
            <table className="w-full text-left">
              <thead>
                <tr className="text-xs font-bold text-gray-400 uppercase">
                  <th className="p-2">Nome</th>
                  <th className="p-2">Perfil</th>
                  <th className="p-2 text-right">Ação</th>
                </tr>
              </thead>
              <tbody className="divide-y">
                {users.map(u => (
                  <tr key={u.id}>
                    <td className="p-2 text-sm font-bold">{u.name}</td>
                    <td className="p-2">
                      <span className={`text-[10px] px-2 py-0.5 rounded font-black ${u.role === 'superadmin' ? 'bg-black text-white' : u.role === 'admin' ? 'bg-purple-100 text-purple-700' : 'bg-gray-100 text-gray-600'}`}>
                        {u.role.toUpperCase()}
                      </span>
                    </td>
                    <td className="p-2 text-right">
                      {isAdminOrSuper && u.id !== currentUser.id && !(currentUser.role === 'admin' && u.role === 'superadmin') && (
                        <button onClick={() => handleDeleteUser(u)} className="text-red-600 font-bold text-xs hover:underline">Excluir</button>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {selectedEval && (
        <div className="fixed inset-0 z-[100] bg-black/80 flex items-center justify-center p-4 backdrop-blur-sm">
          <div className="bg-white w-full max-w-4xl max-h-[90vh] rounded-3xl overflow-hidden shadow-2xl flex flex-col animate-scaleUp">
            <div className="claro-red p-4 flex justify-between items-center text-white">
              <h3 className="font-bold uppercase">Detalhes da Explicação - {selectedEval.userName}</h3>
              <button onClick={() => setSelectedEval(null)} className="p-1 hover:bg-white/20 rounded-full transition-colors">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>

            <div className="flex-1 overflow-y-auto p-6 space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-3">
                  <div className="bg-black rounded-2xl aspect-video flex items-center justify-center overflow-hidden shadow-inner border border-gray-100">
                    {videoUrl ? (
                      <video src={videoUrl} controls className="w-full h-full object-contain" />
                    ) : (
                      <p className="text-gray-400 text-sm italic">Carregando mídia...</p>
                    )}
                  </div>
                  <div className="bg-gray-50 p-4 rounded-xl border border-gray-100">
                    <h4 className="text-xs font-black text-gray-400 uppercase mb-2">Transcrição da IA</h4>
                    <p className="text-sm text-gray-600 leading-relaxed italic line-clamp-4 hover:line-clamp-none transition-all cursor-help">"{selectedEval.transcript}"</p>
                  </div>
                </div>

                <div className="space-y-4">
                  <div className="flex items-center justify-between bg-gray-50 p-4 rounded-2xl border border-gray-100">
                    <span className="text-sm font-bold text-gray-500 uppercase tracking-tight">Nota da Performance</span>
                    <span className={`text-4xl font-black ${selectedEval.score >= 8 ? 'text-green-500' : 'text-[#ee0000]'}`}>{selectedEval.score.toFixed(1)}</span>
                  </div>

                  <div className="space-y-4">
                    <ExpandableSection 
                      title="Pontos Fortes" 
                      content={selectedEval.strengths} 
                      colorClass="border-green-500" 
                      textColor="text-green-700" 
                    />
                    <ExpandableSection 
                      title="Oportunidades" 
                      content={selectedEval.weaknesses} 
                      colorClass="border-red-500" 
                      textColor="text-red-700" 
                    />
                    <ExpandableSection 
                      title="Dica do Avaliador" 
                      content={selectedEval.suggestions} 
                      colorClass="border-blue-500" 
                      textColor="text-blue-700" 
                    />
                  </div>

                  <div className="pt-4 border-t border-gray-100 flex justify-between text-[10px] text-gray-400 font-bold uppercase">
                    <span>ID: {selectedEval.id}</span>
                    <span>{selectedEval.city}/{selectedEval.uf}</span>
                  </div>
                </div>
              </div>
            </div>

            <div className="p-4 bg-gray-50 border-t border-gray-100 flex flex-wrap gap-2 justify-end">
              <button 
                onClick={handleSendEmail} 
                className="px-5 py-2.5 bg-blue-600 text-white rounded-full font-bold text-sm hover:bg-blue-700 transition-all flex items-center gap-2 shadow-sm"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" />
                </svg>
                Enviar por Email
              </button>
              <button 
                onClick={() => window.print()} 
                className="px-5 py-2.5 bg-gray-200 text-gray-700 rounded-full font-bold text-sm hover:bg-gray-300 transition-all flex items-center gap-2"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z" />
                </svg>
                Imprimir Relatório
              </button>
              <button 
                onClick={() => setSelectedEval(null)} 
                className="px-8 py-2.5 claro-red text-white rounded-full font-bold text-sm hover:bg-red-700 transition-all shadow-sm"
              >
                Fechar
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { DB } from '../db';
import { User, AccessLog, Evaluation } from '../types';
import { MediaStorage } from '../services/storageService';
import { validateCPF, formatCPF } from '../utils/validators';

interface AdminDashboardProps {
  currentUser: User;
}

interface IBGECity {
  id: number;
  nome: string;
}

