import React, { useState, useEffect, useCallback } from 'react';
import { User, Evaluation as EvalModel, AccessLog } from './types';
import { DB } from './db';
import { Layout } from './components/Layout';
import { Login } from './pages/Login';
import { Register } from './pages/Register';
import { Dashboard } from './pages/Dashboard';
import { Consultivo } from './pages/Consultivo';
import { Recorder } from './pages/Recorder';
import { EvaluationResult } from './pages/EvaluationResult';
import { AdminDashboard } from './pages/AdminDashboard';
import { evaluateExplanation, EvaluationResult as AIResult } from './services/geminiService';
import { MediaStorage } from './services/storageService';

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<string>('login');
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(false);
  const [lastEval, setLastEval] = useState<AIResult | null>(null);
  const [activeScenario, setActiveScenario] = useState<any>(null);

  useEffect(() => {
    MediaStorage.init().catch(err => console.error("Falha ao iniciar IndexedDB:", err));

    const savedUser = localStorage.getItem('explica_session');
    if (savedUser) {
      const u = JSON.parse(savedUser);
      const freshUser = DB.users.findById(u.id);
      if (freshUser) {
        setUser(freshUser);
        setCurrentPage('dashboard');
      } else {
        localStorage.removeItem('explica_session');
      }
    }
  }, []);

  const handleLogin = (cpf: string, pass: string) => {
    const foundUser = DB.users.findByCpf(cpf);
    if (foundUser && (foundUser.password === pass || foundUser.role === 'admin' || foundUser.role === 'superadmin')) {
      setUser(foundUser);
      localStorage.setItem('explica_session', JSON.stringify(foundUser));

      DB.accesses.add({
        id: Math.random().toString(36).substr(2, 9),
        userId: foundUser.id,
        userName: foundUser.name,
        timestamp: new Date().toISOString(),
        uf: foundUser.uf,
        city: foundUser.city
      });

      setCurrentPage('dashboard');
    } else {
      alert("Credenciais inválidas");
    }
  };

  const handleRegister = (data: Partial<User>) => {
    const newId = `tech-${Math.random().toString(36).substr(2, 9)}`;
    const newUser: User = {
      ...data,
      id: newId,
      role: 'tech',
      createdAt: new Date().toISOString()
    } as User;

    DB.users.add(newUser);
    alert(`Técnico cadastrado com sucesso! ID: ${newId}. Faça login com seu CPF.`);
    setCurrentPage('login');
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('explica_session');
    setCurrentPage('login');
  };

  const handleHome = () => {
    if (user) {
      setCurrentPage('dashboard');
    }
  };

  const handleStartScenario = (scenario: any) => {
    setActiveScenario(scenario);
    setCurrentPage('recorder');
  };

  const handleRecorderComplete = async (video: Blob) => {
    setLoading(true);
    try {
      const evalId = Math.random().toString(36).substr(2, 9);

      await MediaStorage.save(evalId, video);

      const reader = new FileReader();
      const base64Promise = new Promise<string>((resolve) => {
        reader.onloadend = () => resolve(reader.result as string);
        reader.readAsDataURL(video);
      });

      const base64Video = await base64Promise;

      // Passamos o contexto do cenário para a IA
      const scenarioContext = activeScenario ? 
        `Cenário: Atendimento para ${activeScenario.customerName}. Produto: ${activeScenario.product}. Dúvida do cliente: ${activeScenario.question}` 
        : undefined;

      const result = await evaluateExplanation(base64Video, undefined, scenarioContext);

      if (user) {
        DB.evaluations.add({
          id: evalId,
          userId: user.id,
          userName: user.name,
          timestamp: new Date().toISOString(),
          score: result.score,
          strengths: result.strengths,
          weaknesses: result.weaknesses,
          suggestions: result.suggestions,
          transcript: result.transcript,
          uf: user.uf,
          city: user.city
        });
      }

      setLastEval(result);
      setCurrentPage('result');
    } catch (err) {
      console.error(err);
      alert("Erro ao avaliar vídeo. Tente novamente.");
    } finally {
      setLoading(false);
    }
  };

  const renderContent = () => {
    if (loading) {
      return (
        <div className="flex flex-col items-center justify-center min-h-[50vh] space-y-4">
          <div className="w-16 h-16 border-4 border-gray-100 border-t-[#ee0000] rounded-full animate-spin"></div>
          <p className="text-[#ee0000] font-bold">A inteligência artificial está analisando sua explicação...</p>
          <p className="text-gray-400 text-sm">Aguarde a geração do feedback completo.</p>
        </div>
      );
    }

    switch (currentPage) {
      case 'login': return <Login onLogin={handleLogin} onGoToRegister={() => setCurrentPage('register')} />;
      case 'register': return <Register onRegister={handleRegister} onBack={() => setCurrentPage('login')} />;
      case 'dashboard': return user ? <Dashboard user={user} onNavigate={setCurrentPage} /> : null;
      case 'consultivo': return <Consultivo onStart={handleStartScenario} onBack={() => setCurrentPage('dashboard')} />;
      case 'recorder': return <Recorder onComplete={handleRecorderComplete} onCancel={() => setCurrentPage('consultivo')} />;
      case 'result': return lastEval ? <EvaluationResult result={lastEval} onFinish={() => setCurrentPage('dashboard')} /> : null;
      case 'admin': return user ? <AdminDashboard currentUser={user} /> : null;
      default: return <Login onLogin={handleLogin} onGoToRegister={() => setCurrentPage('register')} />;
    }
  };

  return (
    <Layout 
      user={user} 
      onLogout={handleLogout} 
      onHome={handleHome} 
      onAdminClick={() => setCurrentPage('admin')}
      title={currentPage === 'admin' ? 'Painel Administrativo' : undefined}
    >
      {renderContent()}
    </Layout>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export interface EvaluationResult {
  score: number;
  strengths: string;
  weaknesses: string;
  suggestions: string;
  transcript: string;
}

export const evaluateExplanation = async (
  videoBase64?: string, 
  audioBase64?: string, 
  scenarioContext?: string
): Promise<EvaluationResult> => {
  const contextPrompt = scenarioContext ? 
    `CONTEXTO DO CENÁRIO ESPECÍFICO: ${scenarioContext}. Avalie se o técnico respondeu diretamente à dúvida do cliente e se usou argumentos corretos para este produto.` : 
    "Avalie uma explicação técnica geral sobre os produtos Claro.";

  const prompt = `
    Você é um avaliador de excelência de atendimento da Claro especializado em feedback para técnicos de campo.
    ${contextPrompt}

    Analise a explicação técnica/comercial feita pelo funcionário.

    Critérios de Avaliação (Nota 0-10):
    1. Clareza e Didática: O técnico fala de forma compreensível?
    2. Empatia: Demonstrou paciência e foco no perfil do cliente?
    3. Conhecimento do Produto: As informações sobre Virtua, TV+ ou Mesh estão corretas?
    4. Argumentação: Ele explicou o 'porquê' do produto ser bom (benefícios)?

    Retorne o resultado estritamente em JSON.
  `;

  try {
    const parts: any[] = [
      { text: prompt }
    ];

    if (videoBase64) {
      parts.push({
        inlineData: {
          data: videoBase64.split(',')[1],
          mimeType: 'video/mp4'
        }
      });
    }

    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: { parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            score: { type: Type.NUMBER, description: "Nota final de 0 a 10" },
            strengths: { type: Type.STRING, description: "O que o técnico fez de excelente" },
            weaknesses: { type: Type.STRING, description: "Onde o técnico falhou ou pode melhorar" },
            suggestions: { type: Type.STRING, description: "Conselho prático para o próximo atendimento" },
            transcript: { type: Type.STRING, description: "Transcrição fiel do que foi dito" }
          },
          required: ["score", "strengths", "weaknesses", "suggestions", "transcript"]
        }
      }
    });

    const jsonStr = response.text?.trim() || '{}';
    const result = JSON.parse(jsonStr);

    return {
      score: result.score || 0,
      strengths: result.strengths || "Não foi possível identificar pontos fortes.",
      weaknesses: result.weaknesses || "Não foi possível identificar pontos fracos.",
      suggestions: result.suggestions || "Continue praticando os cenários!",
      transcript: result.transcript || "[Transcrição indisponível]"
    };
  } catch (error) {
    console.error("Erro na avaliação Gemini:", error);
    throw error;
  }
};

