import React, { useRef, useState, useEffect } from 'react';

interface Scenario {
  id: string;
  title: string;
  product: 'Virtua' | 'TV' | 'Mesh' | 'Móvel';
  customerName: string;
  customerProfile: string;
  image: string;
  question: string;
  evalCriteria: string[];
}

interface RecorderProps {
  onComplete: (videoBlob: Blob, audioBlob: Blob) => void;
  onCancel: () => void;
  scenario: Scenario | null;
}

export const Recorder: React.FC<RecorderProps> = ({ onComplete, onCancel, scenario }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const [isRecording, setIsRecording] = useState(false);
  const [recordedBlob, setRecordedBlob] = useState<Blob | null>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const chunks = useRef<Blob[]>([]);

  const startCamera = async () => {
    try {
      const s = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'user', width: { ideal: 1280 }, height: { ideal: 720 } }, 
        audio: true 
      });
      setStream(s);
      if (videoRef.current) {
        videoRef.current.srcObject = s;
      }
    } catch (err) {
      alert("Não foi possível acessar a câmera ou microfone.");
      onCancel();
    }
  };

  useEffect(() => {
    startCamera();
    return () => {
      stream?.getTracks().forEach(track => track.stop());
    };
  }, []);

  const handleStartRecording = () => {
    if (!stream) return;
    chunks.current = [];
    const recorder = new MediaRecorder(stream);
    recorder.ondataavailable = (e) => {
      if (e.data.size > 0) chunks.current.push(e.data);
    };
    recorder.onstop = () => {
      const blob = new Blob(chunks.current, { type: 'video/mp4' });
      setRecordedBlob(blob);
    };
    recorder.start();
    mediaRecorderRef.current = recorder;
    setIsRecording(true);
  };

  const handleStopRecording = () => {
    mediaRecorderRef.current?.stop();
    setIsRecording(false);
  };

  const handleRepeat = () => {
    setRecordedBlob(null);
    startCamera();
  };

  const handleSend = () => {
    if (recordedBlob) {
      onComplete(recordedBlob, recordedBlob);
    }
  };

  // Gerador de roteiro baseado no produto
  const getSuggestedScript = () => {
    if (!scenario) return null;
    const name = scenario.customerName;

    switch(scenario.product) {
      case 'TV':
        return {
          intro: `Olá ${name}, entendo perfeitamente sua dúvida sobre o Claro TV+...`,
          body: `Diferente do sistema antigo, agora você tem comando de voz direto no controle. É só apertar e falar o nome do filme! Além disso, Netflix e Globoplay já estão integrados, sem precisar mudar de entrada na TV.`,
          outro: `Ficou claro como essa facilidade vai ajudar no seu dia a dia?`
        };
      case 'Mesh':
        return {
          intro: `${name}, para resolver esse problema de sinal no seu escritório, a melhor solução é o Wi-Fi Mesh...`,
          body: `Ele cria uma rede única na casa toda. Diferente de um repetidor comum, ele não divide a velocidade; ele amplia a cobertura mantendo a estabilidade total para suas consultas de telemedicina.`,
          outro: `Podemos testar a posição dos cubos agora para garantir o sinal lá em cima?`
        };
      case 'Virtua':
        return {
          intro: `Com certeza ${name}, para quem joga online ou tem muita gente conectada, o Wi-Fi 6 da Claro é um diferencial...`,
          body: `Ele reduz a latência (o ping) e permite que mais aparelhos usem o máximo da velocidade simultaneamente sem travar o vídeo 4K de ninguém.`,
          outro: `É a tecnologia de ponta que sua família precisa para navegar sem estresse.`
        };
      default:
        return {
          intro: `Oi ${name}, vou te explicar como a Claro tem a melhor solução para você...`,
          body: `Nosso serviço foca em entregar estabilidade e os benefícios que realmente importam para o seu perfil de uso.`,
          outro: `O que você achou dessa facilidade?`
        };
    }
  };

  const script = getSuggestedScript();

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 animate-fadeIn max-w-6xl mx-auto">

      {/* Coluna da Esquerda: Vídeo e Controles */}
      <div className="lg:col-span-7 flex flex-col space-y-4">
        <div className="relative aspect-video bg-black rounded-[32px] overflow-hidden shadow-2xl border-4 border-white">
          {!recordedBlob ? (
            <video 
              ref={videoRef} 
              autoPlay 
              muted 
              playsInline 
              className="w-full h-full object-cover mirror scale-x-[-1]"
            />
          ) : (
            <video 
              src={URL.createObjectURL(recordedBlob)} 
              controls 
              className="w-full h-full object-cover"
            />
          )}

          {isRecording && (
            <div className="absolute top-6 left-6 flex items-center gap-3 bg-red-600 px-4 py-2 rounded-full text-white text-xs font-black animate-pulse shadow-lg">
              <div className="w-2.5 h-2.5 bg-white rounded-full"></div>
              GRAVANDO RESPOSTA
            </div>
          )}

          {!recordedBlob && !isRecording && (
            <div className="absolute inset-0 flex items-center justify-center bg-black/40 backdrop-blur-[2px]">
              <p className="text-white font-black text-sm uppercase tracking-widest text-center px-10">
                Posicione-se bem no centro <br/> e clique no botão para começar
              </p>
            </div>
          )}
        </div>

        <div className="flex justify-center items-center gap-4 py-4">
          {!recordedBlob ? (
            <button 
              onClick={isRecording ? handleStopRecording : handleStartRecording}
              className={`w-20 h-20 rounded-full border-8 transition-all flex items-center justify-center shadow-xl ${
                isRecording ? 'border-gray-200 bg-white' : 'border-red-100 bg-[#ee0000] hover:scale-105'
              }`}
            >
              {isRecording ? (
                <div className="w-6 h-6 bg-[#ee0000] rounded-sm"></div>
              ) : (
                <div className="w-7 h-7 bg-white rounded-full"></div>
              )}
            </button>
          ) : (
            <div className="flex w-full gap-3">
              <button 
                onClick={handleRepeat}
                className="flex-1 bg-gray-100 text-gray-600 font-black text-xs uppercase py-5 rounded-3xl hover:bg-gray-200 transition-colors"
              >
                Tentar novamente
              </button>
              <button 
                onClick={handleSend}
                className="flex-[2] claro-red text-white font-black text-xs uppercase py-5 rounded-3xl shadow-lg hover:bg-red-700 transition-colors"
              >
                Enviar para IA Avaliar
              </button>
            </div>
          )}
        </div>
      </div>

      {/* Coluna da Direita: Roteiro e Dicas */}
      <div className="lg:col-span-5 space-y-4 h-full">
        {/* Roteiro Sugerido */}
        <div className="bg-white p-6 rounded-[32px] shadow-sm border border-gray-100 flex flex-col h-fit">
          <div className="flex items-center gap-2 mb-4">
            <span className="text-[10px] font-black claro-text-red uppercase tracking-widest border-b-2 claro-border-red pb-1">Sugestão de Roteiro</span>
          </div>

          <div className="space-y-4">
            <div>
              <span className="text-[8px] font-bold text-gray-300 uppercase">Abertura</span>
              <p className="text-sm text-gray-700 font-medium leading-relaxed italic">"{script?.intro}"</p>
            </div>
            <div className="p-4 bg-red-50 rounded-2xl border-l-4 claro-border-red">
              <span className="text-[8px] font-bold claro-text-red uppercase">Desenvolvimento (Foco em Benefício)</span>
              <p className="text-sm text-gray-800 font-bold leading-relaxed">{script?.body}</p>
            </div>
            <div>
              <span className="text-[8px] font-bold text-gray-300 uppercase">Fechamento</span>
              <p className="text-sm text-gray-700 font-medium leading-relaxed italic">"{script?.outro}"</p>
            </div>
          </div>
        </div>

        {/* Dicas de Gravação */}
        <div className="bg-gray-900 p-6 rounded-[32px] text-white shadow-xl">
          <h4 className="text-[10px] font-black uppercase tracking-[0.2em] mb-4 text-gray-400">Checklist de Gravação:</h4>
          <ul className="space-y-3">
            <li className="flex items-center gap-3">
              <div className="w-5 h-5 rounded-full bg-green-500 flex items-center justify-center text-[10px]">✓</div>
              <span className="text-xs font-medium text-gray-300">Mantenha o celular na altura dos olhos.</span>
            </li>
            <li className="flex items-center gap-3">
              <div className="w-5 h-5 rounded-full bg-green-500 flex items-center justify-center text-[10px]">✓</div>
              <span className="text-xs font-medium text-gray-300">Fale de forma clara, sem pressa.</span>
            </li>
            <li className="flex items-center gap-3">
              <div className="w-5 h-5 rounded-full bg-green-500 flex items-center justify-center text-[10px]">✓</div>
              <span className="text-xs font-medium text-gray-300">Sorria e use as mãos para explicar.</span>
            </li>
            <li className="flex items-center gap-3">
              <div className="w-5 h-5 rounded-full bg-orange-500 flex items-center justify-center text-[10px]">!</div>
              <span className="text-xs font-medium text-gray-300">Cuidado com barulhos de fundo.</span>
            </li>
          </ul>
        </div>

        <button 
          onClick={onCancel}
          className="w-full text-gray-400 hover:text-red-500 text-[10px] font-black uppercase tracking-widest py-2 transition-colors"
        >
          Cancelar e voltar
        </button>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { User, Evaluation as EvalModel, AccessLog } from './types';
import { DB } from './db';
import { Layout } from './components/Layout';
import { Login } from './pages/Login';
import { Register } from './pages/Register';
import { Dashboard } from './pages/Dashboard';
import { Consultivo } from './pages/Consultivo';
import { Recorder } from './pages/Recorder';
import { EvaluationResult } from './pages/EvaluationResult';
import { AdminDashboard } from './pages/AdminDashboard';
import { evaluateExplanation, EvaluationResult as AIResult } from './services/geminiService';
import { MediaStorage } from './services/storageService';

const LOADING_MESSAGES = [
  "A Inteligência Artificial está ouvindo sua explicação...",
  "Analisando a clareza técnica do produto...",
  "Comparando com os padrões de excelência Claro...",
  "Avaliando empatia e tom de voz...",
  "Identificando seus pontos fortes...",
  "Gerando sugestões personalizadas para você...",
  "Quase lá! Finalizando seu relatório de performance..."
];

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<string>('login');
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(false);
  const [loadingMsgIdx, setLoadingMsgIdx] = useState(0);
  const [lastEval, setLastEval] = useState<AIResult | null>(null);
  const [activeScenario, setActiveScenario] = useState<any>(null);

  useEffect(() => {
    MediaStorage.init().catch(err => console.error("Falha ao iniciar IndexedDB:", err));

    const savedUser = localStorage.getItem('explica_session');
    if (savedUser) {
      const u = JSON.parse(savedUser);
      const freshUser = DB.users.findById(u.id);
      if (freshUser) {
        setUser(freshUser);
        setCurrentPage('dashboard');
      } else {
        localStorage.removeItem('explica_session');
      }
    }
  }, []);

  // Cycle messages during loading
  useEffect(() => {
    let interval: any;
    if (loading) {
      interval = setInterval(() => {
        setLoadingMsgIdx((prev) => (prev + 1) % LOADING_MESSAGES.length);
      }, 3000);
    } else {
      setLoadingMsgIdx(0);
    }
    return () => clearInterval(interval);
  }, [loading]);

  const handleLogin = (cpf: string, pass: string) => {
    const foundUser = DB.users.findByCpf(cpf);
    if (foundUser && (foundUser.password === pass || foundUser.role === 'admin' || foundUser.role === 'superadmin')) {
      setUser(foundUser);
      localStorage.setItem('explica_session', JSON.stringify(foundUser));

      DB.accesses.add({
        id: Math.random().toString(36).substr(2, 9),
        userId: foundUser.id,
        userName: foundUser.name,
        timestamp: new Date().toISOString(),
        uf: foundUser.uf,
        city: foundUser.city
      });

      setCurrentPage('dashboard');
    } else {
      alert("Credenciais inválidas");
    }
  };

  const handleRegister = (data: Partial<User>) => {
    const newId = `tech-${Math.random().toString(36).substr(2, 9)}`;
    const newUser: User = {
      ...data,
      id: newId,
      role: 'tech',
      createdAt: new Date().toISOString()
    } as User;

    DB.users.add(newUser);
    alert(`Técnico cadastrado com sucesso! ID: ${newId}. Faça login com seu CPF.`);
    setCurrentPage('login');
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('explica_session');
    setCurrentPage('login');
  };

  const handleHome = () => {
    if (user) {
      setCurrentPage('dashboard');
    }
  };

  const handleStartScenario = (scenario: any) => {
    setActiveScenario(scenario);
    setCurrentPage('recorder');
  };

  const handleRecorderComplete = async (video: Blob) => {
    setLoading(true);
    try {
      const evalId = Math.random().toString(36).substr(2, 9);

      await MediaStorage.save(evalId, video);

      const reader = new FileReader();
      const base64Promise = new Promise<string>((resolve) => {
        reader.onloadend = () => resolve(reader.result as string);
        reader.readAsDataURL(video);
      });

      const base64Video = await base64Promise;

      const scenarioContext = activeScenario ? 
        `Cenário: Atendimento para ${activeScenario.customerName}. Produto: ${activeScenario.product}. Dúvida do cliente: ${activeScenario.question}` 
        : undefined;

      const result = await evaluateExplanation(base64Video, undefined, scenarioContext);

      if (user) {
        DB.evaluations.add({
          id: evalId,
          userId: user.id,
          userName: user.name,
          timestamp: new Date().toISOString(),
          score: result.score,
          strengths: result.strengths,
          weaknesses: result.weaknesses,
          suggestions: result.suggestions,
          transcript: result.transcript,
          uf: user.uf,
          city: user.city
        });
      }

      setLastEval(result);
      setCurrentPage('result');
    } catch (err) {
      console.error(err);
      alert("Erro ao avaliar vídeo. Tente novamente.");
    } finally {
      setLoading(false);
    }
  };

  const renderContent = () => {
    if (loading) {
      return (
        <div className="flex flex-col items-center justify-center min-h-[60vh] space-y-12 animate-fadeIn">
          {/* Animated Dots Container */}
          <div className="flex items-center justify-center space-x-4">
            <div className="w-6 h-6 claro-red rounded-full dot-1"></div>
            <div className="w-6 h-6 claro-red rounded-full dot-2"></div>
            <div className="w-6 h-6 claro-red rounded-full dot-3"></div>
          </div>

          <div className="text-center space-y-4 max-w-sm">
            <h3 className="text-xl font-black claro-text-red uppercase tracking-tight animate-pulse">
              Explica+ IA
            </h3>
            <div key={loadingMsgIdx} className="animate-slideUpFade">
              <p className="text-gray-700 font-bold text-lg leading-snug">
                {LOADING_MESSAGES[loadingMsgIdx]}
              </p>
              <p className="text-gray-400 text-sm mt-2">
                Isso pode levar alguns segundos.
              </p>
            </div>
          </div>

          {/* Visual Feedback Line */}
          <div className="w-full max-w-xs h-1 bg-gray-100 rounded-full overflow-hidden">
            <div className="h-full claro-red w-1/2 animate-[progress_2s_infinite_linear]"></div>
          </div>
          <style>{`
            @keyframes progress {
              0% { transform: translateX(-100%); }
              100% { transform: translateX(200%); }
            }
          `}</style>
        </div>
      );
    }

    switch (currentPage) {
      case 'login': return <Login onLogin={handleLogin} onGoToRegister={() => setCurrentPage('register')} />;
      case 'register': return <Register onRegister={handleRegister} onBack={() => setCurrentPage('login')} />;
      case 'dashboard': return user ? <Dashboard user={user} onNavigate={setCurrentPage} /> : null;
      case 'consultivo': return <Consultivo onStart={handleStartScenario} onBack={() => setCurrentPage('dashboard')} />;
      case 'recorder': return <Recorder scenario={activeScenario} onComplete={handleRecorderComplete} onCancel={() => setCurrentPage('consultivo')} />;
      case 'result': return lastEval ? <EvaluationResult result={lastEval} onFinish={() => setCurrentPage('dashboard')} /> : null;
      case 'admin': return user ? <AdminDashboard currentUser={user} /> : null;
      default: return <Login onLogin={handleLogin} onGoToRegister={() => setCurrentPage('register')} />;
    }
  };

  return (
    <Layout 
      user={user} 
      onLogout={handleLogout} 
      onHome={handleHome} 
      onAdminClick={() => setCurrentPage('admin')}
      title={currentPage === 'admin' ? 'Painel Administrativo' : undefined}
    >
      {renderContent()}
    </Layout>
  );
};

