        {/* Coluna da Esquerda: Vídeo */}
        <div className="lg:col-span-7 flex flex-col space-y-4">
          <div className="relative aspect-video bg-black rounded-[32px] overflow-hidden shadow-2xl border-4 border-white">
            {!recordedBlob ? (
              <video 
                ref={videoRef} 
                autoPlay 
                muted 
                playsInline 
                className="w-full h-full object-cover mirror scale-x-[-1]"
              />
            ) : (
              <video 
                src={URL.createObjectURL(recordedBlob)} 
                controls 
                className="w-full h-full object-cover"
              />
            )}

            {isRecording && (
              <div className="absolute top-6 left-6 flex items-center gap-3 bg-red-600 px-4 py-2 rounded-full text-white text-[10px] font-black animate-pulse shadow-lg">
                <div className="w-2 h-2 bg-white rounded-full"></div>
                GRAVANDO...
              </div>
            )}

            {!recordedBlob && !isRecording && (
              <div className="absolute inset-0 flex items-center justify-center bg-black/40 backdrop-blur-[2px]">
                <p className="text-white font-black text-xs uppercase tracking-widest text-center px-10">
