import React, { useRef, useState, useEffect } from 'react';

interface Scenario {
  id: string;
  title: string;
  product: 'Virtua' | 'TV' | 'Mesh' | 'Móvel';
  customerName: string;
  customerProfile: string;
  image: string;
  question: string;
  evalCriteria: string[];
}

interface RecorderProps {
  onComplete: (videoBlob: Blob, audioBlob: Blob) => void;
  onCancel: () => void;
  scenario: Scenario | null;
}

export const Recorder: React.FC<RecorderProps> = ({ onComplete, onCancel, scenario }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const [isRecording, setIsRecording] = useState(false);
  const [recordedBlob, setRecordedBlob] = useState<Blob | null>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const chunks = useRef<Blob[]>([]);

  const startCamera = async () => {
    try {
      const s = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'user', width: { ideal: 1280 }, height: { ideal: 720 } }, 
        audio: true 
      });
      setStream(s);
      if (videoRef.current) {
        videoRef.current.srcObject = s;
      }
    } catch (err) {
      alert("Não foi possível acessar a câmera ou microfone.");
      onCancel();
    }
  };

  useEffect(() => {
    startCamera();
    return () => {
      stream?.getTracks().forEach(track => track.stop());
    };
  }, []);

  const handleStartRecording = () => {
    if (!stream) return;
    chunks.current = [];
    const recorder = new MediaRecorder(stream);
    recorder.ondataavailable = (e) => {
      if (e.data.size > 0) chunks.current.push(e.data);
    };
    recorder.onstop = () => {
      const blob = new Blob(chunks.current, { type: 'video/mp4' });
      setRecordedBlob(blob);
    };
    recorder.start();
    mediaRecorderRef.current = recorder;
    setIsRecording(true);
  };

  const handleStopRecording = () => {
    mediaRecorderRef.current?.stop();
    setIsRecording(false);
  };

  const handleRepeat = () => {
    setRecordedBlob(null);
    startCamera();
  };

  const handleSend = () => {
    if (recordedBlob) {
      onComplete(recordedBlob, recordedBlob);
    }
  };

  const getSuggestedScript = () => {
    if (!scenario) return null;
    const name = scenario.customerName;

    switch(scenario.product) {
      case 'TV':
        return {
          intro: `Olá ${name}, entendo perfeitamente sua dúvida sobre o Claro TV+...`,
          body: `Diferente do sistema antigo, agora você tem comando de voz direto no controle. É só apertar e falar o nome do filme! Além disso, Netflix e Globoplay já estão integrados, sem precisar mudar de entrada na TV.`,
          outro: `Ficou claro como essa facilidade vai ajudar no seu dia a dia?`
        };
      case 'Mesh':
        return {
          intro: `${name}, para resolver esse problema de sinal no seu escritório, a melhor solução é o Wi-Fi Mesh...`,
          body: `Ele cria uma rede única na casa toda. Diferente de um repetidor comum, ele não divide a velocidade; ele amplia a cobertura mantendo a estabilidade total para suas consultas de telemedicina.`,
          outro: `Podemos testar a posição dos cubos agora para garantir o sinal lá em cima?`
        };
      case 'Virtua':
        return {
          intro: `Com certeza ${name}, para quem joga online ou tem muita gente conectada, o Wi-Fi 6 da Claro é um diferencial...`,
          body: `Ele reduz a latência (o ping) e permite que mais aparelhos usem o máximo da velocidade simultaneamente sem travar o vídeo 4K de ninguém.`,
          outro: `É a tecnologia de ponta que sua família precisa para navegar sem estresse.`
        };
      default:
        return {
          intro: `Oi ${name}, vou te explicar como a Claro tem a melhor solução para você...`,
          body: `Nosso serviço foca em entregar estabilidade e os benefícios que realmente importam para o seu perfil de uso.`,
          outro: `O que você achou dessa facilidade?`
        };
    }
  };

  const script = getSuggestedScript();

  return (
    <div className="flex flex-col space-y-6 animate-fadeIn max-w-6xl mx-auto pb-16">

      {/* Seção Superior: Vídeo e Roteiro */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">

        {/* Coluna da Esquerda: Vídeo e Controles Principais */}
        <div className="lg:col-span-7 flex flex-col space-y-4">
          <div className="relative aspect-video bg-black rounded-[32px] overflow-hidden shadow-2xl border-4 border-white">
            {!recordedBlob ? (
              <video 
                ref={videoRef} 
                autoPlay 
                muted 
                playsInline 
                className="w-full h-full object-cover mirror scale-x-[-1]"
              />
            ) : (
              <video 
                src={URL.createObjectURL(recordedBlob)} 
                controls 
                className="w-full h-full object-cover"
              />
            )}

            {isRecording && (
              <div className="absolute top-6 left-6 flex items-center gap-3 bg-red-600 px-4 py-2 rounded-full text-white text-[10px] font-black animate-pulse shadow-lg z-20">
                <div className="w-2 h-2 bg-white rounded-full"></div>
                GRAVANDO...
              </div>
            )}

            {!recordedBlob && !isRecording && (
              <div className="absolute inset-0 flex items-center justify-center bg-black/40 backdrop-blur-[2px] z-10">
                <p className="text-white font-black text-xs uppercase tracking-widest text-center px-10">
                  Prepare-se para explicar <br/> Clique abaixo para iniciar
                </p>
              </div>
            )}
          </div>

          {/* Grupo de Botões Centralizados Abaixo do Vídeo */}
          <div className="flex flex-col items-center gap-4 py-4">
            <div className="w-full flex justify-center items-center">
              {!recordedBlob ? (
                <button 
                  onClick={isRecording ? handleStopRecording : handleStartRecording}
                  className={`flex items-center gap-4 px-8 py-4 rounded-full border-4 transition-all shadow-xl font-black text-sm tracking-widest ${
                    isRecording 
                      ? 'border-gray-200 bg-white text-gray-700' 
                      : 'border-red-100 bg-[#ee0000] text-white hover:scale-105 active:scale-95'
                  }`}
                >
                  {isRecording ? (
                    <>
                      <div className="w-4 h-4 bg-[#ee0000] rounded-sm animate-pulse"></div>
                      PARAR GRAVAÇÃO
                    </>
                  ) : (
                    <>
                      <div className="w-4 h-4 bg-white rounded-full"></div>
                      INICIAR GRAVAÇÃO
                    </>
                  )}
                </button>
              ) : (
                <div className="flex w-full gap-3">
                  <button 
                    onClick={handleRepeat}
                    className="flex-1 bg-gray-100 text-gray-600 font-black text-[10px] uppercase py-4 rounded-2xl hover:bg-gray-200 transition-colors"
                  >
                    Regravar
                  </button>
                  <button 
                    onClick={handleSend}
                    className="flex-[2] claro-red text-white font-black text-[10px] uppercase py-4 rounded-2xl shadow-lg hover:bg-red-700 transition-colors"
                  >
                    Avaliar Performance
                  </button>
                </div>
              )}
            </div>

            {/* Botão Cancelar Reposicionado Abaixo do Botão de Ação */}
            {!isRecording && (
              <button 
                onClick={onCancel}
                className="text-gray-400 hover:text-[#ee0000] text-[10px] font-black uppercase tracking-[0.2em] py-2 transition-all flex items-center gap-2 group"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 group-hover:-translate-x-1 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
                </svg>
                Cancelar e voltar aos cenários
              </button>
            )}
          </div>
        </div>

        {/* Coluna da Direita: Roteiro Sugerido */}
        <div className="lg:col-span-5 h-full">
          <div className="bg-white p-6 rounded-[32px] shadow-sm border border-gray-100 flex flex-col h-full min-h-[350px]">
            <div className="flex items-center gap-2 mb-6">
              <span className="text-[10px] font-black claro-text-red uppercase tracking-widest border-b-2 claro-border-red pb-1">Roteiro Sugerido</span>
            </div>

            <div className="space-y-6 flex-1">
              <div>
                <span className="text-[8px] font-bold text-gray-300 uppercase tracking-widest">Abertura</span>
                <p className="text-sm text-gray-700 font-medium leading-relaxed italic mt-1">"{script?.intro}"</p>
              </div>
              <div className="p-5 bg-red-50 rounded-2xl border-l-4 claro-border-red">
                <span className="text-[8px] font-bold claro-text-red uppercase tracking-widest">Argumento Principal</span>
                <p className="text-sm text-gray-800 font-bold leading-relaxed mt-1">{script?.body}</p>
              </div>
              <div>
                <span className="text-[8px] font-bold text-gray-300 uppercase tracking-widest">Fechamento</span>
                <p className="text-sm text-gray-700 font-medium leading-relaxed italic mt-1">"{script?.outro}"</p>
              </div>
