          </div>
        </div>
      </div>

      {/* Seção Inferior: Checklist de Gravação (Centralizado) */}
      <div className="w-full max-w-2xl mx-auto">
        <div className="bg-gray-900 p-8 rounded-[40px] text-white shadow-2xl relative overflow-hidden">
