import React, { useRef, useState, useEffect } from 'react';

interface Scenario {
  id: string;
  title: string;
  product: 'Virtua' | 'TV' | 'Mesh' | 'Móvel';
  customerName: string;
  customerProfile: string;
  image: string;
  question: string;
  evalCriteria: string[];
}

interface RecorderProps {
  onComplete: (videoBlob: Blob, audioBlob: Blob) => void;
  onCancel: () => void;
  scenario: Scenario | null;
}

export const Recorder: React.FC<RecorderProps> = ({ onComplete, onCancel, scenario }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);

  const [isRecording, setIsRecording] = useState(false);
  const [recordedBlob, setRecordedBlob] = useState<Blob | null>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [activeLine, setActiveLine] = useState(0);
  const [showChecklist, setShowChecklist] = useState(false);
  const chunks = useRef<Blob[]>([]);

  const LINE_HEIGHT = 80;

  const startCamera = async () => {
    try {
      const s = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'user', width: { ideal: 1280 }, height: { ideal: 720 } }, 
        audio: true 
      });
      setStream(s);
      if (videoRef.current) {
        videoRef.current.srcObject = s;
      }
    } catch (err) {
      alert("Não foi possível acessar a câmera ou microfone.");
      onCancel();
    }
  };

  useEffect(() => {
    startCamera();
    return () => {
      stream?.getTracks().forEach(track => track.stop());
    };
  }, []);

  useEffect(() => {
    let interval: any;
    if (isRecording) {
      setActiveLine(0);
      interval = setInterval(() => {
        setActiveLine(prev => {
          if (prev < (fullScript?.length || 0) - 1) {
            return prev + 1;
          }
          return prev;
        });
      }, 4500);
    } else {
      setActiveLine(0);
      if (interval) clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [isRecording]);

  const handleStartRecording = () => {
    if (!stream) return;
    chunks.current = [];
    const recorder = new MediaRecorder(stream);
    recorder.ondataavailable = (e) => {
      if (e.data.size > 0) chunks.current.push(e.data);
    };
    recorder.onstop = () => {
      const blob = new Blob(chunks.current, { type: 'video/mp4' });
      setRecordedBlob(blob);
    };
    recorder.start();
    mediaRecorderRef.current = recorder;
    setIsRecording(true);
  };

  const handleStopRecording = () => {
    mediaRecorderRef.current?.stop();
    setIsRecording(false);
  };

  const handleRepeat = () => {
    setRecordedBlob(null);
    setActiveLine(0);
    startCamera();
  };

  const handleSend = () => {
    if (recordedBlob) {
      onComplete(recordedBlob, recordedBlob);
    }
  };

  const getFullScript = () => {
    if (!scenario) return [];
    const name = scenario.customerName;

    switch(scenario.product) {
      case 'TV':
        return [
          `Olá ${name}, tudo bem? Sou o técnico da Claro.`,
          `Entendo sua dúvida! O Claro TV+ é realmente incrível.`,
          `Sim, o controle tem comando de voz integrado.`,
          `Basta apertar o botão do microfone e dizer o que quer ver.`,
          `"Dona Helena, diga 'Netflix' e o app abre na hora!"`,
          `Não precisa mais decorar números de canais complexos.`,
          `Tudo o que a senhora gosta está em um só lugar.`,
          `Ficou claro como essa facilidade vai ajudar no seu dia?`
        ];
      case 'Mesh':
        return [
          `Oi Dr. Marcos, sou da Claro e vou resolver o sinal do seu escritório.`,
          `Para telemedicina, estabilidade é o fator mais importante.`,
          `O Wi-Fi Mesh cria uma malha inteligente em toda a sua casa.`,
          `Diferente de um repetidor, ele não derruba a velocidade.`,
          `Ele mantém o mesmo sinal forte aqui e lá no andar de cima.`,
          `Sem precisar passar cabos ou fazer qualquer obra no imóvel.`,
          `Podemos testar agora e o senhor verá que a oscilação acabou.`,
          `O que achou dessa solução definitiva para suas consultas?`
        ];
      case 'Virtua':
        return [
          `E aí Enzo! Sou técnico da Claro. Bora baixar esse ping?`,
          `O Wi-Fi 6 que instalamos é tecnologia de ponta para gamers.`,
          `Ele usa frequências mais limpas, evitando o lag indesejado.`,
          `Diferente da fibra comum, nossa rede tem baixa latência (jitter).`,
          `Isso significa que sua reação no FPS será muito mais rápida.`,
          `A largura de banda permite que você jogue enquanto outros assistem 4K.`,
          `É o setup ideal para quem busca performance competitiva.`,
          `Sentiu a diferença na estabilidade da conexão agora?`
        ];
      default:
        return [
          `Olá ${name}, sou o técnico da Claro e estou aqui para ajudar.`,
          `Nossos produtos são pensados para facilitar sua vida.`,
          `A tecnologia que estamos instalando é a melhor do mercado.`,
          `Foco total na sua estabilidade e conforto digital.`,
          `Qualquer dúvida que tiver, pode me perguntar agora.`,
          `A Claro agradece a sua confiança no nosso trabalho.`,
          `Tudo certo com a sua nova conexão?`
        ];
    }
  };

  const fullScript = getFullScript();

  return (
    <div className="flex flex-col space-y-6 animate-fadeIn max-w-6xl mx-auto pb-16">

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-stretch">

        <div className="lg:col-span-5 flex flex-col space-y-4">
          <div className="relative aspect-[3/4] lg:aspect-square bg-black rounded-[32px] overflow-hidden shadow-2xl border-4 border-white">
            {!recordedBlob ? (
              <video 
                ref={videoRef} 
                autoPlay 
                muted 
                playsInline 
                className="w-full h-full object-cover mirror scale-x-[-1]"
              />
            ) : (
              <video 
                src={URL.createObjectURL(recordedBlob)} 
                controls 
                className="w-full h-full object-cover"
              />
            )}

            {isRecording && (
              <div className="absolute top-6 left-6 flex items-center gap-3 bg-red-600 px-4 py-2 rounded-full text-white text-[10px] font-black animate-pulse shadow-lg z-20">
                <div className="w-2 h-2 bg-white rounded-full"></div>
                GRAVANDO...
              </div>
            )}

            {!recordedBlob && !isRecording && (
              <div className="absolute inset-0 flex items-center justify-center bg-black/40 backdrop-blur-[2px] z-10">
                <div className="text-center">
                  <p className="text-white font-black text-xs uppercase tracking-widest mb-2">POSICIONE-SE</p>
                  <p className="text-white/60 text-[10px] font-medium uppercase tracking-tighter">Olhe para a câmera ao ler</p>
                </div>
              </div>
            )}
          </div>

          <div className="flex flex-col items-center gap-4 py-2">
            {!recordedBlob ? (
              <button 
                onClick={isRecording ? handleStopRecording : handleStartRecording}
                className={`flex items-center gap-4 px-10 py-5 rounded-full border-4 transition-all shadow-xl font-black text-sm tracking-widest ${
                  isRecording 
                    ? 'border-gray-200 bg-white text-gray-700' 
                    : 'border-red-100 bg-[#ee0000] text-white hover:scale-105 active:scale-95'
                }`}
              >
                {isRecording ? (
                  <>
                    <div className="w-4 h-4 bg-[#ee0000] rounded-sm animate-pulse"></div>
                    CONCLUIR EXPLICAÇÃO
                  </>
                ) : (
                  <>
                    <div className="w-4 h-4 bg-white rounded-full"></div>
                    INICIAR GRAVAÇÃO
                  </>
                )}
              </button>
            ) : (
              <div className="flex w-full gap-3">
                <button 
