import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export interface EvaluationResult {
  score: number;
  strengths: string;
  weaknesses: string;
  suggestions: string;
  transcript: string;
}

export const evaluateExplanation = async (
  videoBase64?: string, 
  audioBase64?: string, 
  scenarioContext?: string
): Promise<EvaluationResult> => {
  const contextPrompt = scenarioContext ? 
    `CONTEXTO DO CENÁRIO ESPECÍFICO: ${scenarioContext}. Avalie se o técnico respondeu diretamente à dúvida do cliente e se usou argumentos corretos para este produto.` : 
    "Avalie uma explicação técnica geral sobre os produtos Claro.";

  const prompt = `
    Você é um avaliador de excelência de atendimento da Claro especializado em feedback para técnicos de campo.
    ${contextPrompt}

    IMPORTANTE: Não avalie apenas se o técnico leu o roteiro (karaokê) corretamente. Valorize a NATURALIDADE e CONVICÇÃO.

    Analise o vídeo e o áudio sob estes novos critérios:
    1. Expressão e Postura (Visual): O técnico mantém contato visual com a lente? Ele demonstra confiança através de expressões faciais amigáveis e sorriso? A postura é profissional ou parece "robótica/lida"?
    2. Nitidez e Clareza: A explicação é "sharp" (afiada)? Ele consegue ser direto e claro nos benefícios técnicos sem hesitação excessiva?
    3. Empatia Real: O tom de voz condiz com o perfil do cliente do cenário? Ele parece estar conversando ou apenas recitando um texto?
    4. Linguagem Não-Verbal: Identifique gestos ou expressões que reforçam ou enfraquecem a autoridade do técnico.

    Retorne o resultado estritamente em JSON.
  `;

  try {
    const parts: any[] = [
      { text: prompt }
    ];

    if (videoBase64) {
      parts.push({
        inlineData: {
          data: videoBase64.split(',')[1],
          mimeType: 'video/mp4'
        }
      });
    }

    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: { parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            score: { type: Type.NUMBER, description: "Nota final de 0 a 10 baseada na nitidez e expressão" },
            strengths: { type: Type.STRING, description: "Destaque as expressões positivas e pontos fortes da fala" },
            weaknesses: { type: Type.STRING, description: "Onde a nitidez falhou ou a postura foi inadequada" },
            suggestions: { type: Type.STRING, description: "Dica prática sobre olhar, voz ou gestos para a próxima" },
            transcript: { type: Type.STRING, description: "Transcrição fiel do que foi dito" }
          },
          required: ["score", "strengths", "weaknesses", "suggestions", "transcript"]
        }
      }
    });

    const jsonStr = response.text?.trim() || '{}';
    const result = JSON.parse(jsonStr);

    return {
      score: result.score || 0,
      strengths: result.strengths || "Não foi possível identificar pontos fortes.",
      weaknesses: result.weaknesses || "Não foi possível identificar pontos fracos.",
      suggestions: result.suggestions || "Continue praticando os cenários!",
      transcript: result.transcript || "[Transcrição indisponível]"
    };
  } catch (error) {
    console.error("Erro na avaliação Gemini:", error);
    throw error;
  }
};

import React, { useState, useEffect, useCallback } from 'react';
import { User, Evaluation as EvalModel, AccessLog } from './types';
import { DB } from './db';
import { Layout } from './components/Layout';
import { Login } from './pages/Login';
import { Register } from './pages/Register';
import { Dashboard } from './pages/Dashboard';
import { Consultivo } from './pages/Consultivo';
import { Recorder } from './pages/Recorder';
import { EvaluationResult } from './pages/EvaluationResult';
import { AdminDashboard } from './pages/AdminDashboard';
import { evaluateExplanation, EvaluationResult as AIResult } from './services/geminiService';
import { MediaStorage } from './services/storageService';

const LOADING_MESSAGES = [
  "A Inteligência Artificial está analisando seu vídeo...",
  "Observando expressões faciais e postura...",
  "Avaliando a nitidez da sua explicação...",
  "Medindo o nível de empatia e conexão...",
  "Comparando com os padrões de excelência Claro...",
  "Identificando micro-expressões de confiança...",
  "Gerando seu relatório detalhado de performance..."
];

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<string>('login');
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(false);
  const [loadingMsgIdx, setLoadingMsgIdx] = useState(0);
  const [lastEval, setLastEval] = useState<AIResult | null>(null);
  const [activeScenario, setActiveScenario] = useState<any>(null);

  useEffect(() => {
    MediaStorage.init().catch(err => console.error("Falha ao iniciar IndexedDB:", err));

    const savedUser = localStorage.getItem('explica_session');
    if (savedUser) {
      const u = JSON.parse(savedUser);
      const freshUser = DB.users.findById(u.id);
      if (freshUser) {
        setUser(freshUser);
        setCurrentPage('dashboard');
      } else {
        localStorage.removeItem('explica_session');
      }
    }
  }, []);

  useEffect(() => {
    let interval: any;
    if (loading) {
      interval = setInterval(() => {
        setLoadingMsgIdx((prev) => (prev + 1) % LOADING_MESSAGES.length);
      }, 3500);
    } else {
      setLoadingMsgIdx(0);
    }
    return () => clearInterval(interval);
  }, [loading]);

  const handleLogin = (cpf: string, pass: string) => {
    const foundUser = DB.users.findByCpf(cpf);
    if (foundUser && (foundUser.password === pass || foundUser.role === 'admin' || foundUser.role === 'superadmin')) {
      setUser(foundUser);
      localStorage.setItem('explica_session', JSON.stringify(foundUser));

      DB.accesses.add({
        id: Math.random().toString(36).substr(2, 9),
        userId: foundUser.id,
        userName: foundUser.name,
        timestamp: new Date().toISOString(),
        uf: foundUser.uf,
        city: foundUser.city
      });

      setCurrentPage('dashboard');
    } else {
      alert("Credenciais inválidas");
    }
  };

  const handleRegister = (data: Partial<User>) => {
    const newId = `tech-${Math.random().toString(36).substr(2, 9)}`;
    const newUser: User = {
      ...data,
      id: newId,
      role: 'tech',
      createdAt: new Date().toISOString()
    } as User;

    DB.users.add(newUser);
    alert(`Técnico cadastrado com sucesso! ID: ${newId}. Faça login com seu CPF.`);
    setCurrentPage('login');
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('explica_session');
    setCurrentPage('login');
  };

  const handleHome = () => {
    if (user) {
      setCurrentPage('dashboard');
    }
  };

  const handleStartScenario = (scenario: any) => {
    setActiveScenario(scenario);
    setCurrentPage('recorder');
  };

  const handleRecorderComplete = async (video: Blob) => {
    setLoading(true);
    try {
      const evalId = Math.random().toString(36).substr(2, 9);

      await MediaStorage.save(evalId, video);

      const reader = new FileReader();
      const base64Promise = new Promise<string>((resolve) => {
        reader.onloadend = () => resolve(reader.result as string);
        reader.readAsDataURL(video);
      });

      const base64Video = await base64Promise;

      const scenarioContext = activeScenario ? 
        `Cenário: Atendimento para ${activeScenario.customerName}. Produto: ${activeScenario.product}. Dúvida do cliente: ${activeScenario.question}` 
        : undefined;

      const result = await evaluateExplanation(base64Video, undefined, scenarioContext);

      if (user) {
        DB.evaluations.add({
          id: evalId,
          userId: user.id,
          userName: user.name,
          timestamp: new Date().toISOString(),
          score: result.score,
          strengths: result.strengths,
          weaknesses: result.weaknesses,
          suggestions: result.suggestions,
          transcript: result.transcript,
          uf: user.uf,
          city: user.city
        });
      }

      setLastEval(result);
      setCurrentPage('result');
    } catch (err) {
      console.error(err);
      alert("Erro ao avaliar vídeo. Tente novamente.");
    } finally {
      setLoading(false);
    }
  };

  const renderContent = () => {
    if (loading) {
      return (
        <div className="flex flex-col items-center justify-center min-h-[60vh] space-y-10 animate-fadeIn text-center">

          {/* Claro SOL Loading Animation */}
          <div className="relative w-32 h-32 flex items-center justify-center">
            {/* Sun Rays */}
            <div className="absolute inset-0 animate-[spin_6s_linear_infinite]">
              {[...Array(12)].map((_, i) => (
                <div 
                  key={i}
                  className="absolute top-1/2 left-1/2 w-1.5 h-6 claro-red rounded-full origin-bottom"
                  style={{ 
                    transform: `translate(-50%, -100%) rotate(${i * 30}deg)`,
                    marginTop: '-24px',
                    opacity: 1 - (i * 0.05)
                  }}
                ></div>
              ))}
            </div>
            {/* Core Pulsing Circle */}
            <div className="w-12 h-12 claro-red rounded-full shadow-[0_0_35px_rgba(238,0,0,0.5)] z-10 animate-pulse"></div>
          </div>

          <div className="space-y-4 max-w-sm px-6">
            <h3 className="text-xs font-black claro-text-red uppercase tracking-[0.4em] animate-pulse">
              Explica+ IA Vision
            </h3>
            <div key={loadingMsgIdx} className="animate-slideUpFade">
              <p className="text-gray-800 font-bold text-lg leading-tight min-h-[3.5rem]">
                {LOADING_MESSAGES[loadingMsgIdx]}
              </p>
              <p className="text-gray-400 text-[10px] mt-4 font-black uppercase tracking-widest">
                Análise Multimodal em curso
              </p>
            </div>
          </div>

          {/* Subtle Progress bar */}
          <div className="w-48 h-1 bg-gray-100 rounded-full overflow-hidden">
            <div className="h-full claro-red w-full animate-[loading_2.5s_ease-in-out_infinite]"></div>
          </div>

          <style>{`
            @keyframes loading {
              0% { transform: translateX(-100%); }
              50% { transform: translateX(0); }
              100% { transform: translateX(100%); }
            }
          `}</style>
        </div>
      );
    }

    switch (currentPage) {
      case 'login': return <Login onLogin={handleLogin} onGoToRegister={() => setCurrentPage('register')} />;
      case 'register': return <Register onRegister={handleRegister} onBack={() => setCurrentPage('login')} />;
      case 'dashboard': return user ? <Dashboard user={user} onNavigate={setCurrentPage} /> : null;
      case 'consultivo': return <Consultivo onStart={handleStartScenario} onBack={() => setCurrentPage('dashboard')} />;
      case 'recorder': return <Recorder scenario={activeScenario} onComplete={handleRecorderComplete} onCancel={() => setCurrentPage('consultivo')} />;
      case 'result': return lastEval ? <EvaluationResult result={lastEval} onFinish={() => setCurrentPage('dashboard')} /> : null;
      case 'admin': return user ? <AdminDashboard currentUser={user} /> : null;
      default: return <Login onLogin={handleLogin} onGoToRegister={() => setCurrentPage('register')} />;
    }
  };

  return (
    <Layout 
      user={user} 
      onLogout={handleLogout} 
      onHome={handleHome} 
      onAdminClick={() => setCurrentPage('admin')}
      title={currentPage === 'admin' ? 'Painel Administrativo' : undefined}
    >
      {renderContent()}
    </Layout>
  );
};

