      if (previewUrl) {
        URL.revokeObjectURL(previewUrl);
        setPreviewUrl(null);
      }

      const s = await navigator.mediaDevices.getUserMedia({ 
        video: { 
          facingMode: 'user', 
          width: { ideal: 1280 }, 
          height: { ideal: 720 } 
        }, 
        audio: true 
      });
      setStream(s);
      if (videoRef.current) {
        videoRef.current.srcObject = s;
      }
    } catch (err) {
      console.error("Erro ao acessar mídia:", err);
      alert("Não foi possível acessar a câmera ou microfone. Verifique as permissões do navegador.");
      onCancel();
    }
  };

  useEffect(() => {
    startCamera();
    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
      if (previewUrl) URL.revokeObjectURL(previewUrl);
    };
  }, []);

  useEffect(() => {
    let interval: any;
    if (isRecording) {
      setActiveLine(0);
      interval = setInterval(() => {
        setActiveLine(prev => {
          if (prev < (fullScript?.length || 0) - 1) {
            return prev + 1;
          }
          return prev;
        });
      }, 4500);
    } else {
      setActiveLine(0);
      if (interval) clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [isRecording]);

  const handleStartRecording = () => {
    if (!stream) return;

    // Detect supported mime type
    const mimeType = MediaRecorder.isTypeSupported('video/webm;codecs=vp8,opus') 
      ? 'video/webm;codecs=vp8,opus' 
      : 'video/mp4';

    chunks.current = [];
    const recorder = new MediaRecorder(stream, { mimeType });

    recorder.ondataavailable = (e) => {
      if (e.data && e.data.size > 0) {
        chunks.current.push(e.data);
      }
    };

    recorder.onstop = () => {
      const blob = new Blob(chunks.current, { type: recorder.mimeType });
      const url = URL.createObjectURL(blob);
      setRecordedBlob(blob);
      setPreviewUrl(url);

      // Stop camera stream to release resources during review
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
      setStream(null);
    };

    recorder.start(1000); // Collect data every second
    mediaRecorderRef.current = recorder;
    setIsRecording(true);
  };

  const handleStopRecording = () => {
    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
      mediaRecorderRef.current.stop();
    }
    setIsRecording(false);
  };

  const handleRepeat = () => {
    setRecordedBlob(null);
    if (previewUrl) URL.revokeObjectURL(previewUrl);
    setPreviewUrl(null);
    setActiveLine(0);
    startCamera();
  };

  const handleSend = () => {
    if (recordedBlob) {
      onComplete(recordedBlob, recordedBlob);
    }
  };

  const getFullScript = () => {
    if (!scenario) return [];
    const name = scenario.customerName;

    switch(scenario.product) {
      case 'TV':
        return [
