import React, { useRef, useState, useEffect } from 'react';

interface Scenario {
  id: string;
  title: string;
  product: 'Virtua' | 'TV' | 'Mesh' | 'Móvel';
  customerName: string;
  customerProfile: string;
  image: string;
  question: string;
  evalCriteria: string[];
}

interface RecorderProps {
  onComplete: (videoBlob: Blob, audioBlob: Blob) => void;
  onCancel: () => void;
  scenario: Scenario | null;
}

export const Recorder: React.FC<RecorderProps> = ({ onComplete, onCancel, scenario }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const previewVideoRef = useRef<HTMLVideoElement>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);

  const [isRecording, setIsRecording] = useState(false);
  const [recordedBlob, setRecordedBlob] = useState<Blob | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [activeLine, setActiveLine] = useState(0);
  const [showChecklist, setShowChecklist] = useState(false);
  const chunks = useRef<Blob[]>([]);

  const LINE_HEIGHT = 80;

  const startCamera = async () => {
    try {
      if (previewUrl) {
        URL.revokeObjectURL(previewUrl);
        setPreviewUrl(null);
      }

      // Constraints otimizadas para mobile e desktop
      const constraints = {
        video: { 
          facingMode: 'user', 
          width: { ideal: 720 }, 
          height: { ideal: 1280 }, // Orientação vertical prioritária para mobile
          aspectRatio: { ideal: 9/16 }
        }, 
        audio: {
          echoCancellation: true,
          noiseSuppression: true,
          autoGainControl: true
        } 
      };

      const s = await navigator.mediaDevices.getUserMedia(constraints);
      setStream(s);
      if (videoRef.current) {
        videoRef.current.srcObject = s;
      }
    } catch (err) {
      console.error("Erro ao acessar mídia:", err);
      alert("Não foi possível acessar a câmera ou microfone. Verifique as permissões do seu navegador ou celular.");
      onCancel();
    }
  };

  useEffect(() => {
    startCamera();
    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
      if (previewUrl) URL.revokeObjectURL(previewUrl);
    };
  }, []);

  useEffect(() => {
    let interval: any;
    if (isRecording) {
      setActiveLine(0);
      interval = setInterval(() => {
        setActiveLine(prev => {
          if (prev < (fullScript?.length || 0) - 1) {
            return prev + 1;
          }
          return prev;
        });
      }, 4500);
    } else {
      setActiveLine(0);
      if (interval) clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [isRecording]);

  const handleStartRecording = () => {
    if (!stream) return;

    // Suporte amplo de tipos para diferentes navegadores (iOS/Android/Desktop)
    const types = [
      'video/webm;codecs=vp9,opus',
      'video/webm;codecs=vp8,opus',
      'video/webm',
      'video/mp4', // Fallback para iOS
    ];

    const mimeType = types.find(type => MediaRecorder.isTypeSupported(type)) || '';

    chunks.current = [];
    const recorder = new MediaRecorder(stream, { mimeType });

    recorder.ondataavailable = (e) => {
      if (e.data && e.data.size > 0) {
        chunks.current.push(e.data);
      }
    };

    recorder.onstop = () => {
      const blob = new Blob(chunks.current, { type: recorder.mimeType || 'video/mp4' });
      const url = URL.createObjectURL(blob);
      setRecordedBlob(blob);
      setPreviewUrl(url);

      // Encerra stream da câmera para liberar hardware e focar no player de revisão
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
      setStream(null);
    };

    recorder.start(1000); 
    mediaRecorderRef.current = recorder;
    setIsRecording(true);
  };

  const handleStopRecording = () => {
    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
      mediaRecorderRef.current.stop();
    }
    setIsRecording(false);
  };

  const handleRepeat = () => {
    setRecordedBlob(null);
    if (previewUrl) URL.revokeObjectURL(previewUrl);
    setPreviewUrl(null);
    setActiveLine(0);
    startCamera();
  };

  const handleSend = () => {
    if (recordedBlob) {
      onComplete(recordedBlob, recordedBlob);
    }
  };

  const getFullScript = () => {
    if (!scenario) return [];
    const name = scenario.customerName;

    switch(scenario.product) {
      case 'TV':
        return [
          `Olá ${name}, tudo bem? Sou o técnico da Claro.`,
          `O Claro TV+ é realmente incrível.`,
          `Sim, o controle tem comando de voz integrado.`,
          `Basta apertar o microfone e dizer o que quer ver.`,
          `Diga "Netflix" e o app abre na hora!`,
          `Não precisa mais decorar números de canais.`,
          `Tudo o que a senhora gosta em um só lugar.`,
          `Ficou claro como essa facilidade vai ajudar?`
        ];
      case 'Mesh':
        return [
          `Oi Dr. Marcos, sou da Claro e vou resolver seu sinal.`,
          `Para telemedicina, estabilidade é fundamental.`,
          `O Wi-Fi Mesh cria uma malha inteligente na casa.`,
          `Diferente de um repetidor, não derruba a velocidade.`,
          `Mantém o sinal forte aqui e no andar de cima.`,
          `Sem precisar passar cabos ou fazer obra.`,
          `Podemos testar agora e verá que a oscilação acabou.`,
          `O que achou dessa solução definitiva?`
        ];
      case 'Virtua':
        return [
          `E aí Enzo! Sou técnico da Claro. Bora baixar esse ping?`,
          `O Wi-Fi 6 é tecnologia de ponta para gamers.`,
          `Ele usa frequências limpas, evitando o lag.`,
          `Nossa rede tem baixa latência (jitter).`,
          `Sua reação no FPS será muito mais rápida.`,
          `Larga banda permite jogar enquanto outros veem 4K.`,
          `É o setup ideal para performance competitiva.`,
          `Sentiu a diferença na estabilidade agora?`
        ];
      default:
        return [
          `Olá ${name}, sou o técnico da Claro.`,
          `Nossos produtos facilitam sua vida.`,
          `A tecnologia que instalamos é a melhor do mercado.`,
          `Foco total na sua estabilidade digital.`,
          `Qualquer dúvida, pode me perguntar agora.`,
          `A Claro agradece a sua confiança.`,
          `Tudo certo com a sua conexão?`
        ];
    }
  };

  const fullScript = getFullScript();

  return (
    <div className="flex flex-col space-y-4 animate-fadeIn max-w-4xl mx-auto pb-10 px-2 md:px-4">

      {/* Título de Contexto para Mobile */}
      <div className="lg:hidden text-center bg-white p-3 rounded-2xl shadow-sm border border-gray-100 mb-2">
        <h2 className="text-xs font-black claro-text-red uppercase tracking-widest">{scenario?.title || 'Treinamento'}</h2>
        <p className="text-[10px] text-gray-400 font-bold uppercase mt-1">Falando com: {scenario?.customerName}</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-4 md:gap-6 items-stretch">

        {/* Visualizador de Vídeo / Review */}
        <div className="lg:col-span-5 flex flex-col space-y-4">
          <div className="relative aspect-[3/4] bg-black rounded-[32px] overflow-hidden shadow-2xl border-4 border-white ring-1 ring-gray-100">
            {!previewUrl ? (
              <video 
                ref={videoRef} 
                autoPlay 
                muted 
                playsInline 
                className="w-full h-full object-cover mirror scale-x-[-1]"
              />
            ) : (
              <video 
                ref={previewVideoRef}
                src={previewUrl} 
                controls 
                playsInline
                webkit-playsinline="true"
                className="w-full h-full object-cover"
                autoPlay
              />
            )}

            {isRecording && (
              <div className="absolute top-4 left-4 flex items-center gap-2 bg-red-600 px-3 py-1.5 rounded-full text-white text-[9px] font-black animate-pulse shadow-lg z-20">
                <div className="w-1.5 h-1.5 bg-white rounded-full"></div>
                GRAVANDO...
              </div>
            )}

            {previewUrl && (
              <div className="absolute top-4 left-4 flex items-center gap-2 bg-blue-600 px-3 py-1.5 rounded-full text-white text-[9px] font-black shadow-lg z-20">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
                </svg>
                REVISÃO DE VÍDEO
              </div>
            )}
          </div>

          <div className="flex flex-col items-center gap-3">
            {!previewUrl ? (
              <button 
                onClick={isRecording ? handleStopRecording : handleStartRecording}
                className={`w-full flex items-center justify-center gap-3 py-5 rounded-full border-4 transition-all shadow-xl font-black text-sm tracking-widest ${
                  isRecording 
                    ? 'border-gray-200 bg-white text-gray-700 hover:bg-gray-50' 
                    : 'border-red-100 bg-[#ee0000] text-white hover:bg-red-700 active:scale-95'
                }`}
              >
                {isRecording ? (
                  <>
                    <div className="w-3 h-3 bg-[#ee0000] rounded-sm animate-pulse"></div>
                    PARAR GRAVAÇÃO
                  </>
                ) : (
                  <>
                    <div className="w-3 h-3 bg-white rounded-full"></div>
                    GRAVAR EXPLICAÇÃO
                  </>
                )}
              </button>
            ) : (
              <div className="w-full space-y-3">
                <div className="flex gap-2">
                  <button 
                    onClick={handleRepeat}
                    className="flex-1 bg-gray-100 text-gray-600 font-black text-[10px] uppercase py-5 rounded-2xl hover:bg-gray-200 transition-colors flex flex-col items-center gap-1 shadow-sm"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
                    </svg>
                    Repetir Gravação
                  </button>
                  <button 
                    onClick={handleSend}
                    className="flex-[1.5] claro-red text-white font-black text-[10px] uppercase py-5 rounded-2xl shadow-lg hover:bg-red-700 transition-colors flex flex-col items-center gap-1"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
                    </svg>
                    Enviar Vídeo
                  </button>
                </div>
                <p className="text-center text-[9px] font-bold text-gray-400 uppercase tracking-widest">Confira se a explicação ficou clara antes de enviar</p>
              </div>
            )}
          </div>
        </div>

        {/* Teleprompter / Roteiro */}
        <div className="lg:col-span-7 flex flex-col min-h-[300px]">
          <div className="bg-gray-900 rounded-[32px] shadow-2xl overflow-hidden flex-1 flex flex-col relative border-4 border-gray-800">
            <div className="bg-gray-800 px-4 py-3 flex justify-between items-center">
              <span className="text-[9px] font-black text-red-500 uppercase tracking-widest">Roteiro Sugerido</span>
              <div className="flex gap-1.5">
                <div className={`w-1.5 h-1.5 rounded-full ${isRecording ? 'bg-red-500 animate-pulse' : 'bg-gray-600'}`}></div>
                <div className="w-1.5 h-1.5 rounded-full bg-gray-600"></div>
                <div className="w-1.5 h-1.5 rounded-full bg-gray-600"></div>
              </div>
            </div>

            <div className="relative flex-1 overflow-hidden flex items-center justify-center p-4 md:p-8">
              <div className="absolute inset-x-0 top-1/2 -translate-y-1/2 h-16 bg-red-600/10 border-y border-red-600/20 z-0"></div>

              <div 
                className="relative z-10 w-full transition-transform duration-700 ease-in-out text-center"
                style={{ transform: `translateY(${(fullScript.length / 2 - activeLine - 0.5) * LINE_HEIGHT}px)` }}
              >
                {fullScript.map((line, idx) => (
                  <div 
                    key={idx}
                    className={`h-20 flex items-center justify-center px-4 transition-all duration-500 leading-tight ${
                      idx === activeLine 
                        ? 'text-white text-xl md:text-2xl font-black opacity-100 scale-105' 
                        : 'text-gray-600 text-sm md:text-lg font-bold opacity-20 scale-90'
                    }`}
                  >
                    {line}
                  </div>
                ))}
              </div>

              {!isRecording && !previewUrl && (
                <div className="absolute bottom-6 left-0 right-0 text-center">
                  <p className="text-[9px] font-black text-gray-500 uppercase tracking-widest animate-bounce">
                    O texto rolará automaticamente ao iniciar
                  </p>
                </div>
              )}
            </div>

            <div className="h-1 bg-gray-800 w-full">
              <div 
                className="h-full bg-red-600 transition-all duration-1000 ease-linear"
                style={{ width: `${((activeLine + 1) / fullScript.length) * 100}%` }}
              ></div>
            </div>
          </div>
        </div>
      </div>

      {/* Ações de Suporte */}
      <div className="flex flex-col items-center gap-4 pt-2">
        {!isRecording && !previewUrl && (
          <button 
            onClick={() => setShowChecklist(true)}
            className="text-gray-400 hover:text-gray-600 text-[10px] font-black uppercase tracking-widest py-2 px-6 border border-gray-200 rounded-full transition-all flex items-center gap-2"
          >
            Ver Checklist de Qualidade
          </button>
        )}

        {!isRecording && (
          <button 
            onClick={onCancel}
            className="text-gray-300 hover:text-[#ee0000] text-[9px] font-black uppercase tracking-widest transition-all"
          >
            Sair do Treinamento
          </button>
        )}
      </div>

      {/* Checklist Modal */}
      {showChecklist && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/70 backdrop-blur-sm animate-fadeIn">
          <div className="bg-white w-full max-w-sm p-8 rounded-[40px] text-gray-800 shadow-2xl relative animate-scaleUp">
            <button onClick={() => setShowChecklist(false)} className="absolute top-6 right-6 text-gray-400 hover:text-gray-600">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
            </button>
            <div className="text-center space-y-6">
              <h4 className="text-xs font-black uppercase tracking-widest text-[#ee0000]">Dicas para o Sucesso</h4>
              <ul className="text-left space-y-4">
                <li className="flex items-center gap-3 text-xs font-bold text-gray-600">
                  <div className="w-2 h-2 rounded-full bg-green-500"></div> Olhe diretamente para a câmera
                </li>
                <li className="flex items-center gap-3 text-xs font-bold text-gray-600">
                  <div className="w-2 h-2 rounded-full bg-green-500"></div> Fale de forma clara e pausada
                </li>
                <li className="flex items-center gap-3 text-xs font-bold text-gray-600">
                  <div className="w-2 h-2 rounded-full bg-green-500"></div> Procure um local bem iluminado
                </li>
                <li className="flex items-center gap-3 text-xs font-bold text-gray-600">
                  <div className="w-2 h-2 rounded-full bg-orange-500"></div> Evite barulhos externos
                </li>
              </ul>
              <button onClick={() => setShowChecklist(false)} className="w-full py-4 claro-red text-white rounded-2xl font-black text-[10px] uppercase shadow-lg">Entendi</button>
            </div>
          </div>
        </div>
      )}

    </div>
  );
};

import React, { useRef, useState, useEffect } from 'react';

interface Scenario {
  id: string;
  title: string;
  product: 'Virtua' | 'TV' | 'Mesh' | 'Móvel';
  customerName: string;
  customerProfile: string;
  image: string;
  question: string;
  evalCriteria: string[];
}

interface RecorderProps {
  onComplete: (videoBlob: Blob, audioBlob: Blob) => void;
  onCancel: () => void;
  scenario: Scenario | null;
}

export const Recorder: React.FC<RecorderProps> = ({ onComplete, onCancel, scenario }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const previewVideoRef = useRef<HTMLVideoElement>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);

  const [isRecording, setIsRecording] = useState(false);
  const [recordedBlob, setRecordedBlob] = useState<Blob | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [activeLine, setActiveLine] = useState(0);
  const [showChecklist, setShowChecklist] = useState(false);
  const chunks = useRef<Blob[]>([]);

  const LINE_HEIGHT = 80;

  // Forçar o reload do vídeo de preview quando a URL mudar
  useEffect(() => {
    if (previewUrl && previewVideoRef.current) {
      previewVideoRef.current.load();
    }
  }, [previewUrl]);

  const startCamera = async () => {
    try {
      if (previewUrl) {
        URL.revokeObjectURL(previewUrl);
        setPreviewUrl(null);
      }

      const constraints = {
        video: { 
          facingMode: 'user', 
          width: { ideal: 720 }, 
          height: { ideal: 1280 },
          aspectRatio: { ideal: 9/16 }
        }, 
        audio: {
          echoCancellation: true,
          noiseSuppression: true,
          autoGainControl: true
        } 
      };

      const s = await navigator.mediaDevices.getUserMedia(constraints);
      setStream(s);
      if (videoRef.current) {
        videoRef.current.srcObject = s;
      }
    } catch (err) {
      console.error("Erro ao acessar mídia:", err);
      alert("Não foi possível acessar a câmera ou microfone. Verifique as permissões.");
      onCancel();
    }
  };

  useEffect(() => {
    startCamera();
    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
      if (previewUrl) URL.revokeObjectURL(previewUrl);
    };
  }, []);

  useEffect(() => {
    let interval: any;
    if (isRecording) {
      setActiveLine(0);
      interval = setInterval(() => {
        setActiveLine(prev => {
          if (prev < (fullScript?.length || 0) - 1) {
            return prev + 1;
          }
          return prev;
        });
      }, 4500);
    } else {
      setActiveLine(0);
      if (interval) clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [isRecording]);

  const handleStartRecording = () => {
    if (!stream) return;

    // Ordem de preferência de formatos para máxima compatibilidade
    const mimeTypes = [
      'video/mp4', // Prioridade para iOS/Safari
      'video/webm;codecs=vp8,opus',
      'video/webm;codecs=vp9,opus',
      'video/webm'
    ];

    const mimeType = mimeTypes.find(type => MediaRecorder.isTypeSupported(type)) || '';

    chunks.current = [];
    const recorder = new MediaRecorder(stream, { mimeType });

    recorder.ondataavailable = (e) => {
      if (e.data && e.data.size > 0) {
        chunks.current.push(e.data);
      }
    };

    recorder.onstop = () => {
      const blob = new Blob(chunks.current, { type: recorder.mimeType });
      const url = URL.createObjectURL(blob);
      setRecordedBlob(blob);
      setPreviewUrl(url);

      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
      setStream(null);
    };

    recorder.start(100); // Intervalos menores para evitar perda de dados
    mediaRecorderRef.current = recorder;
    setIsRecording(true);
  };

  const handleStopRecording = () => {
    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
      mediaRecorderRef.current.stop();
    }
    setIsRecording(false);
  };

  const handleRepeat = () => {
    setRecordedBlob(null);
    if (previewUrl) URL.revokeObjectURL(previewUrl);
    setPreviewUrl(null);
    setActiveLine(0);
    startCamera();
  };

  const handleSend = () => {
    if (recordedBlob) {
      onComplete(recordedBlob, recordedBlob);
    }
  };

  const getFullScript = () => {
    if (!scenario) return [];
    const name = scenario.customerName;
    switch(scenario.product) {
      case 'TV': return [`Olá ${name}, tudo bem? Sou o técnico da Claro.`, `O Claro TV+ é realmente incrível.`, `O controle tem comando de voz integrado.`, `Aperte o microfone e diga o que quer ver.`, `Diga "Netflix" e o app abre na hora!`, `Não precisa mais decorar números de canais.`, `Tudo o que a senhora gosta em um só lugar.`, `Ficou claro como essa facilidade vai ajudar?` ];
      case 'Mesh': return [`Oi Dr. Marcos, sou da Claro e vou resolver seu sinal.`, `Para telemedicina, estabilidade é fundamental.`, `O Wi-Fi Mesh cria uma malha inteligente na casa.`, `Diferente de um repetidor, não derruba a velocidade.`, `Mantém o sinal forte aqui e no andar de cima.`, `Sem precisar passar cabos ou fazer obra.`, `Podemos testar agora e verá que a oscilação acabou.`, `O que achou dessa solução definitiva?` ];
      case 'Virtua': return [`E aí Enzo! Sou técnico da Claro. Bora baixar esse ping?`, `O Wi-Fi 6 é tecnologia de ponta para gamers.`, `Ele usa frequências limpas, evitando o lag.`, `Nossa rede tem baixa latência (jitter).`, `Sua reação no FPS será muito mais rápida.`, `Larga banda permite jogar enquanto outros veem 4K.`, `É o setup ideal para performance competitiva.`, `Sentiu a diferença na estabilidade agora?` ];
      default: return [`Olá ${name}, sou o técnico da Claro.`, `Nossos produtos facilitam sua vida.`, `A tecnologia que instalamos é a melhor.`, `Foco total na sua estabilidade digital.`, `Qualquer dúvida, pode me perguntar agora.`, `A Claro agradece a sua confiança.`, `Tudo certo com a sua conexão?` ];
    }
  };

  const fullScript = getFullScript();

  return (
    <div className="flex flex-col space-y-4 animate-fadeIn max-w-4xl mx-auto pb-10 px-2 md:px-4">
      <div className="lg:hidden text-center bg-white p-3 rounded-2xl shadow-sm border border-gray-100 mb-2">
        <h2 className="text-xs font-black claro-text-red uppercase tracking-widest">{scenario?.title || 'Treinamento'}</h2>
        <p className="text-[10px] text-gray-400 font-bold uppercase mt-1">Cliente: {scenario?.customerName}</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-4 md:gap-6 items-stretch">
        <div className="lg:col-span-5 flex flex-col space-y-4">
          <div className="relative aspect-[3/4] bg-black rounded-[32px] overflow-hidden shadow-2xl border-4 border-white ring-1 ring-gray-100">
            {!previewUrl ? (
              <video 
                ref={videoRef} 
                autoPlay 
                muted 
                playsInline 
                className="w-full h-full object-cover mirror scale-x-[-1]"
              />
            ) : (
              <video 
                ref={previewVideoRef}
                key={previewUrl}
                src={previewUrl} 
                controls 
                playsInline
                webkitPlaysInline
                className="w-full h-full object-cover"
                autoPlay
              />
            )}

            {isRecording && (
              <div className="absolute top-4 left-4 flex items-center gap-2 bg-red-600 px-3 py-1.5 rounded-full text-white text-[9px] font-black animate-pulse shadow-lg z-20">
                <div className="w-1.5 h-1.5 bg-white rounded-full"></div>
                GRAVANDO...
              </div>
            )}

            {previewUrl && (
              <div className="absolute top-4 left-4 flex items-center gap-2 bg-blue-600 px-3 py-1.5 rounded-full text-white text-[9px] font-black shadow-lg z-20">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
                </svg>
                REVISÃO DE VÍDEO
              </div>
            )}
          </div>

          <div className="flex flex-col items-center gap-3">
            {!previewUrl ? (
              <button 
                onClick={isRecording ? handleStopRecording : handleStartRecording}
                className={`w-full flex items-center justify-center gap-3 py-5 rounded-full border-4 transition-all shadow-xl font-black text-sm tracking-widest ${
                  isRecording 
                    ? 'border-gray-200 bg-white text-gray-700 hover:bg-gray-50' 
                    : 'border-red-100 bg-[#ee0000] text-white hover:bg-red-700 active:scale-95'
                }`}
              >
                {isRecording ? (
                  <><div className="w-3 h-3 bg-[#ee0000] rounded-sm animate-pulse"></div> PARAR GRAVAÇÃO</>
                ) : (
                  <><div className="w-3 h-3 bg-white rounded-full"></div> GRAVAR AGORA</>
                )}
              </button>
            ) : (
              <div className="w-full space-y-3">
                <div className="flex gap-2">
                  <button 
                    onClick={handleRepeat}
                    className="flex-1 bg-gray-100 text-gray-600 font-black text-[10px] uppercase py-5 rounded-2xl hover:bg-gray-200 transition-colors flex flex-col items-center gap-1 shadow-sm"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" /></svg>
                    Repetir Gravação
                  </button>
                  <button 
                    onClick={handleSend}
                    className="flex-[1.5] claro-red text-white font-black text-[10px] uppercase py-5 rounded-2xl shadow-lg hover:bg-red-700 transition-colors flex flex-col items-center gap-1"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>
                    Enviar Vídeo
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>

        <div className="lg:col-span-7 flex flex-col min-h-[300px]">
          <div className="bg-gray-900 rounded-[32px] shadow-2xl overflow-hidden flex-1 flex flex-col relative border-4 border-gray-800">
            <div className="bg-gray-800 px-4 py-3 flex justify-between items-center">
              <span className="text-[9px] font-black text-red-500 uppercase tracking-widest">Teleprompter</span>
              <div className={`w-1.5 h-1.5 rounded-full ${isRecording ? 'bg-red-500 animate-pulse' : 'bg-gray-600'}`}></div>
            </div>

            <div className="relative flex-1 overflow-hidden flex items-center justify-center p-4">
              <div className="absolute inset-x-0 top-1/2 -translate-y-1/2 h-16 bg-red-600/10 border-y border-red-600/20 z-0"></div>
              <div 
                className="relative z-10 w-full transition-transform duration-700 ease-in-out text-center"
                style={{ transform: `translateY(${(fullScript.length / 2 - activeLine - 0.5) * LINE_HEIGHT}px)` }}
              >
                {fullScript.map((line, idx) => (
                  <div key={idx} className={`h-20 flex items-center justify-center px-4 transition-all duration-500 leading-tight ${idx === activeLine ? 'text-white text-xl md:text-2xl font-black opacity-100 scale-105' : 'text-gray-600 text-sm md:text-lg font-bold opacity-20 scale-90'}`}>
                    {line}
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="flex flex-col items-center gap-4 pt-2">
        {!isRecording && !previewUrl && (
          <button onClick={() => setShowChecklist(true)} className="text-gray-400 text-[10px] font-black uppercase py-2 px-6 border border-gray-200 rounded-full transition-all flex items-center gap-2">Ver Checklist</button>
        )}
        {!isRecording && (
          <button onClick={onCancel} className="text-gray-300 hover:text-[#ee0000] text-[9px] font-black uppercase tracking-widest transition-all">Sair</button>
        )}
      </div>

      {showChecklist && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/70 backdrop-blur-sm animate-fadeIn">
