import React, { useRef, useState, useEffect } from 'react';

interface Scenario {
  id: string;
  title: string;
  product: 'Virtua' | 'TV' | 'Mesh' | 'Móvel';
  customerName: string;
  customerProfile: string;
  image: string;
  question: string;
  evalCriteria: string[];
