import React, { useRef, useState, useEffect } from 'react';

interface Scenario {
  id: string;
  title: string;
  product: 'Virtua' | 'TV' | 'Mesh' | 'Móvel';
  customerName: string;
  customerProfile: string;
  image: string;
  question: string;
  evalCriteria: string[];
}

interface RecorderProps {
  onComplete: (videoBlob: Blob, audioBlob: Blob) => void;
  onCancel: () => void;
  scenario: Scenario | null;
  techName: string; // Adicionado para exibir o nome do técnico no roteiro
}

export const Recorder: React.FC<RecorderProps> = ({ onComplete, onCancel, scenario, techName }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const previewVideoRef = useRef<HTMLVideoElement>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);

  const [isRecording, setIsRecording] = useState(false);
  const [recordedBlob, setRecordedBlob] = useState<Blob | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [activeLine, setActiveLine] = useState(0);
  const [showChecklist, setShowChecklist] = useState(false);
  const chunks = useRef<Blob[]>([]);

  const LINE_HEIGHT = 80;

  // Extrai o primeiro nome para uma fala mais natural
  const firstName = techName.split(' ')[0];

  useEffect(() => {
    if (previewUrl && previewVideoRef.current) {
      previewVideoRef.current.load();
    }
  }, [previewUrl]);

  const startCamera = async () => {
    try {
      if (previewUrl) {
        URL.revokeObjectURL(previewUrl);
        setPreviewUrl(null);
      }

      const constraints = {
        video: { 
          facingMode: 'user', 
          width: { ideal: 720 }, 
          height: { ideal: 1280 },
          aspectRatio: { ideal: 9/16 }
        }, 
        audio: {
          echoCancellation: true,
          noiseSuppression: true,
          autoGainControl: true
        } 
      };

      const s = await navigator.mediaDevices.getUserMedia(constraints);
      setStream(s);
      if (videoRef.current) {
        videoRef.current.srcObject = s;
      }
    } catch (err) {
      console.error("Erro ao acessar mídia:", err);
      alert("Não foi possível acessar a câmera ou microfone. Verifique as permissões.");
      onCancel();
    }
  };

  useEffect(() => {
    startCamera();
    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
      if (previewUrl) URL.revokeObjectURL(previewUrl);
    };
  }, []);

  useEffect(() => {
    let interval: any;
    if (isRecording) {
      setActiveLine(0);
      interval = setInterval(() => {
        setActiveLine(prev => {
          if (prev < (fullScript?.length || 0) - 1) {
            return prev + 1;
          }
          return prev;
        });
      }, 4500);
    } else {
      setActiveLine(0);
      if (interval) clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [isRecording]);

  const handleStartRecording = () => {
    if (!stream) return;

    const mimeTypes = [
      'video/mp4',
      'video/webm;codecs=vp8,opus',
      'video/webm;codecs=vp9,opus',
      'video/webm'
    ];

    const mimeType = mimeTypes.find(type => MediaRecorder.isTypeSupported(type)) || '';

    chunks.current = [];
    const recorder = new MediaRecorder(stream, { mimeType });

    recorder.ondataavailable = (e) => {
      if (e.data && e.data.size > 0) {
        chunks.current.push(e.data);
      }
    };

    recorder.onstop = () => {
      const blob = new Blob(chunks.current, { type: recorder.mimeType });
      const url = URL.createObjectURL(blob);
      setRecordedBlob(blob);
      setPreviewUrl(url);

      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
      setStream(null);
    };

    recorder.start(100);
    mediaRecorderRef.current = recorder;
    setIsRecording(true);
  };

  const handleStopRecording = () => {
    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
      mediaRecorderRef.current.stop();
    }
    setIsRecording(false);
  };

  const handleRepeat = () => {
    setRecordedBlob(null);
    if (previewUrl) URL.revokeObjectURL(previewUrl);
    setPreviewUrl(null);
    setActiveLine(0);
    startCamera();
  };

  const handleSend = () => {
