        <h2 className="text-xs font-black claro-text-red uppercase tracking-widest">{scenario?.title || 'Treinamento'}</h2>
        <p className="text-[10px] text-gray-400 font-bold uppercase mt-1">Cliente: {scenario?.customerName}</p>
