  scenarioContext?: string
): Promise<EvaluationResult> => {
  // Inicialização dentro da função para garantir que pegue a chave de API mais atualizada
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Limpa o mimeType para garantir que seja um tipo IANA padrão (ex: video/webm;codecs=vp8 -> video/webm)
  const cleanMimeType = videoMimeType.split(';')[0];

  const systemInstruction = `Você é um avaliador de excelência de atendimento da Claro especializado em feedback para técnicos de campo.
    Sua missão é avaliar a naturalidade, convicção e clareza de uma explicação técnica.
    Não avalie apenas se o técnico leu o roteiro corretamente, mas sim a postura, tom de voz e empatia.
    Retorne o resultado estritamente em JSON conforme o schema definido.`;

  const contextPrompt = scenarioContext ? 
    `CONTEXTO DO CENÁRIO ESPECÍFICO: ${scenarioContext}. Avalie se o técnico respondeu diretamente à dúvida do cliente e se usou argumentos corretos para este produto.` : 
    "Avalie uma explicação técnica geral sobre os produtos Claro.";

  const userPrompt = `
    Analise o vídeo anexo sob estes critérios:
    1. Expressão e Postura: Contato visual, sorriso, confiança e naturalidade.
    2. Nitidez e Clareza: Explicação direta e sem hesitação excessiva.
    3. Empatia: Tom de voz adequado ao perfil do cliente.
    4. Linguagem Não-Verbal: Gestos que reforçam a autoridade.

    ${contextPrompt}
  `;

  try {
    const parts: any[] = [
      { text: userPrompt }
    ];

    if (videoBase64) {
      // Remove o prefixo data:video/...;base64, se existir
      const base64Data = videoBase64.includes(',') ? videoBase64.split(',')[1] : videoBase64;
      parts.push({
        inlineData: {
          data: base64Data,
          mimeType: cleanMimeType
        }
      });
    }

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: { parts },
      config: {
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            score: { type: Type.NUMBER, description: "Nota final de 0 a 10" },
            strengths: { type: Type.STRING, description: "Pontos fortes da expressão e fala" },
            weaknesses: { type: Type.STRING, description: "Onde a nitidez falhou ou a postura foi inadequada" },
            suggestions: { type: Type.STRING, description: "Dica prática para a próxima gravação" },
            transcript: { type: Type.STRING, description: "Transcrição fiel do que foi dito" }
          },
          required: ["score", "strengths", "weaknesses", "suggestions", "transcript"]
        }
      }
    });

    const jsonStr = response.text?.trim() || '{}';
    const result = JSON.parse(jsonStr);

    return {
      score: result.score || 0,
      strengths: result.strengths || "Não foi possível identificar pontos fortes.",
      weaknesses: result.weaknesses || "Não foi possível identificar pontos fracos.",
      suggestions: result.suggestions || "Continue praticando os cenários!",
      transcript: result.transcript || "[Transcrição indisponível]"
    };
  } catch (error: any) {
    console.error("Erro detalhado na avaliação Gemini:", error);
    // Se for um erro de argumento inválido, pode ser o tamanho do vídeo ou mimeType
    if (error.message?.includes("INVALID_ARGUMENT")) {
      console.warn("Dica: O erro INVALID_ARGUMENT pode ser causado por um mimeType não suportado ou arquivo corrompido.");
    }
    throw error;
  }
};

