interface RecorderProps {
  onComplete: (videoBlob: Blob) => void;
  onCancel: () => void;
  scenario: Scenario | null;
  techName: string;
  mode: EvalMode;
}

export const Recorder: React.FC<RecorderProps> = ({ onComplete, onCancel, scenario, techName, mode }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const previewVideoRef = useRef<HTMLVideoElement>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);

  const [isRecording, setIsRecording] = useState(false);
  const [recordedBlob, setRecordedBlob] = useState<Blob | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [activeLine, setActiveLine] = useState(0);
  const chunks = useRef<Blob[]>([]);

  const LINE_HEIGHT = window.innerWidth < 768 ? 60 : 80;
  const firstName = techName.split(' ')[0];

  useEffect(() => {
    if (previewUrl && previewVideoRef.current) {
      previewVideoRef.current.load();
    }
  }, [previewUrl]);

  const startCamera = async () => {
    try {
      if (previewUrl) {
        URL.revokeObjectURL(previewUrl);
        setPreviewUrl(null);
      }

      const constraints = {
        video: { 
          facingMode: 'user', 
          width: { ideal: 1280 }, 
          height: { ideal: 720 },
          aspectRatio: { ideal: 1.7777777778 }
        }, 
        audio: {
          echoCancellation: true,
          noiseSuppression: true
        } 
      };

      const s = await navigator.mediaDevices.getUserMedia(constraints);
      setStream(s);
      if (videoRef.current) {
        videoRef.current.srcObject = s;
      }
    } catch (err) {
      console.error("Erro ao acessar mídia:", err);
      alert("Não foi possível acessar a câmera ou microfone.");
      onCancel();
    }
  };

  useEffect(() => {
    startCamera();
    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
      if (previewUrl) URL.revokeObjectURL(previewUrl);
    };
  }, []);

  useEffect(() => {
    let interval: any;
    if (isRecording && mode === 'script') {
      setActiveLine(0);
      interval = setInterval(() => {
        setActiveLine(prev => {
          if (prev < (fullScript?.length || 0) - 1) {
            return prev + 1;
          }
          return prev;
        });
      }, 4500);
    } else {
      setActiveLine(0);
      if (interval) clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [isRecording, mode]);

  const handleStartRecording = () => {
    if (!stream) return;
    const mimeTypes = ['video/mp4', 'video/webm;codecs=vp8,opus', 'video/webm'];
    const mimeType = mimeTypes.find(type => MediaRecorder.isTypeSupported(type)) || '';

    chunks.current = [];
    const recorder = new MediaRecorder(stream, { mimeType });

    recorder.ondataavailable = (e) => {
      if (e.data && e.data.size > 0) chunks.current.push(e.data);
    };

    recorder.onstop = () => {
      const blob = new Blob(chunks.current, { type: recorder.mimeType });
      const url = URL.createObjectURL(blob);
      setRecordedBlob(blob);
      setPreviewUrl(url);
      if (stream) stream.getTracks().forEach(track => track.stop());
      setStream(null);
    };

    recorder.start(100);
    mediaRecorderRef.current = recorder;
    setIsRecording(true);
  };

  const handleStopRecording = () => {
    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
      mediaRecorderRef.current.stop();
    }
    setIsRecording(false);
  };

  const handleRepeat = () => {
    setRecordedBlob(null);
    if (previewUrl) URL.revokeObjectURL(previewUrl);
    setPreviewUrl(null);
    setActiveLine(0);
    startCamera();
  };

  const handleSend = () => {
    if (recordedBlob) onComplete(recordedBlob);
  };

  const getFullScript = () => {
    if (!scenario) return [];
    const name = scenario.customerName;
    const intro = `Oi ${name}, tudo bem? Sou o ${firstName}, técnico da Claro.`;
    switch(scenario.product) {
      case 'TV': return [intro, `O Claro TV+ é realmente incrível.`, `O controle tem comando de voz integrado.`, `Aperte o microfone e diga o que quer ver.`, `Diga "Netflix" e o app abre na hora!`, `Não precisa mais decorar números de canais.`, `Tudo o que a senhora gosta em um só lugar.`, `Ficou claro como essa facilidade vai ajudar?` ];
      case 'Mesh': return [`Oi Dr. Marcos, sou o ${firstName} da Claro e vou resolver seu sinal.`, `Para telemedicina, estabilidade é fundamental.`, `O Wi-Fi Mesh cria uma malha inteligente na casa.`, `Diferente de um repetidor, não derruba a velocidade.`, `Mantém o sinal forte aqui e no andar de cima.`, `Sem precisar passar cabos ou fazer obra.`, `Podemos testar agora e verá que a oscilação acabou.`, `O que achou dessa solução definitiva?` ];
      case 'Virtua': return [`E aí Enzo! Sou o ${firstName}, técnico da Claro. Bora baixar esse ping?`, `O Wi-Fi 6 é tecnologia de ponta para gamers.`, `Ele usa frequências limpas, evitando o lag.`, `Nossa rede tem baixa latência (jitter).`, `Sua reação no FPS será muito mais rápida.`, `Larga banda permite jogar enquanto outros veem 4K.`, `É o setup ideal para performance competitiva.`, `Sentiu a diferença na estabilidade agora?` ];
      default: return [`Olá ${name}, sou o ${firstName}, técnico da Claro.`, `Nossos produtos facilitam sua vida.`, `A tecnologia que instalamos é a melhor.`, `Foco total na sua estabilidade digital.`, `Qualquer dúvida, pode me perguntar agora.`, `A Claro agradece a sua confiança.`, `Tudo certo com a sua conexão?` ];
    }
  };

  const fullScript = getFullScript();

  return (
    <div className="flex flex-col space-y-4 animate-fadeIn max-w-6xl mx-auto pb-10 px-2 md:px-4">
      <div className="flex items-center justify-between bg-white p-3 rounded-2xl shadow-sm border border-gray-100">
        <div className="flex flex-col">
          <h2 className="text-xs font-black claro-text-red uppercase tracking-widest">{scenario?.title}</h2>
          <p className="text-[10px] text-gray-400 font-bold uppercase">Cliente: {scenario?.customerName}</p>
        </div>
        <div className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest ${mode === 'knowledge' ? 'bg-orange-100 text-orange-600' : 'bg-blue-100 text-blue-600'}`}>
          {mode === 'knowledge' ? 'Etapa 1: Sem Roteiro' : 'Etapa 2: Com Roteiro'}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-4 md:gap-6 items-stretch">
        <div className="lg:col-span-5 flex flex-col space-y-4">
          <div className="relative aspect-[3/4] md:aspect-square lg:aspect-[3/4] bg-black rounded-[32px] overflow-hidden shadow-2xl border-4 border-white">
            {!previewUrl ? (
              <video ref={videoRef} autoPlay muted playsInline className="w-full h-full object-cover mirror" />
            ) : (
              <video key={previewUrl} src={previewUrl} controls playsInline className="w-full h-full object-cover" autoPlay />
            )}

            {isRecording && (
              <div className="absolute top-4 left-4 flex items-center gap-2 bg-red-600 px-3 py-1.5 rounded-full text-white text-[9px] font-black animate-pulse z-20">
                <div className="w-1.5 h-1.5 bg-white rounded-full"></div>
                GRAVANDO...
              </div>
            )}
          </div>

          <div className="flex flex-col items-center gap-3">
            {!previewUrl ? (
              <button 
                onClick={isRecording ? handleStopRecording : handleStartRecording}
                className={`w-full flex items-center justify-center gap-3 py-5 rounded-full border-4 transition-all shadow-xl font-black text-sm tracking-widest ${isRecording ? 'border-gray-200 bg-white text-gray-700' : 'border-red-100 bg-[#ee0000] text-white'}`}
              >
                {isRecording ? 'PARAR' : 'GRAVAR AGORA'}
              </button>
            ) : (
              <div className="w-full flex gap-2">
                <button onClick={handleRepeat} className="flex-1 bg-gray-100 text-gray-600 font-black text-[10px] uppercase py-5 rounded-2xl">REPETIR</button>
                <button onClick={handleSend} className="flex-[1.5] claro-red text-white font-black text-[10px] uppercase py-5 rounded-2xl shadow-lg">ENVIAR PARA IA</button>
              </div>
            )}
          </div>
        </div>

        <div className="lg:col-span-7 flex flex-col min-h-[350px]">
          {mode === 'script' ? (
            <div className="bg-gray-900 rounded-[32px] shadow-2xl overflow-hidden flex-1 flex flex-col relative border-4 border-gray-800">
              <div className="bg-gray-800 px-4 py-3 flex justify-between items-center shrink-0">
                <span className="text-[10px] font-black text-red-500 uppercase tracking-widest">Teleprompter Ativado</span>
              </div>
              <div className="relative flex-1 overflow-hidden flex items-center justify-center p-4">
                <div className="absolute inset-x-0 top-1/2 -translate-y-1/2 h-20 md:h-24 bg-white/5 border-y border-white/10 z-0"></div>
                <div 
                  className="relative z-10 w-full transition-transform duration-700 ease-in-out text-center"
                  style={{ transform: `translateY(${(fullScript.length / 2 - activeLine - 0.5) * LINE_HEIGHT}px)` }}
                >
                  {fullScript.map((line, idx) => (
                    <div key={idx} className={`flex items-center justify-center px-4 transition-all duration-500 ${idx === activeLine ? 'text-white text-lg md:text-2xl font-black opacity-100 scale-105 h-[60px] md:h-[80px]' : 'text-gray-600 text-xs md:text-base font-bold opacity-20 scale-90 h-[60px] md:h-[80px]'}`}>
                      {line}
                    </div>
                  ))}
                </div>
              </div>
            </div>
          ) : (
            <div className="bg-white rounded-[32px] shadow-sm border-4 border-orange-50 flex-1 flex flex-col items-center justify-center p-8 text-center space-y-6">
              <div className="w-20 h-20 bg-orange-100 rounded-full flex items-center justify-center text-orange-500">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.663 17h4.674a1 1 0 00.922-.618l2.7-6.187a1 1 0 00-.922-1.395H13.43l.73-4.38a1 1 0 00-1.747-.852l-6.407 8.01a1 1 0 00.787 1.629h4.105l-1.932 4.182a1 1 0 00.922 1.41z" />
                </svg>
              </div>
              <h3 className="text-2xl font-black text-gray-800 uppercase tracking-tighter">Desafio Conhecimento</h3>
              <p className="text-gray-500 font-medium max-w-sm">
                Nesta etapa o roteiro está oculto. Demonstre como você explicaria este produto usando suas próprias palavras e experiência!
              </p>
              <div className="bg-orange-50 p-4 rounded-2xl w-full border border-orange-100">
                <p className="text-[10px] font-black text-orange-600 uppercase tracking-widest mb-1">Dica de Ouro</p>
                <p className="text-xs text-orange-800 font-bold">Foque nos benefícios que você sabe que encantam o cliente.</p>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { EvaluationResult as EvalType } from '../services/geminiService';
