interface ResultProps {
  result: EvalType;
  mode: EvalMode;
  onNextStep?: () => void;
  onFinish: () => void;
  previousResult?: EvalType | null;
}

export const EvaluationResult: React.FC<ResultProps> = ({ result, mode, onNextStep, onFinish, previousResult }) => {
  const getScoreColor = (score: number) => {
    if (score >= 8) return 'text-green-500';
    if (score >= 6) return 'text-yellow-500';
    return 'text-red-500';
  };

  const isEvolution = previousResult && mode === 'script';

  return (
    <div className="space-y-6 animate-fadeIn pb-10">
      {isEvolution && (
        <div className="bg-blue-600 text-white p-6 rounded-[32px] shadow-xl flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="bg-white/20 p-3 rounded-2xl">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" /></svg>
            </div>
            <div>
              <h4 className="font-black uppercase text-xs tracking-widest">Sua Evolução</h4>
              <p className="text-lg font-bold">Você melhorou {Math.max(0, result.score - previousResult.score).toFixed(1)} pontos!</p>
            </div>
          </div>
          <div className="text-right">
            <p className="text-[10px] font-black opacity-70 uppercase">Antes: {previousResult.score.toFixed(1)}</p>
            <p className="text-xl font-black">Agora: {result.score.toFixed(1)}</p>
          </div>
        </div>
      )}

      <div className="bg-white p-8 rounded-3xl shadow-sm border border-gray-100 text-center relative overflow-hidden">
        <div className={`absolute top-0 right-0 p-4 text-[10px] font-black uppercase tracking-widest ${mode === 'knowledge' ? 'text-orange-400' : 'text-blue-400'}`}>
          {mode === 'knowledge' ? 'Modo: Conhecimento' : 'Modo: Com Roteiro'}
        </div>
        <p className="text-sm text-gray-400 uppercase font-bold tracking-widest mb-1">Nota desta Etapa</p>
        <div className={`text-7xl font-black mb-4 ${getScoreColor(result.score)}`}>
          {result.score.toFixed(1)}
        </div>
        <div className="flex justify-center mb-6">
          {[...Array(10)].map((_, i) => (
            <div key={i} className={`w-4 h-2 mx-0.5 rounded-full ${i < result.score ? 'claro-red' : 'bg-gray-100'}`}></div>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className="bg-white p-6 rounded-2xl border-l-4 border-green-500 shadow-sm">
          <h4 className="font-bold text-green-700 flex items-center gap-2 mb-2 text-xs uppercase">Pontos Fortes</h4>
          <p className="text-gray-600 text-sm leading-relaxed">{result.strengths}</p>
        </div>
        <div className="bg-white p-6 rounded-2xl border-l-4 border-red-500 shadow-sm">
          <h4 className="font-bold text-red-700 flex items-center gap-2 mb-2 text-xs uppercase">Oportunidades</h4>
          <p className="text-gray-600 text-sm leading-relaxed">{result.weaknesses}</p>
        </div>
      </div>

      <div className="bg-white p-6 rounded-2xl border-l-4 border-blue-500 shadow-sm">
        <h4 className="font-bold text-blue-700 flex items-center gap-2 mb-2 text-xs uppercase">Sugestão Técnica</h4>
        <p className="text-gray-600 text-sm leading-relaxed">{result.suggestions}</p>
      </div>

      <div className="flex flex-col gap-3 pt-4">
        {mode === 'knowledge' && onNextStep && (
          <button 
            onClick={onNextStep}
            className="w-full claro-red text-white font-black py-5 rounded-full shadow-xl text-sm uppercase tracking-widest hover:scale-[1.02] transition-all flex items-center justify-center gap-3"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>
            MELHORAR COM ROTEIRO
          </button>
        )}
        <button 
          onClick={onFinish}
          className="w-full bg-gray-100 text-gray-600 font-black py-4 rounded-full text-xs uppercase tracking-widest"
        >
          {mode === 'knowledge' ? 'CONCLUIR TREINAMENTO' : 'VOLTAR AO INÍCIO'}
        </button>
      </div>
    </div>
  );
};

