import { GoogleGenAI, Type } from "@google/genai";

export interface EvaluationResult {
  score: number;
  strengths: string;
  weaknesses: string;
  suggestions: string;
  transcript: string;
}

export const evaluateExplanation = async (
  videoBase64?: string, 
  videoMimeType: string = 'video/mp4',
  scenarioContext?: string
): Promise<EvaluationResult> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // LIMPEZA DE MIMETYPE
  // Remove codecs para deixar apenas o container (ex: "video/webm")
  let cleanMimeType = videoMimeType.split(';')[0].trim().toLowerCase();

  // Normalização de tipos para o Gemini
  if (cleanMimeType === 'video/quicktime') cleanMimeType = 'video/mp4';
  if (cleanMimeType === 'video/x-matroska') cleanMimeType = 'video/webm';
  if (cleanMimeType === 'application/octet-stream') cleanMimeType = 'video/mp4'; // Fallback comum

  // Se não estiver na lista de suportados, força mp4 que é o mais compatível
  const supportedTypes = ['video/mp4', 'video/mpeg', 'video/mov', 'video/avi', 'video/flv', 'video/mpg', 'video/webm', 'video/wmv', 'video/3gp'];
  if (!supportedTypes.includes(cleanMimeType)) {
    console.warn(`MimeType original ${videoMimeType} ajustado para video/mp4.`);
    cleanMimeType = 'video/mp4';
  }

  const systemInstruction = `Você é um avaliador de excelência de atendimento da Claro.
    Analise o vídeo do técnico explicando o produto.
    Critérios: Naturalidade, Clareza, Empatia e Correção Técnica.
    Retorne JSON válido.`;

  const contextPrompt = scenarioContext ? 
    `CENÁRIO: ${scenarioContext}.` : 
    "Avaliação técnica geral Claro.";

  const userPrompt = `
    Analise o vídeo:
    1. Postura e Sorriso.
    2. Clareza da explicação.
    3. Argumentação correta.

    ${contextPrompt}
  `;

  try {
    const parts: any[] = [{ text: userPrompt }];

    if (videoBase64) {
      const base64Data = videoBase64.includes(',') ? videoBase64.split(',')[1] : videoBase64;

      // Verificação de tamanho (aprox 20MB limite seguro para inline)
      const sizeInBytes = (base64Data.length * 3) / 4;
      if (sizeInBytes > 19 * 1024 * 1024) {
        throw new Error("O vídeo ficou muito longo para análise (max 20MB). Tente gravar por menos tempo.");
      }

      parts.push({
        inlineData: {
          data: base64Data,
          mimeType: cleanMimeType
        }
      });
    }

    // Usando gemini-2.5-flash-latest pois é mais estável para video input multimodal
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-latest",
      contents: { parts },
      config: {
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            score: { type: Type.NUMBER, description: "Nota de 0 a 10" },
            strengths: { type: Type.STRING, description: "Pontos positivos" },
            weaknesses: { type: Type.STRING, description: "Pontos a melhorar" },
            suggestions: { type: Type.STRING, description: "Sugestão prática" },
            transcript: { type: Type.STRING, description: "O que foi falado" }
          },
          required: ["score", "strengths", "weaknesses", "suggestions", "transcript"]
        }
      }
    });

    const jsonStr = response.text?.trim() || '{}';
    return JSON.parse(jsonStr);

  } catch (error: any) {
    console.error("Gemini Error:", error);
    // Fallback amigável se a IA falhar
    if (error.message?.includes("INVALID_ARGUMENT")) {
       return {
         score: 0,
         strengths: "Erro no formato do vídeo.",
         weaknesses: "O vídeo pode estar corrompido ou muito grande.",
         suggestions: "Tente gravar um vídeo mais curto (max 45s).",
         transcript: "Indisponível"
       };
    }
    throw error;
  }
};

