      }

      parts.push({
        inlineData: {
          data: base64Data,
          mimeType: cleanMimeType
        }
      });
    }

    // Usando gemini-2.0-flash-exp para maior compatibilidade com vídeo multimodal
    const response = await ai.models.generateContent({
      model: "gemini-2.0-flash-exp",
      contents: { parts },
      config: {
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            score: { type: Type.NUMBER, description: "Nota de 0 a 10" },
