    } else if (technicalDetails.includes("API key")) {
      errorMessage = "Erro de autenticação com a IA.";
    }

    // Retorna um objeto de erro "soft" para não quebrar a UI, mas com nota 0
    return {
      score: 0,
      strengths: "Não foi possível analisar o vídeo.",
      weaknesses: errorMessage,
      suggestions: "Tente gravar um vídeo mais curto (max 30s) e verifique sua conexão.",
      transcript: `Erro técnico: ${technicalDetails.slice(0, 100)}...`
    };
