import React, { useState, useEffect } from 'react';
import { User, EvalMode, Evaluation as EvalModel } from './types';
import { DB } from './db';
import { Layout } from './components/Layout';
import { Login } from './pages/Login';
import { Register } from './pages/Register';
import { Dashboard } from './pages/Dashboard';
import { Consultivo } from './pages/Consultivo';
import { Recorder } from './pages/Recorder';
import { EvaluationResult } from './pages/EvaluationResult';
import { AdminDashboard } from './pages/AdminDashboard';
import { evaluateExplanation, EvaluationResult as AIResult } from './services/geminiService';
import { MediaStorage } from './services/storageService';

const LOADING_MESSAGES = [
  "A Inteligência Artificial está analisando seu vídeo...",
  "Observando expressões faciais e postura...",
  "Avaliando a nitidez da sua explicação...",
  "Medindo o nível de empatia e conexão...",
  "Comparando com os padrões de excelência Claro...",
  "Gerando seu relatório detalhado de performance..."
];

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<string>('login');
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(false);
  const [loadingMsgIdx, setLoadingMsgIdx] = useState(0);

  const [lastEval, setLastEval] = useState<AIResult | null>(null);
  const [previousEval, setPreviousEval] = useState<AIResult | null>(null);
  const [activeScenario, setActiveScenario] = useState<any>(null);
  const [recordingMode, setRecordingMode] = useState<EvalMode>('knowledge');
  const [correlationId, setCorrelationId] = useState<string>('');

  useEffect(() => {
    MediaStorage.init().catch(err => console.error("Falha ao iniciar IndexedDB:", err));
    const savedUser = localStorage.getItem('explica_session');
    if (savedUser) {
      const u = JSON.parse(savedUser);
      const freshUser = DB.users.findById(u.id);
      if (freshUser) {
        setUser(freshUser);
        setCurrentPage('dashboard');
      }
    }
  }, []);

  useEffect(() => {
    let interval: any;
    if (loading) {
      interval = setInterval(() => {
        setLoadingMsgIdx((prev) => (prev + 1) % LOADING_MESSAGES.length);
      }, 3500);
    }
    return () => clearInterval(interval);
  }, [loading]);

  const handleLogin = (cpf: string, pass: string) => {
    const foundUser = DB.users.findByCpf(cpf);
    if (foundUser && (foundUser.password === pass || foundUser.role === 'admin' || foundUser.role === 'superadmin')) {
      setUser(foundUser);
      localStorage.setItem('explica_session', JSON.stringify(foundUser));
      DB.accesses.add({ id: Math.random().toString(36).substr(2, 9), userId: foundUser.id, userName: foundUser.name, timestamp: new Date().toISOString(), uf: foundUser.uf, city: foundUser.city });
      setCurrentPage('dashboard');
    } else alert("Credenciais inválidas");
  };

  const handleStartScenario = (scenario: any) => {
    setActiveScenario(scenario);
    setRecordingMode('knowledge');
    setCorrelationId(Math.random().toString(36).substr(2, 9));
    setPreviousEval(null);
    setCurrentPage('recorder');
  };

  const handleRecorderComplete = async (video: Blob) => {
    setLoading(true);
    try {
      const evalId = Math.random().toString(36).substr(2, 9);
      await MediaStorage.save(evalId, video);

      const reader = new FileReader();
      const base64Promise = new Promise<string>((resolve) => {
        reader.onloadend = () => resolve(reader.result as string);
        reader.readAsDataURL(video);
      });
      const base64Video = await base64Promise;

      const scenarioContext = activeScenario ? `Cenário: Atendimento para ${activeScenario.customerName}. Produto: ${activeScenario.product}. Dúvida: ${activeScenario.question}. Modo: ${recordingMode}.` : undefined;

      const result = await evaluateExplanation(base64Video, video.type || 'video/mp4', scenarioContext);

      // Se retornou score 0 com mensagem de erro, mostramos alerta mas não salvamos no histórico (opcional)
      if (result.score === 0 && result.strengths.includes("Não foi possível")) {
        alert(`Atenção: ${result.weaknesses}\n\nDica: ${result.suggestions}`);
      }

      if (user) {
        DB.evaluations.add({
          id: evalId, userId: user.id, userName: user.name, timestamp: new Date().toISOString(),
          score: result.score, strengths: result.strengths, weaknesses: result.weaknesses,
          suggestions: result.suggestions, transcript: result.transcript,
          uf: user.uf, city: user.city, evalMode: recordingMode, correlationId: correlationId
        });
      }

      setLastEval(result);
      setCurrentPage('result');
    } catch (err) {
      console.error(err);
      alert("Ocorreu um erro crítico ao processar o vídeo. Tente novamente.");
    } finally {
      setLoading(false);
    }
  };

  const startScriptedMode = () => {
    setPreviousEval(lastEval);
    setRecordingMode('script');
    setCurrentPage('recorder');
  };

  const renderContent = () => {
    if (loading) {
      return (
        <div className="flex flex-col items-center justify-center min-h-[60vh] space-y-8 animate-fadeIn text-center">
          <div className="flex space-x-2"><div className="w-4 h-4 claro-red rounded-full dot-1"></div><div className="w-4 h-4 claro-red rounded-full dot-2"></div><div className="w-4 h-4 claro-red rounded-full dot-3"></div></div>
          <div className="space-y-4 max-w-sm px-6">
            <h3 className="text-xs font-black claro-text-red uppercase tracking-[0.4em] animate-pulse">Explica+ IA Vision</h3>
            <div key={loadingMsgIdx} className="animate-slideUpFade">
              <p className="text-gray-800 font-bold text-lg leading-tight min-h-[3.5rem]">{LOADING_MESSAGES[loadingMsgIdx]}</p>
            </div>
          </div>
          <div className="w-48 h-1 bg-gray-100 rounded-full overflow-hidden"><div className="h-full claro-red w-full animate-[loading_2.5s_ease-in-out_infinite]"></div></div>
          <style>{`@keyframes loading { 0% { transform: translateX(-100%); } 50% { transform: translateX(0); } 100% { transform: translateX(100%); } }`}</style>
        </div>
      );
    }

    switch (currentPage) {
      case 'login': return <Login onLogin={handleLogin} onGoToRegister={() => setCurrentPage('register')} />;
      case 'register': return <Register onRegister={() => setCurrentPage('login')} onBack={() => setCurrentPage('login')} />;
      case 'dashboard': return user ? <Dashboard user={user} onNavigate={setCurrentPage} /> : null;
      case 'consultivo': return <Consultivo onStart={handleStartScenario} onBack={() => setCurrentPage('dashboard')} />;
      case 'recorder': return <Recorder techName={user?.name || 'Técnico'} scenario={activeScenario} mode={recordingMode} onComplete={handleRecorderComplete} onCancel={() => setCurrentPage('consultivo')} />;
      case 'result': return lastEval ? <EvaluationResult result={lastEval} mode={recordingMode} onNextStep={startScriptedMode} previousResult={previousEval} onFinish={() => setCurrentPage('dashboard')} /> : null;
      case 'admin': return user ? <AdminDashboard currentUser={user} /> : null;
      default: return <Login onLogin={handleLogin} onGoToRegister={() => setCurrentPage('register')} />;
    }
  };

  return <Layout user={user} onLogout={() => { setUser(null); localStorage.removeItem('explica_session'); setCurrentPage('login'); }} onHome={() => setCurrentPage('dashboard')} onAdminClick={() => setCurrentPage('admin')} title={currentPage === 'admin' ? 'Painel Administrativo' : undefined}>{renderContent()}</Layout>;
};

export default App;

import React, { useRef, useState, useEffect } from 'react';
import { EvalMode } from '../types';

interface Scenario {
  id: string;
  title: string;
  product: 'Virtua' | 'TV' | 'Mesh' | 'Móvel';
  customerName: string;
  customerProfile: string;
  image: string;
  question: string;
  evalCriteria: string[];
}

interface RecorderProps {
  onComplete: (videoBlob: Blob) => void;
  onCancel: () => void;
  scenario: Scenario | null;
  techName: string;
  mode: EvalMode;
}

const MAX_RECORDING_TIME = 60; // 60 segundos máximo

export const Recorder: React.FC<RecorderProps> = ({ onComplete, onCancel, scenario, techName, mode }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const [isRecording, setIsRecording] = useState(false);
  const [recordedBlob, setRecordedBlob] = useState<Blob | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [activeLine, setActiveLine] = useState(0);
  const [timeLeft, setTimeLeft] = useState(MAX_RECORDING_TIME);
  const chunks = useRef<Blob[]>([]);

  const LINE_HEIGHT = window.innerWidth < 768 ? 60 : 80;
  const firstName = techName.split(' ')[0];

  const stopTracks = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => {
        try {
          track.stop();
          track.enabled = false;
        } catch (e) {
          console.warn("Erro ao parar track:", e);
        }
      });
      streamRef.current = null;
    }
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
  };

  const startCamera = async () => {
    try {
      stopTracks();

      // Configuração otimizada para Gemini: 480p é suficiente para análise facial e gera arquivos leves
      const constraints: MediaStreamConstraints = {
        video: { 
          facingMode: 'user', 
          width: { ideal: 480 }, 
          height: { ideal: 360 },
          frameRate: { ideal: 24, max: 30 }
        }, 
        audio: { 
          echoCancellation: true, 
          noiseSuppression: true,
          channelCount: 1 
        } 
      };

      const s = await navigator.mediaDevices.getUserMedia(constraints);
      streamRef.current = s;
      if (videoRef.current) {
        videoRef.current.srcObject = s;
      }
    } catch (err: any) {
      console.error("Erro ao acessar mídia:", err);
      if (err.name === 'NotReadableError' || err.message?.includes('in use') || err.name === 'NotAllowedError') {
        alert("A câmera parece estar em uso ou bloqueada. Verifique as permissões do navegador.");
      } else {
        alert("Não foi possível acessar a câmera. Tente recarregar a página.");
      }
      onCancel();
    }
  };

  useEffect(() => {
    startCamera();
    return () => {
      stopTracks();
      if (previewUrl) URL.revokeObjectURL(previewUrl);
    };
  }, []);

  useEffect(() => {
    let interval: any;
    if (isRecording) {
      interval = setInterval(() => {
        setTimeLeft((prev) => {
          if (prev <= 1) {
            handleStopRecording();
            return 0;
          }
          return prev - 1;
        });

        if (mode === 'script') {
          setActiveLine(prev => {
            if (prev < (fullScript?.length || 0) - 1) return prev + 1;
            return prev;
          });
        }
      }, mode === 'script' ? 4500 : 1000);
    } else {
      setTimeLeft(MAX_RECORDING_TIME);
      setActiveLine(0);
    }
    return () => clearInterval(interval);
  }, [isRecording, mode]);

  const handleStartRecording = () => {
    if (!streamRef.current) {
      startCamera();
      return;
    }

    // Tenta priorizar MP4 (Safari/iOS) ou WebM (Chrome/Android)
    const mimeTypes = [
      'video/mp4',
      'video/webm;codecs=vp8,opus',
      'video/webm'
    ];

    const mimeType = mimeTypes.find(type => MediaRecorder.isTypeSupported(type)) || '';

    chunks.current = [];
    try {
      // 250kbps é suficiente para vídeo falado em 480p e mantém o arquivo pequeno (<10MB por min)
      const options: MediaRecorderOptions = { 
        mimeType,
        videoBitsPerSecond: 250000, 
        audioBitsPerSecond: 64000
      };

      const recorder = new MediaRecorder(streamRef.current, mimeType ? options : undefined);

      recorder.ondataavailable = (e) => { 
        if (e.data && e.data.size > 0) chunks.current.push(e.data); 
      };

      recorder.onstop = () => {
        // Garante que o Blob final tenha o tipo correto
        const finalType = mimeType || 'video/webm';
        const blob = new Blob(chunks.current, { type: finalType });
        console.log(`Gravação finalizada. Tipo: ${finalType}, Tamanho: ${(blob.size / 1024 / 1024).toFixed(2)} MB`);
        setRecordedBlob(blob);
        setPreviewUrl(URL.createObjectURL(blob));
        stopTracks();
      };

      recorder.start(1000); 
      mediaRecorderRef.current = recorder;
      setIsRecording(true);
    } catch (e) {
      console.error("Erro ao iniciar MediaRecorder:", e);
      alert("Erro ao iniciar gravação. Tente usar outro navegador.");
    }
  };

  const handleStopRecording = () => {
    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
      mediaRecorderRef.current.stop();
    }
    setIsRecording(false);
  };

  const handleRepeat = () => {
    setRecordedBlob(null);
    if (previewUrl) URL.revokeObjectURL(previewUrl);
    setPreviewUrl(null);
    setActiveLine(0);
    setTimeLeft(MAX_RECORDING_TIME);
    startCamera();
  };

  const getFullScript = () => {
    if (!scenario) return [];
    const name = scenario.customerName;
    const intro = `Oi ${name}, tudo bem? Sou o ${firstName}, técnico da Claro.`;
    switch(scenario.product) {
      case 'TV': return [intro, `O Claro TV+ é realmente incrível.`, `O controle tem comando de voz integrado.`, `Aperte o microfone e diga o que quer ver.`, `Diga "Netflix" e o app abre na hora!`, `Não precisa mais decorar números de canais.`, `Tudo o que a senhora gosta em um só lugar.`, `Ficou claro como essa facilidade vai ajudar?` ];
      case 'Mesh': return [`Oi Dr. Marcos, sou o ${firstName} da Claro e vou resolver seu sinal.`, `Para telemedicina, estabilidade é fundamental.`, `O Wi-Fi Mesh cria uma malha inteligente na casa.`, `Diferente de um repetidor, não derruba a velocidade.`, `Mantém o sinal forte aqui e no andar de cima.`, `Sem precisar passar cabos ou fazer obra.`, `Podemos testar agora e verá que a oscilação acabou.`, `O que achou dessa solução definitiva?` ];
      case 'Virtua': return [`E aí Enzo! Sou o ${firstName}, técnico da Claro. Bora baixar esse ping?`, `O Wi-Fi 6 é tecnologia de ponta para gamers.`, `Ele usa frequências limpas, evitando o lag.`, `Nossa rede tem baixa latência (jitter).`, `Sua reação no FPS será muito mais rápida.`, `Larga banda permite jogar enquanto outros veem 4K.`, `É o setup ideal para performance competitiva.`, `Sentiu a diferença na estabilidade agora?` ];
      default: return [`Olá ${name}, sou o ${firstName}, técnico da Claro.`, `Nossos produtos facilitam sua vida.`, `A tecnologia que instalamos é a melhor.`, `Foco total na sua estabilidade digital.`, `A Claro agradece a sua confiança.`, `Tudo certo com a sua conexão?` ];
    }
  };

  const fullScript = getFullScript();

  return (
    <div className="flex flex-col space-y-4 animate-fadeIn max-w-6xl mx-auto pb-10 px-2 md:px-4">
      <div className="flex items-center justify-between bg-white p-3 rounded-2xl shadow-sm border border-gray-100">
        <div>
          <h2 className="text-xs font-black claro-text-red uppercase tracking-widest">{scenario?.title}</h2>
          <p className="text-[10px] text-gray-400 font-bold uppercase">Cliente: {scenario?.customerName}</p>
        </div>
        <div className="flex items-center gap-2">
           {isRecording && <span className="text-xs font-black text-red-600 animate-pulse">{timeLeft}s</span>}
           <div className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest ${mode === 'knowledge' ? 'bg-orange-100 text-orange-600' : 'bg-blue-100 text-blue-600'}`}>
             {mode === 'knowledge' ? 'Etapa 1: Conhecimento' : 'Etapa 2: Com Roteiro'}
           </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        <div className="lg:col-span-5 flex flex-col space-y-4">
          <div className="relative aspect-[3/4] bg-black rounded-[32px] overflow-hidden shadow-2xl border-4 border-white">
            {!previewUrl ? <video ref={videoRef} autoPlay muted playsInline className="w-full h-full object-cover mirror" /> : <video src={previewUrl} controls playsInline className="w-full h-full object-cover" autoPlay />}
            {isRecording && <div className="absolute top-4 left-4 flex items-center gap-2 bg-red-600 px-3 py-1.5 rounded-full text-white text-[9px] font-black animate-pulse z-20">GRAVANDO...</div>}
          </div>
          <div className="flex flex-col gap-3">
            {!previewUrl ? (
              <button onClick={isRecording ? handleStopRecording : handleStartRecording} className={`w-full py-5 rounded-full border-4 font-black text-sm tracking-widest ${isRecording ? 'border-gray-200 bg-white text-gray-700' : 'border-red-100 bg-[#ee0000] text-white hover:bg-red-700 active:scale-95 transition-all'}`}>{isRecording ? 'PARAR' : 'GRAVAR AGORA'}</button>
            ) : (
              <div className="w-full flex gap-2">
                <button onClick={handleRepeat} className="flex-1 bg-gray-100 text-gray-600 font-black text-[10px] uppercase py-5 rounded-2xl">REPETIR</button>
                <button onClick={() => onComplete(recordedBlob!)} className="flex-[1.5] claro-red text-white font-black text-[10px] uppercase py-5 rounded-2xl shadow-lg">ENVIAR PARA IA</button>
              </div>
            )}
          </div>
        </div>

        <div className="lg:col-span-7 flex flex-col min-h-[350px]">
          {mode === 'script' ? (
            <div className="bg-gray-900 rounded-[32px] shadow-2xl overflow-hidden flex-1 flex flex-col relative border-4 border-gray-800">
              <div className="bg-gray-800 px-4 py-3 flex justify-between items-center text-[10px] font-black text-red-500 uppercase tracking-widest">Teleprompter Ativado</div>
              <div className="relative flex-1 overflow-hidden flex items-center justify-center p-4">
                <div className="absolute inset-x-0 top-1/2 -translate-y-1/2 h-20 md:h-24 bg-white/5 border-y border-white/10 z-0"></div>
                <div className="relative z-10 w-full transition-transform duration-700 ease-in-out text-center" style={{ transform: `translateY(${(fullScript.length / 2 - activeLine - 0.5) * LINE_HEIGHT}px)` }}>
                  {fullScript.map((line, idx) => (
                    <div key={idx} className={`flex items-center justify-center px-4 transition-all duration-500 ${idx === activeLine ? 'text-white text-lg md:text-2xl font-black opacity-100 scale-105 h-[60px] md:h-[80px]' : 'text-gray-600 text-xs md:text-base font-bold opacity-20 scale-90 h-[60px] md:h-[80px]'}`}>{line}</div>
                  ))}
                </div>
              </div>
            </div>
          ) : (
            <div className="bg-white rounded-[32px] shadow-sm border-4 border-orange-50 flex-1 flex flex-col items-center justify-center p-8 text-center space-y-6">
              <div className="w-20 h-20 bg-orange-100 rounded-full flex items-center justify-center text-orange-500"><svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.663 17h4.674a1 1 0 00.922-.618l2.7-6.187a1 1 0 00-.922-1.395H13.43l.73-4.38a1 1 0 00-1.747-.852l-6.407 8.01a1 1 0 00.787 1.629h4.105l-1.932 4.182a1 1 0 00.922 1.41z" /></svg></div>
              <h3 className="text-2xl font-black text-gray-800 uppercase tracking-tighter">Desafio Conhecimento</h3>
              <p className="text-gray-500 font-medium">Nesta etapa o roteiro está oculto. Explique este produto usando seu conhecimento! <br/><span className="text-red-500 text-xs">(Máx: 60s)</span></p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import { GoogleGenAI, Type } from "@google/genai";

export interface EvaluationResult {
  score: number;
  strengths: string;
  weaknesses: string;
  suggestions: string;
  transcript: string;
}

export const evaluateExplanation = async (
  videoBase64?: string, 
  videoMimeType: string = 'video/mp4',
  scenarioContext?: string
): Promise<EvaluationResult> => {
  if (!process.env.API_KEY) {
    console.error("ERRO CRÍTICO: API Key não encontrada no ambiente.");
    throw new Error("Configuração de API Key ausente.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // --- NORMALIZAÇÃO DE MIMETYPE PARA A IA ---
  // A API rejeita strings complexas como "video/webm; codecs=vp8".
  // Pegamos apenas a parte principal (ex: "video/webm").
  let cleanMimeType = videoMimeType.split(';')[0].trim().toLowerCase();

  // Mapeamentos de compatibilidade para dispositivos móveis
  if (cleanMimeType === 'video/quicktime') cleanMimeType = 'video/mp4'; // iOS grava como MOV, mas o conteúdo geralmente é compatível com container MP4 na visão da IA
  if (cleanMimeType === 'video/x-matroska') cleanMimeType = 'video/webm'; // Alguns Androids antigos
  if (cleanMimeType === 'application/octet-stream') cleanMimeType = 'video/mp4'; // Fallback genérico

  // Lista oficial de suportados pelo Gemini Vision
  const supportedTypes = ['video/mp4', 'video/mpeg', 'video/mov', 'video/avi', 'video/flv', 'video/mpg', 'video/webm', 'video/wmv', 'video/3gp'];

  if (!supportedTypes.includes(cleanMimeType)) {
    console.warn(`MimeType original "${cleanMimeType}" não listado como suportado oficial. Forçando "video/mp4" como tentativa de compatibilidade.`);
    cleanMimeType = 'video/mp4';
  }

  const systemInstruction = `Você é um avaliador de excelência de atendimento da Claro.
    Analise o vídeo do técnico explicando o produto.
    Critérios: Naturalidade, Clareza, Empatia e Correção Técnica.
    Retorne JSON válido.`;

  const contextPrompt = scenarioContext ? 
    `CENÁRIO: ${scenarioContext}.` : 
    "Avaliação técnica geral Claro.";

  const userPrompt = `
    Analise o vídeo:
    1. Postura e Sorriso.
    2. Clareza da explicação.
    3. Argumentação correta.

    ${contextPrompt}
  `;

  try {
    const parts: any[] = [{ text: userPrompt }];

    if (videoBase64) {
      const base64Data = videoBase64.includes(',') ? videoBase64.split(',')[1] : videoBase64;

      // Validação de tamanho antes do envio (Max ~20MB para inline)
      const sizeInBytes = (base64Data.length * 3) / 4;
      if (sizeInBytes > 19 * 1024 * 1024) {
        throw new Error("O vídeo ficou muito longo para análise (max 20MB). Tente gravar por menos tempo.");
      }

      parts.push({
        inlineData: {
          data: base64Data,
          mimeType: cleanMimeType
        }
      });
    }

    // gemini-2.0-flash-exp tem mostrado melhor compatibilidade com inputs multimodais variados
    const response = await ai.models.generateContent({
      model: "gemini-2.0-flash-exp",
      contents: { parts },
      config: {
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            score: { type: Type.NUMBER, description: "Nota de 0 a 10" },
            strengths: { type: Type.STRING, description: "Pontos positivos" },
            weaknesses: { type: Type.STRING, description: "Pontos a melhorar" },
            suggestions: { type: Type.STRING, description: "Sugestão prática" },
            transcript: { type: Type.STRING, description: "O que foi falado" }
          },
          required: ["score", "strengths", "weaknesses", "suggestions", "transcript"]
        }
      }
    });

    const jsonStr = response.text?.trim() || '{}';
    return JSON.parse(jsonStr);

  } catch (error: any) {
    console.error("Gemini API Error:", error);

    let errorMessage = "Erro desconhecido na análise.";
    let technicalDetails = error.message || "";

    if (technicalDetails.includes("INVALID_ARGUMENT")) {
      errorMessage = "Formato de vídeo incompatível ou arquivo corrompido.";
    } else if (technicalDetails.includes("404") || technicalDetails.includes("not found")) {
      errorMessage = "Serviço de IA temporariamente indisponível.";
    }

    return {
      score: 0,
      strengths: "Não foi possível analisar o vídeo.",
      weaknesses: errorMessage,
      suggestions: "Tente gravar um vídeo mais curto (max 30s) ou use outro navegador.",
      transcript: `Erro: ${technicalDetails.slice(0, 100)}`
    };
  }
};

