  const [activeTab, setActiveTab] = useState<'accesses' | 'evaluations' | 'users'>('evaluations');
  const [refresh, setRefresh] = useState(0);
  const [selectedEval, setSelectedEval] = useState<Evaluation | null>(null);
  const [videoUrl, setVideoUrl] = useState<string | null>(null);

  // States para criação de usuário
  const [showUserModal, setShowUserModal] = useState(false);
  const [cities, setCities] = useState<IBGECity[]>([]);
  const [loadingCities, setLoadingCities] = useState(false);
  const [newUser, setNewUser] = useState({
    name: '',
    login: '',
    cpf: '',
    email: '',
    uf: '',
    city: '',
    role: 'tech' as UserRole,
    password: ''
  });

  const accesses = useMemo(() => DB.accesses.all().sort((a,b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()), [refresh]);
  const evaluations = useMemo(() => DB.evaluations.all().sort((a,b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()), [refresh]);
  const users = useMemo(() => DB.users.all().sort((a, b) => a.name.localeCompare(b.name)), [refresh]);

  useEffect(() => {
    if (selectedEval) {
      MediaStorage.get(selectedEval.id).then(blob => { if (blob) setVideoUrl(URL.createObjectURL(blob)); });
    } else setVideoUrl(null);
  }, [selectedEval]);

  useEffect(() => {
    if (newUser.uf) {
      setLoadingCities(true);
      fetch(`https://servicodados.ibge.gov.br/api/v1/localidades/estados/${newUser.uf}/municipios?orderBy=nome`)
        .then(res => res.json())
        .then((data: IBGECity[]) => {
          setCities(data);
          setLoadingCities(false);
        })
        .catch(() => setLoadingCities(false));
    }
  }, [newUser.uf]);

  const handleCreateUser = (e: React.FormEvent) => {
    e.preventDefault();
    const clean = cleanCPF(newUser.cpf);

    if (!validateCPF(clean)) {
      alert("CPF Inválido");
      return;
    }

    if (DB.users.findByCpf(clean)) {
      alert("Usuário já existe com este CPF.");
      return;
    }

    DB.users.add({
      id: Math.random().toString(36).substr(2, 9),
      ...newUser,
      cpf: clean,
      createdAt: new Date().toISOString()
    });

    alert("Usuário criado com sucesso!");
    setShowUserModal(false);
    setNewUser({ name: '', login: '', cpf: '', email: '', uf: '', city: '', role: 'tech', password: '' });
    setRefresh(prev => prev + 1);
  };

  return (
    <div className="space-y-6 animate-fadeIn pb-20">
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <div className="bg-white p-4 rounded-2xl shadow-sm border border-gray-100">
          <p className="text-[10px] font-bold text-gray-400 uppercase">Avaliações</p>
          <p className="text-2xl font-black claro-text-red">{evaluations.length}</p>
        </div>
        <div className="bg-white p-4 rounded-2xl shadow-sm border border-gray-100">
          <p className="text-[10px] font-bold text-gray-400 uppercase">Acessos Hoje</p>
          <p className="text-2xl font-black text-blue-600">{accesses.filter(a => new Date(a.timestamp).toDateString() === new Date().toDateString()).length}</p>
        </div>
        <div className="bg-white p-4 rounded-2xl shadow-sm border border-gray-100">
          <p className="text-[10px] font-bold text-gray-400 uppercase">Técnicos</p>
          <p className="text-2xl font-black text-gray-800">{users.filter(u => u.role === 'tech').length}</p>
        </div>
        <div className="bg-white p-4 rounded-2xl shadow-sm border border-gray-100">
          <p className="text-[10px] font-bold text-gray-400 uppercase">Admins</p>
          <p className="text-2xl font-black text-gray-800">{users.filter(u => u.role !== 'tech').length}</p>
        </div>
      </div>

      <div className="flex bg-white p-1 rounded-xl shadow-sm border border-gray-200">
        <button onClick={() => setActiveTab('evaluations')} className={`flex-1 py-2 rounded-lg font-bold text-sm transition-all ${activeTab === 'evaluations' ? 'claro-red text-white' : 'text-gray-500'}`}>Avaliações</button>
        <button onClick={() => setActiveTab('users')} className={`flex-1 py-2 rounded-lg font-bold text-sm transition-all ${activeTab === 'users' ? 'claro-red text-white' : 'text-gray-500'}`}>Usuários</button>
        <button onClick={() => setActiveTab('accesses')} className={`flex-1 py-2 rounded-lg font-bold text-sm transition-all ${activeTab === 'accesses' ? 'claro-red text-white' : 'text-gray-500'}`}>Acessos</button>
      </div>

      <div className="bg-white rounded-2xl shadow-sm overflow-hidden border border-gray-100 min-h-[400px]">
        {activeTab === 'evaluations' && (
          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-gray-50 border-b border-gray-100">
                  <th className="p-4 text-xs font-bold text-gray-400 uppercase">Técnico</th>
                  <th className="p-4 text-xs font-bold text-gray-400 uppercase">Modo</th>
                  <th className="p-4 text-xs font-bold text-gray-400 uppercase text-center">Nota</th>
                  <th className="p-4 text-xs font-bold text-gray-400 uppercase text-right">Ação</th>
                </tr>
              </thead>
              <tbody className="divide-y">
                {evaluations.map((ev) => (
                  <tr key={ev.id} className="hover:bg-red-50/30 transition-colors">
                    <td className="p-4">
                      <p className="font-bold text-sm text-gray-700">{ev.userName}</p>
                      <p className="text-[10px] text-gray-400">{ev.city}/{ev.uf}</p>
                    </td>
                    <td className="p-4">
                      <span className={`text-[9px] font-black px-2 py-0.5 rounded-full uppercase ${ev.evalMode === 'knowledge' ? 'bg-orange-100 text-orange-600' : 'bg-blue-100 text-blue-600'}`}>
                        {ev.evalMode === 'knowledge' ? 'Conhecimento' : 'Com Roteiro'}
                      </span>
                    </td>
                    <td className="p-4 text-center">
                      <span className={`inline-block px-3 py-1 rounded-full font-black text-sm ${ev.score >= 8 ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>{ev.score.toFixed(1)}</span>
                    </td>
                    <td className="p-4 text-right">
                      <button onClick={() => setSelectedEval(ev)} className="claro-text-red text-xs font-bold hover:underline">Detalhes</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {activeTab === 'users' && (
          <div className="flex flex-col h-full">
            <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-gray-50">
               <h3 className="text-xs font-black uppercase text-gray-500 tracking-widest">Base de Usuários</h3>
               <button 
                 onClick={() => setShowUserModal(true)}
                 className="bg-black text-white px-4 py-2 rounded-lg text-xs font-bold uppercase tracking-wider hover:bg-gray-800 transition-colors flex items-center gap-2"
               >
                 <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
                 Nova Conta
               </button>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="border-b border-gray-100">
                    <th className="p-4 text-xs font-bold text-gray-400 uppercase">Nome</th>
                    <th className="p-4 text-xs font-bold text-gray-400 uppercase">Login/CPF</th>
                    <th className="p-4 text-xs font-bold text-gray-400 uppercase">Região</th>
                    <th className="p-4 text-xs font-bold text-gray-400 uppercase text-right">Perfil</th>
                  </tr>
                </thead>
                <tbody className="divide-y">
                  {users.map((u) => (
                    <tr key={u.id} className="hover:bg-gray-50 transition-colors">
                      <td className="p-4 font-bold text-sm text-gray-800">{u.name}</td>
                      <td className="p-4 text-xs text-gray-500">
                        <div className="font-medium">{u.login}</div>
                        <div className="opacity-70">{u.cpf}</div>
                      </td>
                      <td className="p-4 text-xs text-gray-500">{u.city}/{u.uf}</td>
                      <td className="p-4 text-right">
                        <span className={`text-[9px] font-black px-2 py-0.5 rounded-full uppercase ${u.role !== 'tech' ? 'bg-black text-white' : 'bg-gray-100 text-gray-500'}`}>
                          {u.role === 'tech' ? 'Técnico' : u.role === 'admin' ? 'Admin' : 'Super Admin'}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {activeTab === 'accesses' && (
          <div className="overflow-x-auto">
             <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="bg-gray-50 border-b border-gray-100">
                    <th className="p-4 text-xs font-bold text-gray-400 uppercase">Usuário</th>
                    <th className="p-4 text-xs font-bold text-gray-400 uppercase">Data/Hora</th>
                    <th className="p-4 text-xs font-bold text-gray-400 uppercase text-right">Local</th>
                  </tr>
                </thead>
                <tbody className="divide-y">
                  {accesses.map((acc) => (
                    <tr key={acc.id}>
                      <td className="p-4 font-bold text-sm text-gray-700">{acc.userName}</td>
                      <td className="p-4 text-xs text-gray-500">{new Date(acc.timestamp).toLocaleString()}</td>
                      <td className="p-4 text-xs text-gray-500 text-right">{acc.city}/{acc.uf}</td>
                    </tr>
                  ))}
                </tbody>
             </table>
          </div>
        )}
      </div>

      {/* Modal Criar Usuário */}
      {showUserModal && (
        <div className="fixed inset-0 z-[150] bg-black/60 backdrop-blur-sm flex items-center justify-center p-4 animate-fadeIn">
          <div className="bg-white w-full max-w-lg rounded-[32px] shadow-2xl p-8 relative animate-scaleUp max-h-[90vh] overflow-y-auto">
            <button onClick={() => setShowUserModal(false)} className="absolute top-6 right-6 text-gray-400 hover:text-red-500"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg></button>

            <h3 className="text-xl font-black claro-text-red uppercase tracking-tight mb-6">Novo Cadastro</h3>

            <form onSubmit={handleCreateUser} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="col-span-2">
                  <label className="text-[10px] font-bold text-gray-400 uppercase ml-1">Nome Completo</label>
                  <input required type="text" className="w-full p-3 bg-gray-50 rounded-xl border border-gray-100 focus:claro-border-red outline-none" value={newUser.name} onChange={e => setNewUser({...newUser, name: e.target.value})} />
                </div>
                <div>
                  <label className="text-[10px] font-bold text-gray-400 uppercase ml-1">CPF (Só números)</label>
                  <input required type="text" maxLength={11} className="w-full p-3 bg-gray-50 rounded-xl border border-gray-100 focus:claro-border-red outline-none" value={newUser.cpf} onChange={e => setNewUser({...newUser, cpf: cleanCPF(e.target.value)})} />
                </div>
                <div>
                  <label className="text-[10px] font-bold text-gray-400 uppercase ml-1">Login</label>
                  <input required type="text" className="w-full p-3 bg-gray-50 rounded-xl border border-gray-100 focus:claro-border-red outline-none" value={newUser.login} onChange={e => setNewUser({...newUser, login: e.target.value})} />
                </div>
                <div className="col-span-2">
                  <label className="text-[10px] font-bold text-gray-400 uppercase ml-1">Email</label>
                  <input required type="email" className="w-full p-3 bg-gray-50 rounded-xl border border-gray-100 focus:claro-border-red outline-none" value={newUser.email} onChange={e => setNewUser({...newUser, email: e.target.value})} />
                </div>
                <div>
                  <label className="text-[10px] font-bold text-gray-400 uppercase ml-1">UF</label>
                  <select required className="w-full p-3 bg-gray-50 rounded-xl border border-gray-100 focus:claro-border-red outline-none" value={newUser.uf} onChange={e => setNewUser({...newUser, uf: e.target.value, city: ''})}>
                    <option value="">Selecione</option>
                    {BRAZIL_STATES.map(s => <option key={s.uf} value={s.uf}>{s.uf}</option>)}
                  </select>
                </div>
                <div>
                  <label className="text-[10px] font-bold text-gray-400 uppercase ml-1">Cidade</label>
                  <select required disabled={loadingCities || !newUser.uf} className="w-full p-3 bg-gray-50 rounded-xl border border-gray-100 focus:claro-border-red outline-none disabled:opacity-50" value={newUser.city} onChange={e => setNewUser({...newUser, city: e.target.value})}>
                    <option value="">{loadingCities ? '...' : 'Selecione'}</option>
                    {cities.map(c => <option key={c.id} value={c.nome}>{c.nome}</option>)}
                  </select>
                </div>
                <div className="col-span-2">
                  <label className="text-[10px] font-bold text-gray-400 uppercase ml-1">Perfil de Acesso</label>
                  <div className="flex gap-4 mt-1">
                    <label className={`flex-1 p-3 rounded-xl border cursor-pointer transition-all flex items-center justify-center gap-2 ${newUser.role === 'tech' ? 'claro-border-red bg-red-50 text-[#ee0000]' : 'border-gray-100 bg-gray-50 text-gray-400'}`}>
                      <input type="radio" name="role" className="hidden" checked={newUser.role === 'tech'} onChange={() => setNewUser({...newUser, role: 'tech'})} />
                      <span className="font-black text-xs uppercase">Técnico</span>
                    </label>
                    <label className={`flex-1 p-3 rounded-xl border cursor-pointer transition-all flex items-center justify-center gap-2 ${newUser.role === 'admin' ? 'border-black bg-gray-900 text-white' : 'border-gray-100 bg-gray-50 text-gray-400'}`}>
                      <input type="radio" name="role" className="hidden" checked={newUser.role === 'admin'} onChange={() => setNewUser({...newUser, role: 'admin'})} />
                      <span className="font-black text-xs uppercase">Admin</span>
                    </label>
                  </div>
                </div>
                <div className="col-span-2">
                  <label className="text-[10px] font-bold text-gray-400 uppercase ml-1">Senha Inicial</label>
                  <input required type="text" className="w-full p-3 bg-gray-50 rounded-xl border border-gray-100 focus:claro-border-red outline-none" value={newUser.password} onChange={e => setNewUser({...newUser, password: e.target.value})} />
                </div>
              </div>
              <button type="submit" className="w-full py-4 claro-red text-white font-black rounded-xl uppercase tracking-widest hover:bg-red-700 transition-colors mt-4">Criar Usuário</button>
            </form>
          </div>
        </div>
      )}

      {selectedEval && (
        <div className="fixed inset-0 z-[100] bg-black/80 flex items-center justify-center p-4 backdrop-blur-sm">
          <div className="bg-white w-full max-w-4xl max-h-[90vh] rounded-3xl overflow-hidden shadow-2xl flex flex-col animate-scaleUp">
            <div className="claro-red p-4 flex justify-between items-center text-white">
              <h3 className="font-bold uppercase">Relatório: {selectedEval.userName}</h3>
              <button onClick={() => setSelectedEval(null)} className="p-1 hover:bg-white/20 rounded-full"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg></button>
            </div>
            <div className="flex-1 overflow-y-auto p-6 space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="bg-black rounded-2xl aspect-video overflow-hidden">
                  {videoUrl && <video src={videoUrl} controls className="w-full h-full object-contain" />}
                </div>
                <div className="space-y-4">
                   <div className="bg-gray-50 p-4 rounded-2xl border border-gray-100 flex justify-between items-center">
                     <span className="text-xs font-bold text-gray-400 uppercase">Performance ({selectedEval.evalMode})</span>
                     <span className={`text-4xl font-black ${selectedEval.score >= 8 ? 'text-green-500' : 'text-red-500'}`}>{selectedEval.score.toFixed(1)}</span>
                   </div>
                   <ExpandableSection title="Pontos Fortes" content={selectedEval.strengths} colorClass="border-green-500" textColor="text-green-700" />
                   <ExpandableSection title="Oportunidades" content={selectedEval.weaknesses} colorClass="border-red-500" textColor="text-red-700" />
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export type UserRole = 'tech' | 'commercial' | 'admin' | 'superadmin';
export type EvalMode = 'knowledge' | 'script';

export interface User {
  id: string;
  name: string;
  login: string;
  cpf: string;
  email: string;
  uf: string;
  city: string;
  role: UserRole;
  password?: string;
  createdAt: string;
}

export interface AccessLog {
  id: string;
  userId: string;
  userName: string;
  timestamp: string;
  uf: string;
  city: string;
}

export interface Evaluation {
  id: string;
  userId: string;
  userName: string;
  timestamp: string;
  score: number;
  strengths: string;
  weaknesses: string;
  suggestions: string;
  videoUrl?: string;
  transcript: string;
  uf: string;
  city: string;
  evalMode: EvalMode;
  correlationId: string;
}

export interface Attempt {
  id: string;
  userId: string;
  timestamp: string;
  status: 'completed' | 'abandoned';
}

export interface AppState {
  currentUser: User | null;
  isAuthenticated: boolean;
}

import React, { useState, useMemo, useEffect } from 'react';
import { DB } from '../db';
import { User, AccessLog, Evaluation, UserRole } from '../types';
import { MediaStorage } from '../services/storageService';
import { validateCPF, cleanCPF } from '../utils/validators';

interface IBGECity {
  id: number;
  nome: string;
}

const BRAZIL_STATES = [
  { uf: 'AC', nome: 'Acre' }, { uf: 'AL', nome: 'Alagoas' }, { uf: 'AP', nome: 'Amapá' },
  { uf: 'AM', nome: 'Amazonas' }, { uf: 'BA', nome: 'Bahia' }, { uf: 'CE', nome: 'Ceará' },
  { uf: 'DF', nome: 'Distrito Federal' }, { uf: 'ES', nome: 'Espírito Santo' }, { uf: 'GO', nome: 'Goiás' },
  { uf: 'MA', nome: 'Maranhão' }, { uf: 'MT', nome: 'Mato Grosso' }, { uf: 'MS', nome: 'Mato Grosso do Sul' },
  { uf: 'MG', nome: 'Minas Gerais' }, { uf: 'PA', nome: 'Pará' }, { uf: 'PB', nome: 'Paraíba' },
  { uf: 'PR', nome: 'Paraná' }, { uf: 'PE', nome: 'Pernambuco' }, { uf: 'PI', nome: 'Piauí' },
  { uf: 'RJ', nome: 'Rio de Janeiro' }, { uf: 'RN', nome: 'Rio Grande do Norte' }, { uf: 'RS', nome: 'Rio Grande do Sul' },
  { uf: 'RO', nome: 'Rondônia' }, { uf: 'RR', nome: 'Roraima' }, { uf: 'SC', nome: 'Santa Catarina' },
  { uf: 'SP', nome: 'São Paulo' }, { uf: 'SE', nome: 'Sergipe' }, { uf: 'TO', nome: 'Tocantins' }
];

const ExpandableSection: React.FC<{ title: string; content: string; colorClass: string; textColor: string }> = ({ title, content, colorClass, textColor }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const isLong = content.length > 150;
  return (
    <div className={`border-l-4 ${colorClass} pl-4 relative group`}>
      <h4 className={`text-xs font-black ${textColor} uppercase flex items-center justify-between`}>
        {title}
        {isLong && (
          <button onClick={() => setIsExpanded(!isExpanded)} className="p-1 hover:bg-gray-100 rounded-full transition-colors text-gray-400">
            <svg xmlns="http://www.w3.org/2000/svg" className={`h-4 w-4 transition-transform ${isExpanded ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg>
          </button>
        )}
      </h4>
      <p className={`text-sm text-gray-600 leading-relaxed ${!isExpanded && isLong ? 'line-clamp-3' : ''}`}>{content}</p>
    </div>
  );
};

export const AdminDashboard: React.FC<{ currentUser: User }> = ({ currentUser }) => {
  const [activeTab, setActiveTab] = useState<'accesses' | 'evaluations' | 'users'>('evaluations');
  const [refresh, setRefresh] = useState(0);
  const [selectedEval, setSelectedEval] = useState<Evaluation | null>(null);
  const [videoUrl, setVideoUrl] = useState<string | null>(null);

  // States para criação de usuário
  const [showUserModal, setShowUserModal] = useState(false);
  const [cities, setCities] = useState<IBGECity[]>([]);
  const [loadingCities, setLoadingCities] = useState(false);
  const [newUser, setNewUser] = useState({
    name: '',
    login: '',
    cpf: '',
    email: '',
    uf: '',
    city: '',
    role: 'tech' as UserRole,
    password: ''
  });

  const accesses = useMemo(() => DB.accesses.all().sort((a,b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()), [refresh]);
  const evaluations = useMemo(() => DB.evaluations.all().sort((a,b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()), [refresh]);
  const users = useMemo(() => DB.users.all().sort((a, b) => a.name.localeCompare(b.name)), [refresh]);

  useEffect(() => {
    if (selectedEval) {
      MediaStorage.get(selectedEval.id).then(blob => { if (blob) setVideoUrl(URL.createObjectURL(blob)); });
    } else setVideoUrl(null);
  }, [selectedEval]);

  useEffect(() => {
    if (newUser.uf) {
      setLoadingCities(true);
      fetch(`https://servicodados.ibge.gov.br/api/v1/localidades/estados/${newUser.uf}/municipios?orderBy=nome`)
        .then(res => res.json())
        .then((data: IBGECity[]) => {
          setCities(data);
          setLoadingCities(false);
        })
        .catch(() => setLoadingCities(false));
    }
  }, [newUser.uf]);

  const handleCreateUser = (e: React.FormEvent) => {
    e.preventDefault();
    const clean = cleanCPF(newUser.cpf);

    if (!validateCPF(clean)) {
      alert("CPF Inválido");
      return;
    }

    if (DB.users.findByCpf(clean)) {
      alert("Usuário já existe com este CPF.");
      return;
    }

    DB.users.add({
      id: Math.random().toString(36).substr(2, 9),
      ...newUser,
      cpf: clean,
      createdAt: new Date().toISOString()
    });

    alert("Usuário criado com sucesso!");
    setShowUserModal(false);
    setNewUser({ name: '', login: '', cpf: '', email: '', uf: '', city: '', role: 'tech', password: '' });
    setRefresh(prev => prev + 1);
  };

  return (
    <div className="space-y-6 animate-fadeIn pb-20">
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <div className="bg-white p-4 rounded-2xl shadow-sm border border-gray-100">
          <p className="text-[10px] font-bold text-gray-400 uppercase">Avaliações</p>
          <p className="text-2xl font-black claro-text-red">{evaluations.length}</p>
        </div>
        <div className="bg-white p-4 rounded-2xl shadow-sm border border-gray-100">
          <p className="text-[10px] font-bold text-gray-400 uppercase">Acessos Hoje</p>
