            <div className="flex items-center gap-4">
              <div className="flex flex-col items-end">
                <span className="hidden sm:inline text-sm opacity-90 font-bold leading-tight">
                  Olá, {user.name.split(' ')[0]}
                </span>
                {isAdmin ? (
                  <button 
                    onClick={onAdminClick}
                    className="mt-0.5 bg-white text-[#ee0000] px-2 py-0.5 rounded text-[9px] font-black uppercase tracking-tighter hover:bg-red-50 transition-colors shadow-sm flex items-center gap-1"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-2.5 w-2.5" viewBox="0 0 20 20" fill="currentColor">
                      <path d="M5 4a1 1 0 00-2 0v7.268a2 2 0 000 3.464V16a1 1 0 102 0v-1.268a2 2 0 000-3.464V4zM11 4a1 1 0 10-2 0v1.268a2 2 0 000 3.464V16a1 1 0 102 0V8.732a2 2 0 000-3.464V4zM16 3a1 1 0 011 1v7.268a2 2 0 010 3.464V16a1 1 0 11-2 0v-1.268a2 2 0 010-3.464V4a1 1 0 011-1z" />
                    </svg>
                    Painel Admin
                  </button>
                ) : (
                  <span className="text-[9px] opacity-70 font-bold uppercase tracking-widest leading-none mt-0.5">
                    {user.role === 'commercial' ? 'Comercial' : 'Técnico'}
                  </span>
                )}
              </div>
              <button 
                onClick={onLogout}
                className="bg-white/20 hover:bg-white/30 px-3 py-1.5 rounded-lg text-xs font-bold transition-colors border border-white/10"
              >
                Sair
              </button>
            </div>
          )}
        </div>
      </header>

      <main className="flex-1 max-w-4xl w-full mx-auto p-4">
        {title && <h2 className="text-2xl font-bold mb-6 claro-text-red animate-fadeIn">{title}</h2>}
        {children}
