import React, { useMemo } from 'react';
import { User, Evaluation } from '../types';
import { DB } from '../db';
import { 
  LineChart, 
  Line, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  AreaChart, 
  Area,
  BarChart,
  Bar,
  Cell
} from 'recharts';

interface DashboardProps {
  user: User;
  onNavigate: (page: string) => void;
}

interface RankingEntry {
  name: string;
  avg: number;
  count: number;
  best: number;
  uf: string;
  city: string;
}

export const Dashboard: React.FC<DashboardProps> = ({ user, onNavigate }) => {
  const evaluations = useMemo(() => DB.evaluations.all(), []);

  // Ranking Logic
  const ranking = useMemo(() => {
    const scores = evaluations.reduce((acc: Record<string, RankingEntry>, curr) => {
      if (!acc[curr.userId]) {
        acc[curr.userId] = { 
          name: curr.userName, 
          avg: 0, 
          count: 0, 
          best: 0,
          uf: curr.uf,
          city: curr.city
        };
      }
      acc[curr.userId].count++;
      acc[curr.userId].best = Math.max(acc[curr.userId].best, curr.score);
      return acc;
    }, {} as Record<string, RankingEntry>);

    return (Object.values(scores) as RankingEntry[])
      .sort((a, b) => b.best - a.best)
      .slice(0, 5);
  }, [evaluations]);

  // Chart Data: Trend (Average score over time)
  const trendData = useMemo(() => {
    const dailyData: Record<string, { sum: number; count: number }> = {};

    // Sort evaluations by date
    const sortedEvals = [...evaluations].sort((a, b) => 
      new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime()
    );

    // Group by date (DD/MM)
    sortedEvals.forEach(ev => {
      const date = new Date(ev.timestamp).toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' });
      if (!dailyData[date]) dailyData[date] = { sum: 0, count: 0 };
      dailyData[date].sum += ev.score;
      dailyData[date].count++;
    });

    return Object.entries(dailyData).map(([date, data]) => ({
      name: date,
      score: Number((data.sum / data.count).toFixed(1))
    })).slice(-7); // Last 7 days with activity
  }, [evaluations]);

  // Chart Data: Score Distribution
  const distributionData = useMemo(() => {
    const buckets = [
      { name: '0-5', count: 0, color: '#EF4444' },
      { name: '5-7', count: 0, color: '#F59E0B' },
      { name: '7-9', count: 0, color: '#10B981' },
      { name: '9-10', count: 0, color: '#059669' }
    ];

    evaluations.forEach(ev => {
      if (ev.score < 5) buckets[0].count++;
      else if (ev.score < 7) buckets[1].count++;
      else if (ev.score < 9) buckets[2].count++;
      else buckets[3].count++;
    });

    return buckets;
  }, [evaluations]);

  const isAdmin = user.role === 'admin' || user.role === 'superadmin';

  return (
    <div className="space-y-6 md:space-y-8 animate-fadeIn px-2 sm:px-0">
      {/* Seção de Boas-vindas Simplificada */}
      <div className="bg-white p-6 md:p-8 rounded-[40px] shadow-sm border border-gray-100 flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <p className="text-[#ee0000] text-[10px] font-black uppercase tracking-[0.2em] mb-1">Bem-vindo ao Portal</p>
          <h2 className="text-3xl md:text-4xl font-black text-gray-800 tracking-tight leading-tight">Olá, {user.name.split(' ')[0]}!</h2>
          <p className="text-xs text-gray-400 mt-1 uppercase font-bold tracking-widest">
            {user.role === 'superadmin' ? 'Super Administrador' : user.role === 'admin' ? 'Gestor Regional' : user.role === 'commercial' ? 'Consultor Comercial' : 'Consultor Técnico'}
          </p>
        </div>
        <div className="bg-red-50 text-[#ee0000] px-5 py-3 rounded-2xl text-[10px] md:text-xs font-black border border-red-100 text-center uppercase tracking-widest">
          {user.city} / {user.uf}
        </div>
      </div>

      {/* Cards de Menu - Responsivos */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6">
        <button 
          onClick={() => onNavigate('consultivo')}
          className="group p-6 md:p-8 bg-white border-2 border-transparent hover:claro-border-red rounded-[40px] shadow-sm transition-all text-left flex items-center justify-between hover:shadow-xl active:scale-[0.98]"
        >
          <div className="flex-1">
            <h3 className="text-xl md:text-2xl font-black claro-text-red mb-2">Treinamento Consultivo</h3>
            <p className="text-gray-500 text-sm md:text-base leading-snug">Pratique sua abordagem e receba feedback imediato da IA.</p>
            <div className="mt-4 flex items-center gap-2">
              <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></span>
              <span className="text-[10px] font-black text-green-600 uppercase tracking-widest">Disponível</span>
            </div>
          </div>
          <div className="w-12 h-12 md:w-16 md:h-16 rounded-full bg-red-50 flex items-center justify-center text-[#ee0000] group-hover:bg-[#ee0000] group-hover:text-white transition-all shadow-inner ml-4 shrink-0">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 md:h-8 md:w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14.752 11.168l-3.197-2.132A1 1 0 0010 9.87v4.263a1 1 0 001.555.832l3.197-2.132a1 1 0 000-1.664z" />
            </svg>
          </div>
        </button>

        {isAdmin && (
          <button 
            onClick={() => onNavigate('admin')}
            className="group p-6 md:p-8 bg-white border-2 border-dashed border-gray-200 hover:claro-border-red rounded-[40px] shadow-sm transition-all text-left flex items-center justify-between hover:shadow-xl active:scale-[0.98]"
          >
            <div className="flex-1">
              <h3 className="text-xl md:text-2xl font-black text-gray-800 mb-2">Painel de Gestão</h3>
              <p className="text-gray-500 text-sm md:text-base leading-snug">Acompanhe indicadores, relatórios e performance da rede.</p>
              <div className="mt-4">
                <span className="px-3 py-1 bg-black text-white text-[9px] font-black rounded-full uppercase tracking-widest">Acesso Restrito</span>
              </div>
            </div>
            <div className="w-12 h-12 md:w-16 md:h-16 rounded-full bg-gray-50 flex items-center justify-center text-gray-400 group-hover:bg-black group-hover:text-white transition-all shadow-inner ml-4 shrink-0">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 md:h-8 md:w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 00-2-2H5a2 2 0 00-2 2v10m10-10V5a2 2 0 00-2-2h-2a2 2 0 00-2 2v14m10-4V7a2 2 0 00-2-2h-2a2 2 0 00-2 2v12" />
              </svg>
            </div>
          </button>
        )}
      </div>

      {/* Visual Data Representation - Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Trend Chart */}
        <div className="bg-white p-6 md:p-8 rounded-[40px] shadow-sm border border-gray-100 flex flex-col">
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-sm font-black text-gray-800 uppercase tracking-widest">Tendência de Qualidade</h3>
            <span className="text-[10px] text-gray-400 font-bold uppercase">Média Diária</span>
          </div>
          <div className="h-64 w-full">
            {trendData.length > 0 ? (
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={trendData}>
                  <defs>
                    <linearGradient id="colorScore" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor="#ee0000" stopOpacity={0.3}/>
                      <stop offset="95%" stopColor="#ee0000" stopOpacity={0}/>
                    </linearGradient>
                  </defs>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f1f1" />
                  <XAxis 
                    dataKey="name" 
                    axisLine={false} 
                    tickLine={false} 
                    tick={{fontSize: 10, fontWeight: 'bold', fill: '#9CA3AF'}} 
                  />
                  <YAxis 
                    domain={[0, 10]} 
                    axisLine={false} 
                    tickLine={false} 
                    tick={{fontSize: 10, fontWeight: 'bold', fill: '#9CA3AF'}}
                  />
                  <Tooltip 
                    contentStyle={{borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)', fontWeight: 'bold'}}
                  />
                  <Area type="monotone" dataKey="score" stroke="#ee0000" strokeWidth={3} fillOpacity={1} fill="url(#colorScore)" />
                </AreaChart>
              </ResponsiveContainer>
            ) : (
              <div className="flex flex-col items-center justify-center h-full text-gray-300 space-y-2">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12 opacity-20" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M7 12l3-3 3 3 4-4M8 21l4-4 4 4M3 4h18M4 4h16v12a1 1 0 01-1 1H5a1 1 0 01-1-1V4z" />
                </svg>
                <p className="text-xs uppercase font-black tracking-widest">Sem dados suficientes</p>
              </div>
            )}
          </div>
        </div>

        {/* Distribution Chart */}
        <div className="bg-white p-6 md:p-8 rounded-[40px] shadow-sm border border-gray-100 flex flex-col">
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-sm font-black text-gray-800 uppercase tracking-widest">Distribuição de Notas</h3>
            <span className="text-[10px] text-gray-400 font-bold uppercase">Volume por Faixa</span>
          </div>
          <div className="h-64 w-full">
            {evaluations.length > 0 ? (
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={distributionData}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f1f1" />
                  <XAxis 
                    dataKey="name" 
                    axisLine={false} 
                    tickLine={false} 
                    tick={{fontSize: 10, fontWeight: 'bold', fill: '#9CA3AF'}} 
                  />
                  <YAxis 
                    axisLine={false} 
                    tickLine={false} 
                    tick={{fontSize: 10, fontWeight: 'bold', fill: '#9CA3AF'}}
                  />
                  <Tooltip 
                    cursor={{fill: '#f9fafb'}}
                    contentStyle={{borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)', fontWeight: 'bold'}}
                  />
                  <Bar dataKey="count" radius={[8, 8, 0, 0]}>
                    {distributionData.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={entry.color} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            ) : (
              <div className="flex flex-col items-center justify-center h-full text-gray-300 space-y-2">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12 opacity-20" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 00-2-2H5a2 2 0 00-2 2v10m10-10V5a2 2 0 00-2-2h-2a2 2 0 00-2 2v14m10-4V7a2 2 0 00-2-2h-2a2 2 0 00-2 2v12" />
                </svg>
                <p className="text-xs uppercase font-black tracking-widest">Aguardando avaliações</p>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Ranking Section - Adaptado para Mobile */}
      <div className="bg-white rounded-[40px] shadow-sm overflow-hidden border border-gray-100">
        <div className="claro-red p-6 text-white font-black flex items-center justify-between">
          <div className="flex items-center gap-3">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-7.714 2.143L11 21l-2.286-6.857L1 12l7.714-2.143L11 3z" />
            </svg>
            <span className="uppercase tracking-[0.2em] text-xs md:text-sm">Ranking Performance</span>
          </div>
          <span className="text-[10px] opacity-70 uppercase tracking-widest">Top 5 Regional</span>
        </div>
        <div className="divide-y divide-gray-50">
          {ranking.length > 0 ? ranking.map((entry, idx) => (
            <div key={idx} className="p-5 md:p-6 flex items-center gap-4 hover:bg-gray-50/50 transition-colors">
              <div className="relative">
                <span className={`text-2xl md:text-3xl font-black w-8 block text-center ${idx === 0 ? 'text-yellow-500' : idx === 1 ? 'text-gray-400' : idx === 2 ? 'text-orange-400' : 'text-gray-200'}`}>
                  {idx + 1}
                </span>
                {idx === 0 && <div className="absolute -top-3 left-1/2 -translate-x-1/2 text-[10px]">👑</div>}
              </div>
              <div className="flex-1">
                <p className="font-black text-gray-800 text-sm md:text-base">{entry.name}</p>
                <p className="text-[10px] md:text-xs text-gray-400 font-bold uppercase tracking-widest">{entry.city}, {entry.uf}</p>
              </div>
              <div className="text-right">
                <span className={`text-xl md:text-2xl font-black ${idx === 0 ? 'claro-text-red' : 'text-gray-700'}`}>{entry.best.toFixed(1)}</span>
                <p className="text-[9px] text-gray-400 uppercase font-black tracking-widest">Melhor Nota</p>
              </div>
            </div>
          )) : (
            <div className="p-12 text-center text-gray-400 italic text-sm">Nenhuma avaliação realizada ainda na sua região.</div>
          )}
        </div>
      </div>
    </div>
  );
};
